window.NEP_2020_MODULES = {"logical_thinking":{"3":{"zoneId":"logical_thinking","classAge":3,"className":"Nursery","pedagogyTier":"play","moduleTitle":"Odd Toy Out & Shape Match","hindiSubtitle":"अनोखी चीज़ पहचानो और आकार मिलाओ","ncertGoalNote":"Foundational observation & visual sorting (early cognitive readiness)","lessons":[{"id":"lt-3-1","title":"Spot What Is Different","hindiTitle":"जो अलग है उसे पहचानो","emojiVisual":"🍎  🍎  ⚽  🍎","explanation":"Three items are yummy red apples. The football is a toy, not a fruit! Finding what looks or works differently trains sharp eyes.","indianExample":"On a fruit plate of mangoes 🥭 🥭 🥭 and one spoon 🥄, the spoon is the odd one out!","funFact":"Little detectives look at shape, color, and use before deciding.","askNyraPrompt":"NYRA, can you give me an easy Nursery odd-one-out puzzle with animals?"},{"id":"lt-3-2","title":"Big & Small Pairs","hindiTitle":"बड़ा और छोटा जोड़ा","emojiVisual":"🐘 Big   vs   🐁 Small","explanation":"Objects around us come in big and small sizes. Matching sizes helps us stack blocks without them falling!","indianExample":"Papa’s big steel katori and baby’s tiny steel katori stack neatly when sorted by size.","funFact":"Sorting toys by size makes cleaning up room super fast!","askNyraPrompt":"NYRA, teach me a playful sorting game for Nursery!"}],"activity":{"kind":"classify","title":"Sort Fruits vs Toys!","instruction":"Tap each card and place it in the Fruit Basket or Toy Box.","leftBucketLabel":"🍎 Yummy Fruits","rightBucketLabel":"🧸 Play Toys","classifyItems":[{"id":"c1","label":"Mango","emoji":"🥭","bucket":"left"},{"id":"c2","label":"Ball","emoji":"⚽","bucket":"right"},{"id":"c3","label":"Banana","emoji":"🍌","bucket":"left"},{"id":"c4","label":"Teddy","emoji":"🧸","bucket":"right"}],"successMessage":"Yay! You sorted every fruit and toy like a super detective!"},"quiz":[{"id":"lt-3-q1","prompt":"Which one is DIFFERENT from the others? 🐶  🐶  🚗  🐶","emoji":"🔎","options":["Car 🚗","Dog 🐶","Both"],"correctAnswer":"Car 🚗","hint":"Look for the one that has wheels instead of paws!","explanation":"Three are puppies and the car has wheels, so Car is the odd one out."},{"id":"lt-3-q2","prompt":"What comes next in the clap pattern? 🔴  🔵  🔴  ___","emoji":"🔴","options":["🔵 Blue","🟢 Green","🟡 Yellow"],"correctAnswer":"🔵 Blue","hint":"Say it aloud: Red, Blue, Red...","explanation":"Red and Blue take turns, so Blue comes after Red!"},{"id":"lt-3-q3","prompt":"Which animal is TINY and fits in your palm?","emoji":"🐾","options":["Ant 🐜","Elephant 🐘","Giraffe 🦒"],"correctAnswer":"Ant 🐜","hint":"Think of the tiniest crawler in the garden.","explanation":"An ant is tiny while elephants and giraffes are huge!"}],"realLifeChallenge":{"title":"Sock & Spoon Sorter","instruction":"Help your parent match 3 pairs of socks by color, or place big spoons together and small spoons together.","familyTip":"Ask your child: \"Why did you put these two together?\" to build reasoning words."},"badge":{"id":"badge-lt-3","title":"Tiny Spotter","emoji":"🔎"}},"4":{"zoneId":"logical_thinking","classAge":4,"className":"LKG","pedagogyTier":"play","moduleTitle":"Color & Shape Patterns","hindiSubtitle":"रंग और आकार की लय पहचानो","ncertGoalNote":"Pattern recognition & simple grouping (Foundational Stage NCF-FS)","lessons":[{"id":"lt-4-1","title":"AB-AB Pattern Train","hindiTitle":"बारी-बारी से पैटर्न ट्रेन","emojiVisual":"🌟 🌙 🌟 🌙 🌟 🌙","explanation":"A pattern repeats in a steady rule! When Sun-Moon-Sun-Moon repeats, you can predict what arrives next without guessing.","indianExample":"Marigold and mango-leaf torans on Indian doors follow a green-orange-green-orange pattern!","funFact":"Our heartbeat lub-dub lub-dub is also a pattern!","askNyraPrompt":"NYRA, make a fun clap-and-tap pattern game for LKG!"},{"id":"lt-4-2","title":"Where Does It Belong?","hindiTitle":"सही जगह पर रखो","emojiVisual":"☔ Rain Gear   vs   ☀️ Sunny Wear","explanation":"Smart thinkers group things by where and when we use them—like rainy umbrellas vs summer cotton caps.","indianExample":"During monsoon in India we pick raincoats and gumboots, not woolen sweaters.","funFact":"Grouping clues help us pack our school bag quickly!","askNyraPrompt":"NYRA, ask me a rainy vs sunny sorting riddle!"}],"activity":{"kind":"experiment","title":"Complete the Toran Pattern!","instruction":"Look at the festive door garland: 🌼 🍃 🌼 🍃 🌼 ___ . Which comes next?","prompt":"Tap the right piece to finish the door toran:","options":[{"label":"Mango Leaf","emoji":"🍃","correct":true,"feedback":"Spot on! Flower, Leaf, Flower, Leaf → Leaf completes the rule!"},{"label":"Flower","emoji":"🌼","correct":false,"feedback":"Two flowers together would break the alternating pattern. Try again!"},{"label":"Balloon","emoji":"🎈","correct":false,"feedback":"A balloon was not part of the toran rule!"}],"successMessage":"Beautiful toran pattern completed!"},"quiz":[{"id":"lt-4-q1","prompt":"Finish the pattern: 🔺  ⭕  🔺  ⭕  ___","emoji":"🔺","options":["🔺 Triangle","🟥 Square","⭐ Star"],"correctAnswer":"🔺 Triangle","hint":"Triangle and Circle take turns!","explanation":"After Circle comes Triangle in the alternating rule."},{"id":"lt-4-q2","prompt":"Which thing flies in the sky like 🐦 and 🦋?","emoji":"☁️","options":["Kite 🪁","Fish 🐟","Bus 🚌"],"correctAnswer":"Kite 🪁","hint":"What floats high in the wind on Makar Sankranti?","explanation":"Birds, butterflies, and kites belong in the sky!"},{"id":"lt-4-q3","prompt":"What do you wear FIRST before putting on shoes?","emoji":"👟","options":["Socks 🧦","Hat 🧢","Watch ⌚"],"correctAnswer":"Socks 🧦","hint":"Think of getting ready for school!","explanation":"Socks go on our feet first, then shoes go over them."}],"realLifeChallenge":{"title":"Make a Spoon-Fork Pattern","instruction":"Arrange 4 spoons and 4 katoris (or 4 crayons of two colors) in an AB-AB line on the table.","familyTip":"Remove one middle item and ask your child which piece is missing."},"badge":{"id":"badge-lt-4","title":"Pattern Builder","emoji":"🎨"}},"5":{"zoneId":"logical_thinking","classAge":5,"className":"UKG","pedagogyTier":"play","moduleTitle":"Step-by-Step Paths & Shadow Match","hindiSubtitle":"कदम-दर-कदम रास्ता और परछाई पहेली","ncertGoalNote":"Sequencing, spatial direction & unplugged logical steps","lessons":[{"id":"lt-5-1","title":"First, Next, Last Steps","hindiTitle":"पहले, फिर और अंत में","emojiVisual":"🌱 Seed  ➡️  💧 Water  ➡️  🌻 Plant","explanation":"Every task follows an order! Just like planting a seed needs soil and water before a flower blooms, thinking step-by-step solves puzzles easily.","indianExample":"Making nimbu-pani needs water, lemon squeeze, and sugar stir in clean order!","funFact":"Even big robots follow tiny \"Step 1, Step 2, Step 3\" directions!","askNyraPrompt":"NYRA, help me practice First-Next-Last step puzzles!"},{"id":"lt-5-2","title":"Guide the Bunny (Unplugged Path)","hindiTitle":"खरगोश को सही रास्ता दिखाओ","emojiVisual":"🐇  ➡️  ➡️  ⬆️  🥕","explanation":"Arrow clues tell a character which way to move—Right ➡️, Left ⬅️, Up ⬆️, Down ⬇️—without touching any computer!","indianExample":"Drawing chalk arrows on the floor to reach your favorite toy is real-life path logic!","funFact":"Planning arrows ahead avoids bumping into walls.","askNyraPrompt":"NYRA, give me an easy arrow-maze riddle to reach a mango!"}],"activity":{"kind":"sequence","title":"Order the Plant Growth Steps!","instruction":"Tap the 3 cards in the exact order a seed grows into a flower (1 → 2 → 3).","sequenceSteps":[{"id":"s1","label":"Put Seed in Soil","emoji":"🌰","order":1},{"id":"s2","label":"Give Water & Sun","emoji":"💧","order":2},{"id":"s3","label":"Flower Blooms!","emoji":"🌻","order":3}],"successMessage":"Perfect sequence! Seed → Water → Flower!"},"quiz":[{"id":"lt-5-q1","prompt":"Bunny is on Box 1. It takes 2 steps ➡️ Right to the carrot. Which way did it turn?","emoji":"🐇","options":["Right ➡️","Down ⬇️","Backwards"],"correctAnswer":"Right ➡️","hint":"Read the arrow carefully!","explanation":"The ➡️ arrow points Right!"},{"id":"lt-5-q2","prompt":"Which shadow outline matches an Umbrella?","emoji":"☂️","options":["Curved dome & hook handle","Four wheels","Sharp triangle"],"correctAnswer":"Curved dome & hook handle","hint":"Look at an open umbrella shape.","explanation":"A curved dome top and J-hook handle match an umbrella."},{"id":"lt-5-q3","prompt":"Pattern challenge: 🟦 🟦 🟨 🟦 🟦 ___","emoji":"🟦","options":["🟨 Yellow","🟦 Blue","🟥 Red"],"correctAnswer":"🟨 Yellow","hint":"Notice it goes two blues, then one yellow!","explanation":"An AAB-AAB pattern puts Yellow after two Blues."}],"realLifeChallenge":{"title":"Floor Toy Treasure Guide","instruction":"Hide a toy in the room and give your family spoken clues like \"Take 3 steps forward, turn right, look under the pillow!\"","familyTip":"Let your child be the \"instruction giver\" so they practice clear directional thinking."},"badge":{"id":"badge-lt-5","title":"Step Explorer","emoji":"🧭"}},"6":{"zoneId":"logical_thinking","classAge":6,"className":"1st Class","pedagogyTier":"foundational","moduleTitle":"Picture Analogies & Clue Sorting","hindiSubtitle":"रिश्ता पहचानो और सुराग से उत्तर खोजो","ncertGoalNote":"Foundational classification, analogies & rule deduction (NIPUN aligned)","lessons":[{"id":"lt-6-1","title":"How Are Two Things Connected?","hindiTitle":"दो चीज़ों का संबंध (Analogy)","emojiVisual":"🐦 : Sky  ::  🐟 : Water","explanation":"An analogy compares relationships! A bird belongs in the sky, just like a fish belongs in water.","indianExample":"Chalk is for a blackboard just as pencil is for a notebook!","funFact":"Spot the link between the first pair before solving the second pair.","askNyraPrompt":"NYRA, give me 2 fun analogy riddles for Class 1!"},{"id":"lt-6-2","title":"Sorting by Two Clues","hindiTitle":"दो सुरागों से छँटाई","emojiVisual":"🟢 Round + Green = Pea 🫛","explanation":"Sometimes one clue is not enough—combining two clues like \"Red AND wearable on head\" narrows down to the exact answer!","indianExample":"Is it sweet AND yellow inside AND grows in summer? Mango!","funFact":"Combining two clues eliminates wrong answers quickly.","askNyraPrompt":"NYRA, play a 2-clue guessing game with me!"}],"activity":{"kind":"classify","title":"Sort: Land vs Water Travel","instruction":"Put each vehicle into Road Travel or Water Travel.","leftBucketLabel":"🛣️ Road Vehicles","rightBucketLabel":"🌊 Water Vessels","classifyItems":[{"id":"c1","label":"Autorickshaw","emoji":"🛺","bucket":"left"},{"id":"c2","label":"Sailboat","emoji":"⛵","bucket":"right"},{"id":"c3","label":"Bicycle","emoji":"🚲","bucket":"left"},{"id":"c4","label":"Ship","emoji":"🚢","bucket":"right"}],"successMessage":"Awesome classification! Road vs Water sorted cleanly."},"quiz":[{"id":"lt-6-q1","prompt":"Glove is to Hand :: Sock is to ___","emoji":"🧦","options":["Foot 🦶","Head 👒","Ear 👂"],"correctAnswer":"Foot 🦶","hint":"Where do you wear socks?","explanation":"Gloves cover hands; socks cover feet!"},{"id":"lt-6-q2","prompt":"Growing shape pattern: ⭐   ⭐⭐   ⭐⭐⭐   ___","emoji":"⭐","options":["4 stars ⭐⭐⭐⭐","2 stars ⭐⭐","1 star ⭐"],"correctAnswer":"4 stars ⭐⭐⭐⭐","hint":"Each group gains 1 more star!","explanation":"1, 2, 3, then 4 stars follow the growing pattern rule."},{"id":"lt-6-q3","prompt":"Clue: It has hands, no fingers, and tells you when school starts!","emoji":"🕰️","options":["Clock ⏰","Chair 🪑","Bat 🏏"],"correctAnswer":"Clock ⏰","hint":"Check the wall in your classroom!","explanation":"A clock has hour and minute hands to tell time."}],"realLifeChallenge":{"title":"2-Clue Kitchen Mystery","instruction":"Pick one kitchen item and give 2 clues (\"It is round AND helps roll rotis\") for your family to guess.","familyTip":"Swap turns so your child learns to ask narrowing yes/no questions."},"badge":{"id":"badge-lt-6","title":"Clue Solver","emoji":"🔍"}},"7":{"zoneId":"logical_thinking","classAge":7,"className":"2nd Class","pedagogyTier":"foundational","moduleTitle":"Mirror Halves & Unplugged Algorithms","hindiSubtitle":"दर्पण सममिति और चरणबद्ध नियम","ncertGoalNote":"Symmetry observation, multi-step routines & rule debugging","lessons":[{"id":"lt-7-1","title":"Mirror Twin Halves (Symmetry)","hindiTitle":"आइने जैसे बराबर भाग","emojiVisual":"🦋  Left Wing  |  Right Wing","explanation":"When you fold a butterfly picture down the middle, both halves match like a mirror twin! Shapes like circles, squares, and leaves often have mirror lines.","indianExample":"Many Kolam and Rangoli designs look identical on the left and right sides!","funFact":"Letters like A, H, M, O have mirror twins, while F and R do not!","askNyraPrompt":"NYRA, help me find which capital letters have mirror symmetry!"},{"id":"lt-7-2","title":"Fixing a Broken Step List (Debugging)","hindiTitle":"गलत क्रम को ठीक करना","emojiVisual":"🐛 Mixed Steps  ➡️  ✅ Clean Order","explanation":"If steps are in the wrong order—\"Eat mango → Wash mango\"—something feels silly! Fixing out-of-order steps is called debugging a plan.","indianExample":"Before cooking rice, washing the rice comes before boiling it on the stove!","funFact":"Checking step order saves mistakes in puzzles, crafts, and school projects.","askNyraPrompt":"NYRA, give me a silly mixed-up daily routine to fix!"}],"activity":{"kind":"sequence","title":"Debug the Sandwich Recipe!","instruction":"Put these 4 steps into the smart, logical order from start to finish.","sequenceSteps":[{"id":"s1","label":"Wash Hands Clean","emoji":"🧼","order":1},{"id":"s2","label":"Take Two Bread Slices","emoji":"🍞","order":2},{"id":"s3","label":"Add Veggies Inside","emoji":"🥒","order":3},{"id":"s4","label":"Enjoy Your Snack!","emoji":"🥪","order":4}],"successMessage":"Bug squashed! Your step-by-step recipe is super clean."},"quiz":[{"id":"lt-7-q1","prompt":"Which butterfly or letter splits into TWO exact mirror halves vertically?","emoji":"🪞","options":["Letter M","Letter F","Letter P"],"correctAnswer":"Letter M","hint":"Fold M right down its middle vertical line!","explanation":"M has identical left and right mirror halves; F and P do not."},{"id":"lt-7-q2","prompt":"Spot the wrong order in getting ready: (1) Wake up (2) Wear shoes (3) Put on socks (4) Walk to bus","emoji":"🚌","options":["Shoes came before socks!","Waking up came first","Bus came last"],"correctAnswer":"Shoes came before socks!","hint":"Can socks go neatly OVER shoes?","explanation":"Steps 2 and 3 must swap: socks always go before shoes!"},{"id":"lt-7-q3","prompt":"Order heights shortest to tallest: Meera (shorter than Kabir), Kabir (shorter than Diya). Who is TALLEST?","emoji":"📏","options":["Diya","Meera","Kabir"],"correctAnswer":"Diya","hint":"Meera < Kabir < Diya.","explanation":"Since Kabir is shorter than Diya and Meera is shorter than Kabir, Diya is tallest."}],"realLifeChallenge":{"title":"Paper Fold Butterfly Mirror","instruction":"Fold a square paper in half, draw half a heart or butterfly wing on the fold, cut carefully with an adult, and open to see symmetry!","familyTip":"Let your child test which household objects (spoon, leaf, mug) look symmetric."},"badge":{"id":"badge-lt-7","title":"Bug Squasher","emoji":"🦋"}},"8":{"zoneId":"logical_thinking","classAge":8,"className":"3rd Class","pedagogyTier":"conceptual","moduleTitle":"Mini Logic Grids & Conditional Rules","hindiSubtitle":"तर्क तालिका और \"यदि-तो\" नियम","ncertGoalNote":"Preparatory deductive reasoning, IF-THEN conditions & grid elimination","lessons":[{"id":"lt-8-1","title":"Using IF–THEN Decision Rules","hindiTitle":"\"अगर-तो\" निर्णय नियम","emojiVisual":"☁️ IF dark clouds  ➡️  THEN pack umbrella ☂️","explanation":"Logical thinking uses IF–THEN conditions: \"IF the traffic signal is red, THEN stop; ELSE IF green, THEN cross safely with an adult.\"","indianExample":"During cricket practice: IF it rains, THEN play indoor carrom; ELSE play outside!","funFact":"Smart decision rules help you pick quickly without confusion.","askNyraPrompt":"NYRA, teach me 2 fun IF-THEN decision riddles for Class 3!"},{"id":"lt-8-2","title":"Elimination Grid Thinking","hindiTitle":"विकल्प हटाकर सही उत्तर खोजना","emojiVisual":"❌ Not Green   ❌ Not Sour   ➡️  Sweet Red Apple 🍎","explanation":"When solving a puzzle with 3 friends and 3 favorite snacks, cross out what CANNOT be true. Whatever remains MUST be the true match!","indianExample":"Aarav hates spicy food and Riya only eats fruit—so samosa goes to Kabir!","funFact":"Crossing out impossible options prevents silly guesses.","askNyraPrompt":"NYRA, create a 3-friend snack logic puzzle for me!"}],"activity":{"kind":"experiment","title":"Solve the 3-Friend Fruit Clue!","instruction":"Clues: (1) Three friends have Mango, Guava, and Banana. (2) Aman never eats yellow fruit. (3) Sara loves bananas. What fruit does Dev have?","prompt":"Use elimination to pick Dev’s fruit:","options":[{"label":"Mango","emoji":"🥭","correct":true,"feedback":"Brilliant! Sara has Banana; Aman can’t have yellow Mango so Aman has green Guava; therefore Dev has Mango!"},{"label":"Guava","emoji":"🍈","correct":false,"feedback":"Check Aman’s clue: Aman avoids yellow Mango and Banana, so Aman gets Guava."},{"label":"Banana","emoji":"🍌","correct":false,"feedback":"Clue 3 says Sara already loves Bananas!"}],"successMessage":"Logical elimination mastered!"},"quiz":[{"id":"lt-8-q1","prompt":"Rule: IF a shape has 4 equal sides AND 4 square corners, THEN score 2 stars. Which shape scores 2 stars?","emoji":"🟥","options":["Square","Triangle","Circle"],"correctAnswer":"Square","hint":"Check both conditions: 4 equal sides + 4 square corners.","explanation":"Only a Square meets both rules!"},{"id":"lt-8-q2","prompt":"Row 1 has [🔴 🔵 🟢]. Row 2 has [🔵 🟢 🔴]. Row 3 needs one of each color without repeating in a column: [🟢 ___ 🔵]. What goes in the middle?","emoji":"🧩","options":["🔴 Red","🔵 Blue","🟢 Green"],"correctAnswer":"🔴 Red","hint":"Look at the middle column: it already has 🔵 and 🟢!","explanation":"Red completes both Row 3 and the middle column without repeats!"},{"id":"lt-8-q3","prompt":"In a line of 5 kids, Asha stands right in the EXACT middle. How many kids stand ahead of her?","emoji":"👧","options":["2 kids","3 kids","4 kids"],"correctAnswer":"2 kids","hint":"Two in front, Asha in spot 3, two behind!","explanation":"In 5 spots (1, 2, [3], 4, 5), spot 3 has 2 kids ahead and 2 behind."}],"realLifeChallenge":{"title":"Write 3 House IF–THEN Rules","instruction":"Create 3 funny or helpful IF–THEN rules for your home (like \"IF shoes are muddy, THEN leave them on the mat\").","familyTip":"Ask your child which rule helps keep study time smooth."},"badge":{"id":"badge-lt-8","title":"Logic Strategist","emoji":"♟️"}},"9":{"zoneId":"logical_thinking","classAge":9,"className":"4th Class","pedagogyTier":"conceptual","moduleTitle":"Loops, Venn Groups & Code Ciphers","hindiSubtitle":"दोहराव नियम, वेन समूह और गुप्त संकेत","ncertGoalNote":"Iterative thinking (loops), overlapping sets & pattern decoding","lessons":[{"id":"lt-9-1","title":"Spotting Repeats (Unplugged Loops)","hindiTitle":"बार-बार दोहराने का आसान नियम","emojiVisual":"🔁 Repeat 3× [Walk 2 steps ➡️ Clap 👏]","explanation":"Instead of writing the same instruction 4 times in a row, logical thinkers group repeated steps into a \"Repeat N times\" shortcut!","indianExample":"Saying \"Do 5 Suryanamaskar rounds\" is much shorter than listing every bend 5 separate times!","funFact":"Spotting loops makes instructions shorter and cleaner.","askNyraPrompt":"NYRA, show me an unplugged dance-step loop puzzle!"},{"id":"lt-9-2","title":"Overlapping Circles (Venn Logic)","hindiTitle":"साझा गुण पहचानना (Venn Circles)","emojiVisual":"⭕ Sweet  ∩  Yellow 🟡  =  Ripe Mango 🥭","explanation":"Two sorting circles can overlap! The middle shared space holds items that obey BOTH rules at once (e.g., Plays Outdoors AND Uses a Ball).","indianExample":"Cricket uses a ball AND is played outdoors, while Chess is indoor and Ludo has no ball.","funFact":"Venn diagrams make comparing two groups super clear!","askNyraPrompt":"NYRA, quiz me on overlapping Venn groups!"}],"activity":{"kind":"experiment","title":"Decode the Letter-Shift Cipher!","instruction":"Secret Rule: Shift each letter 1 step FORWARD (A→B, B→C, C→D...) to make a secret word.","prompt":"Using Shift +1 forward to encode, what original word does secret code \"D B U\" stand for (shift 1 step BACK)?","options":[{"label":"C A T","emoji":"🐱","correct":true,"feedback":"Yes! D-1=C, B-1=A, U-1=T → CAT!"},{"label":"D O G","emoji":"🐶","correct":false,"feedback":"Go 1 letter backward from D, B, U in the alphabet."},{"label":"B A T","emoji":"🏏","correct":false,"feedback":"Check the first letter: 1 step back from D is C!"}],"successMessage":"Cipher cracked with clean pattern decoding!"},"quiz":[{"id":"lt-9-q1","prompt":"What does \"Repeat 3 times: (Step Right, Jump)\" produce in total?","emoji":"🔁","options":["6 actions (3 steps + 3 jumps)","2 actions","9 steps"],"correctAnswer":"6 actions (3 steps + 3 jumps)","hint":"2 actions inside the loop × 3 repeats!","explanation":"Each repeat runs 2 actions, so 3 repeats produce 6 actions in sequence."},{"id":"lt-9-q2","prompt":"Circle A = \"Has Wheels\", Circle B = \"Runs on Electricity\". Which belongs in the OVERLAP?","emoji":"🚆","options":["Electric Metro Train 🚇","Wooden Bull Cart 🐂","Electric Fan 🌀"],"correctAnswer":"Electric Metro Train 🚇","hint":"Look for BOTH wheels AND electricity!","explanation":"A metro train has wheels AND uses electricity; a fan has no road wheels and a cart has no electricity."},{"id":"lt-9-q3","prompt":"All roses are flowers. Some flowers fade fast. Can we be 100% SURE all roses are red?","emoji":"🌹","options":["No—roses can be yellow, pink, or white too!","Yes, definitely","Only in winter"],"correctAnswer":"No—roses can be yellow, pink, or white too!","hint":"Test if a counter-example exists!","explanation":"Finding one yellow rose proves \"all roses are red\" is false!"}],"realLifeChallenge":{"title":"Invent a Secret Family Emoji Code","instruction":"Create a 4-symbol secret note (like 🌟=A, 🌙=E, 🔥=T, 💧=S) and let a parent decode a hidden 3-letter word!","familyTip":"Ask your child to verify every symbol has only ONE letter so the code never confuses."},"badge":{"id":"badge-lt-9","title":"Cipher Master","emoji":"🔐"}},"10":{"zoneId":"logical_thinking","classAge":10,"className":"5th Class","pedagogyTier":"conceptual","moduleTitle":"Flowcharts, Multi-Clue Deduction & Proof","hindiSubtitle":"फ्लोचार्ट, बहु-चरणीय तर्क और कारण विश्लेषण","ncertGoalNote":"Algorithmic flow decomposition, critical deduction & systematic verification","lessons":[{"id":"lt-10-1","title":"Breaking Big Problems Down (Decomposition)","hindiTitle":"बड़ी समस्या को छोटे भागों में बाँटना","emojiVisual":"🎉 School Fair ➡️ [Poster 🎨] + [Stall 🍋] + [Budget 💰]","explanation":"Big challenges look scary only until you split them into 3–4 manageable sub-tasks! Breaking a problem down lets teams check each part cleanly.","indianExample":"Organizing a Republic Day class skit means splitting into Script, Costumes, Props, and Rehearsal!","funFact":"Scientists and architects decompose huge bridges into tested small beams.","askNyraPrompt":"NYRA, help me decompose organizing a school science exhibition stall!"},{"id":"lt-10-2","title":"Cause vs Coincidence Check","hindiTitle":"असली कारण बनाम संयोग की जाँच","emojiVisual":"🍦 Ice-cream sales ⬆️  ≠  ☀️ Sunlight caused by ice-cream!","explanation":"Two events happening on the same day does NOT prove one caused the other! Think carefully: \"Did A cause B, or did a third factor (like hot weather) cause both?\"","indianExample":"Umbrella sales and puddles rise together because RAIN causes both—umbrellas don’t cause rain!","funFact":"Questioning claims politely is the heart of critical thinking.","askNyraPrompt":"NYRA, give me a critical-thinking riddle about cause vs coincidence!"}],"activity":{"kind":"sequence","title":"Plan an Unplugged Library Finder Flowchart!","instruction":"Put the 4 logical steps to check out a library book in clean flowchart order.","sequenceSteps":[{"id":"s1","label":"Search Book Shelf by Subject","emoji":"📚","order":1},{"id":"s2","label":"Check IF Book Is Available","emoji":"🔍","order":2},{"id":"s3","label":"Scan Library Card at Desk","emoji":"🪪","order":3},{"id":"s4","label":"Note Return Date & Read!","emoji":"📅","order":4}],"successMessage":"Structured thinking unlocked! Clean library workflow complete."},"quiz":[{"id":"lt-10-q1","prompt":"Five friends finished a race: Kunal beat Tara. Maya beat Kunal. Tara beat Kabir, and Kabir beat Zoya. Who came 2nd?","emoji":"🏁","options":["Kunal","Maya","Tara"],"correctAnswer":"Kunal","hint":"Rank them 1st to 5th using the clues!","explanation":"Order from 1st to 5th is: Maya (1st) → Kunal (2nd) → Tara (3rd) → Kabir (4th) → Zoya (5th)."},{"id":"lt-10-q2","prompt":"On days when students wear sweaters, hot soup sales go up. What is the TRUE root cause of both?","emoji":"🧣","options":["Cold winter weather","Soup makes people wear sweaters","Sweaters cook soup"],"correctAnswer":"Cold winter weather","hint":"Look for the shared outside condition.","explanation":"Cold weather causes people to wear sweaters AND crave hot soup!"},{"id":"lt-10-q3","prompt":"A frog climbs 3 steps up a wall each day and slips 1 step down each night. At the end of Day 2, what step is it on (starting from 0)?","emoji":"🐸","options":["Step 4","Step 6","Step 2"],"correctAnswer":"Step 4","hint":"Day 1 net gain = 3 - 1 = 2 steps!","explanation":"Day 1 ends at 2; Day 2 climbs to 5 and slips to 4!"}],"realLifeChallenge":{"title":"Draw a Flowchart for Rainy vs Sunny School Morning","instruction":"On paper, draw a start box → a diamond question (\"Is it raining?\") → Yes arrow (raincoat + umbrella) and No arrow (water bottle + cap).","familyTip":"Ask your child to test their flowchart on today’s weather!"},"badge":{"id":"badge-lt-10","title":"Master Thinker","emoji":"🧠"}}},"digital_ai":{"3":{"zoneId":"digital_ai","classAge":3,"className":"Nursery","pedagogyTier":"play","moduleTitle":"Gentle Screens & Happy Eyes","hindiSubtitle":"आँखों की देखभाल और स्क्रीन के सही नियम","ncertGoalNote":"Healthy device habits, posture & screen-break readiness (No coding)","lessons":[{"id":"da-3-1","title":"Clean Hands & Gentle Taps","hindiTitle":"साफ हाथ और प्यार से टैप","emojiVisual":"📱 🧼  ➡️  😊 Happy Device","explanation":"Tablets and phones do not like sticky food or hard banging! Always wipe sticky hands first and tap softly like petting a little kitten.","indianExample":"Keep mango juice and milk glasses far away from Mama or Papa’s phone.","funFact":"A soft finger tap works faster than pushing hard!","askNyraPrompt":"NYRA, tell me a sweet story about taking care of a tablet!"},{"id":"da-3-2","title":"Screen Break = Outdoor Play!","hindiTitle":"स्क्रीन ब्रेक और बाहर खेलना","emojiVisual":"📱 15 mins  ➡️  🌳 Blink & Play!","explanation":"Our eyes need green trees, sunlight, and running games to stay strong! When a parent says \"Time up,\" we smile and go play.","indianExample":"After finishing a short rhyme or puzzle, look far out the window at birds!","funFact":"Blinking keeps our eyes fresh like gentle raindrops.","askNyraPrompt":"NYRA, give me a fun eye-rest stretch rhyme!"}],"activity":{"kind":"classify","title":"Sort: Good Screen Habit vs Oops Habit!","instruction":"Tap each card and place it into Happy Eyes or Oops!","leftBucketLabel":"😊 Happy Habit","rightBucketLabel":"😟 Oops Habit","classifyItems":[{"id":"d1","label":"Ask Parent First","emoji":"👨‍👩‍👧","bucket":"left"},{"id":"d2","label":"Wet Juice Hands","emoji":"🧃","bucket":"right"},{"id":"d3","label":"Rest Eyes & Play","emoji":"🌳","bucket":"left"},{"id":"d4","label":"Screen Near Bed","emoji":"🌙","bucket":"right"}],"successMessage":"Hooray! Your eyes and devices stay super happy!"},"quiz":[{"id":"da-3-q1","prompt":"What should we do BEFORE picking up a tablet after eating?","emoji":"🧼","options":["Wash and dry hands","Keep sticky jam on fingers","Bang the screen"],"correctAnswer":"Wash and dry hands","hint":"Screens hate sticky or wet fingers!","explanation":"Clean, dry hands keep the screen safe and tidy."},{"id":"da-3-q2","prompt":"What is best after finishing a short learning game?","emoji":"🌳","options":["Play outside and rest eyes","Stare closer in the dark","Watch forever"],"correctAnswer":"Play outside and rest eyes","hint":"Eyes love sunlight and running!","explanation":"Balancing play outdoors keeps eyes and body healthy."},{"id":"da-3-q3","prompt":"Who should you ask before opening a new app?","emoji":"🏠","options":["Your parent or teacher","A stranger online","Nobody"],"correctAnswer":"Your parent or teacher","hint":"Grown-ups at home check what is safe!","explanation":"Always check with parents or teachers first."}],"realLifeChallenge":{"title":"20-Step Window Blink Break","instruction":"Look out a window at the farthest tree or cloud you can see, blink gently 5 times, and name its color!","familyTip":"Model putting phones away together during family mealtime."},"badge":{"id":"badge-da-3","title":"Happy Eyes Star","emoji":"👀"}},"4":{"zoneId":"digital_ai","classAge":4,"className":"LKG","pedagogyTier":"play","moduleTitle":"Everyday Helpers & Polite Voice","hindiSubtitle":"स्मार्ट उपकरण और मीठी आवाज़ में बात","ncertGoalNote":"Recognizing everyday technology vs living things & polite voice interaction","lessons":[{"id":"da-4-1","title":"Tools vs Living Friends","hindiTitle":"मशीनें और जीवित दोस्त","emojiVisual":"🐶 Alive & Feels   vs   🤖 Tool That Follows","explanation":"A puppy feels hungry, sleepy, and happy. A speaker or learning app has no heart or tummy—it is a helpful machine made by people!","indianExample":"Your ceiling fan cools the room when switched on, but a pet parrot actually eats and sings!","funFact":"Even friendly learning helpers like NYRA are software tools, not real pets.","askNyraPrompt":"NYRA, explain in simple LKG words what makes you a helper tool!"},{"id":"da-4-2","title":"Kind Words Everywhere","hindiTitle":"हर जगह मीठे शब्द बोलना","emojiVisual":"💬 \"Please show me a star story!\"","explanation":"Saying \"Please\" and \"Thank you\" makes talking with teachers, friends, and even voice helpers cheerful and respectful!","indianExample":"Speaking calmly instead of shouting helps voice tools hear your words clearly.","funFact":"Clear words help both people and voice helpers understand you better.","askNyraPrompt":"NYRA, practice speaking polite learning questions with me!"}],"activity":{"kind":"classify","title":"Sort: Living Friend vs Helpful Machine!","instruction":"Place living beings on the left and machines on the right.","leftBucketLabel":"🐾 Living Being","rightBucketLabel":"⚙️ Helpful Machine","classifyItems":[{"id":"d1","label":"Sparrow Bird","emoji":"🐦","bucket":"left"},{"id":"d2","label":"Washing Machine","emoji":"🧺","bucket":"right"},{"id":"d3","label":"Marigold Plant","emoji":"🌼","bucket":"left"},{"id":"d4","label":"Traffic Light","emoji":"🚦","bucket":"right"}],"successMessage":"Super sorting! You know living beings from machines!"},"quiz":[{"id":"da-4-q1","prompt":"Which one needs food, water, and love to grow?","emoji":"🌱","options":["Little Puppy 🐶","Television 📺","Calculator 🔢"],"correctAnswer":"Little Puppy 🐶","hint":"Machines run on batteries or plugs, not food!","explanation":"A puppy is a living creature; TV and calculator are machines."},{"id":"da-4-q2","prompt":"When a helpful app gives you a hint, why is NYRA NOT a real human teacher?","emoji":"🤖","options":["NYRA is a digital study helper made by engineers","NYRA eats lunch at school","NYRA sleeps on a bed"],"correctAnswer":"NYRA is a digital study helper made by engineers","hint":"Think about how apps work!","explanation":"NYRA is a friendly digital tool built to support your real teachers and parents."},{"id":"da-4-q3","prompt":"What helps a voice helper understand you best?","emoji":"🎙️","options":["Speaking clearly and calmly","Shouting very loudly","Mumbling fast"],"correctAnswer":"Speaking clearly and calmly","hint":"Just like talking to Grandma!","explanation":"Clear, calm speech helps voice helpers hear every word accurately."}],"realLifeChallenge":{"title":"House Machine Scavenger Hunt","instruction":"Walk around one room with a parent and point out 3 helpful machines (fan, fridge, clock) and 2 living things (plant, pet, family)!","familyTip":"Talk about who turns those machines on safely (adults handle electric plugs)."},"badge":{"id":"badge-da-4","title":"Tech Spotter","emoji":"🤖"}},"5":{"zoneId":"digital_ai","classAge":5,"className":"UKG","pedagogyTier":"play","moduleTitle":"Input → Output Magic & Plug Safety","hindiSubtitle":"इनपुट-आउटपुट का जादू और बिजली सुरक्षा","ncertGoalNote":"Unplugged Input-Process-Output thinking & basic electrical/device safety","lessons":[{"id":"da-5-1","title":"Push Button → Something Happens!","hindiTitle":"बटन दबाओ → काम हो जाए","emojiVisual":"🔔 Press Bell (Input)  ➡️  🔊 \"Tring!\" (Output)","explanation":"Every smart machine has an INPUT (what you press or say) and an OUTPUT (what appears or sounds). Tap a piano key → Hear a musical note!","indianExample":"Pressing the school bus horn is Input; hearing \"Beep Beep!\" is Output!","funFact":"On a phone, tapping the Speaker icon is Input; hearing words read aloud is Output!","askNyraPrompt":"NYRA, give me 3 Input-and-Output examples from my kitchen!"},{"id":"da-5-2","title":"Never Touch Plugs or Chargers Alone","hindiTitle":"चार्जर और प्लग से दूर रहना","emojiVisual":"🔌 ⚡  ➡️  ✋ Ask an Adult!","explanation":"Electric sockets and hot chargers are ONLY for grown-ups! If battery is low, hand the tablet to Mama or Papa to plug it in.","indianExample":"Also keep screens away when someone is cooking near gas stoves or water!","funFact":"Unplugging with dry adult hands keeps everyone super safe.","askNyraPrompt":"NYRA, share 2 safety rules for charging phones at home!"}],"activity":{"kind":"experiment","title":"Match the Input to Its Output!","instruction":"If you press the Camera button 📸 on a parent’s phone, what is the Output?","prompt":"Choose the correct Output:","options":[{"label":"It captures a photo!","emoji":"🖼️","correct":true,"feedback":"Yes! Pressing shutter = Input, Saved photo = Output!"},{"label":"It boils milk!","emoji":"🥛","correct":false,"feedback":"Phones cannot cook food!"},{"label":"It turns into a bicycle!","emoji":"🚲","correct":false,"feedback":"Haha, no—phones stay phones!"}],"successMessage":"You understand Input → Output like a pro!"},"quiz":[{"id":"da-5-q1","prompt":"You press the Doorbell button. Hearing \"Ding-Dong!\" is the ___","emoji":"🔔","options":["Output","Battery","Charger"],"correctAnswer":"Output","hint":"What comes OUT after you press?","explanation":"Pressing is Input; the sound coming out is Output!"},{"id":"da-5-q2","prompt":"The tablet shows \"Battery Low 5%\". What should you do?","emoji":"🔋","options":["Give it to a parent to charge safely","Put water on it","Poke the socket yourself"],"correctAnswer":"Give it to a parent to charge safely","hint":"Electric plugs belong to grown-ups!","explanation":"Always let an adult handle chargers and wall sockets."},{"id":"da-5-q3","prompt":"Why should we sit upright while learning on a screen?","emoji":"🪑","options":["So neck and back stay strong and healthy","To break the chair","To sleep faster"],"correctAnswer":"So neck and back stay strong and healthy","hint":"Think of posture!","explanation":"Good sitting posture protects your back, neck, and eyes."}],"realLifeChallenge":{"title":"Find 3 Inputs Around Home","instruction":"Point to 3 buttons or switches at home (with an adult!)—like doorbell, torch switch, or mixer knob—and tell what Output each gives!","familyTip":"Remind children never to touch bare sockets or wet switches."},"badge":{"id":"badge-da-5","title":"Safety & Input Hero","emoji":"⚡"}},"6":{"zoneId":"digital_ai","classAge":6,"className":"1st Class","pedagogyTier":"foundational","moduleTitle":"My Private Info & Kind Online Manners","hindiSubtitle":"निजी जानकारी की सुरक्षा और डिजिटल शिष्टाचार","ncertGoalNote":"Foundational digital citizenship, privacy rules & no-coding computational awareness","lessons":[{"id":"da-6-1","title":"Keep Home Address & Phone Private","hindiTitle":"घर का पता और नंबर गुप्त रखें","emojiVisual":"🔒 Name & Address  vs  🎨 Favorite Color","explanation":"Fun facts like \"I love mangoes\" or \"My favorite color is blue\" are safe to share in class. Private facts like Home Address, School Gate, or Parent Phone Number stay ONLY with family!","indianExample":"Just like we lock our house door at night, we keep our phone number and OTP locked inside family.","funFact":"Secret family numbers are never typed into unknown games!","askNyraPrompt":"NYRA, quiz me on what is safe vs private to share!"},{"id":"da-6-2","title":"How Do Learning Apps Remember What You Practiced?","hindiTitle":"ऐप आपका स्कोर कैसे याद रखता है?","emojiVisual":"📝 Your Score  ➡️  💾 Saved Profile  ➡️  🎯 Easier or Harder Tip","explanation":"Smart apps do not read your mind—they simply look at saved patterns, like noticing you missed 2 questions and offering a helpful hint!","indianExample":"Just like a coach sees you missed a catch and tosses softer balls to help you practice!","funFact":"Humans decide the kind goals; computers only follow pattern rules.","askNyraPrompt":"NYRA, how do you pick easier or harder practice for me?"}],"activity":{"kind":"classify","title":"Safe to Share vs Keep Private!","instruction":"Sort these cards into Public Fun vs Family-Only Private.","leftBucketLabel":"🌈 Safe Fun Fact","rightBucketLabel":"🔒 Family Private","classifyItems":[{"id":"d1","label":"Favorite Fruit","emoji":"🥭","bucket":"left"},{"id":"d2","label":"Home Address","emoji":"🏠","bucket":"right"},{"id":"d3","label":"Hobby: Drawing","emoji":"🎨","bucket":"left"},{"id":"d4","label":"Parent Phone No.","emoji":"📞","bucket":"right"}],"successMessage":"Privacy shield activated! You protected your family info!"},"quiz":[{"id":"da-6-q1","prompt":"A shiny pop-up says: \"Type your home address to win a free toy!\" What do you do?","emoji":"🚨","options":["Close it and tell a parent immediately","Type your home address quickly","Click every button"],"correctAnswer":"Close it and tell a parent immediately","hint":"Never give home addresses to unknown pop-ups!","explanation":"Always tell a trusted adult and never share private details with pop-ups."},{"id":"da-6-q2","prompt":"Which is SAFE to say in a school showcase?","emoji":"🎤","options":["\"My favorite animal is an elephant!\"","\"Here is my mom’s bank PIN!\"","\"Here is my house key photo!\""],"correctAnswer":"\"My favorite animal is an elephant!\"","hint":"Pick the cheerful hobby/interest fact.","explanation":"Hobbies and favorite animals are fun public facts; PINs and keys are private."},{"id":"da-6-q3","prompt":"If a helpful AI companion gives a surprising answer, who should help check it?","emoji":"👩‍🏫","options":["Teacher, parent, or textbook","Nobody—computers never make mistakes","Close your eyes"],"correctAnswer":"Teacher, parent, or textbook","hint":"Computers can sometimes guess wrong!","explanation":"Smart learners verify important answers with parents, teachers, or trusted books."}],"realLifeChallenge":{"title":"Design a Family Tech Agreement Poster","instruction":"Write 3 rules on a sticky note with a parent: (1) Clean hands, (2) No strangers/popups, (3) Screen off 30 mins before sleep.","familyTip":"Put the note near the shared family tablet or study corner."},"badge":{"id":"badge-da-6","title":"Privacy Shield","emoji":"🛡️"}},"7":{"zoneId":"digital_ai","classAge":7,"className":"2nd Class","pedagogyTier":"foundational","moduleTitle":"How AI Spots Patterns & Unplugged Searching","hindiSubtitle":"AI पैटर्न कैसे सीखता है और सुरक्षित खोज","ncertGoalNote":"Demystifying AI pattern learning vs human wisdom + safe search steps","lessons":[{"id":"da-7-1","title":"Training by Examples (Without Coding!)","hindiTitle":"उदाहरणों से सीखना (AI का तरीका)","emojiVisual":"📸 100 Cat Photos  ➡️  🤖 Learns \"Whiskers + Ears\" = Cat!","explanation":"Artificial Intelligence (AI) does NOT think like a human brain. Instead, people show it thousands of labeled examples so it spots patterns like pointy ears and whiskers!","indianExample":"If a machine only saw red apples and never saw a green apple, it might guess wrong on green apples—because data examples matter!","funFact":"Good examples teach helpful tools; tricky gaps make them confuse things.","askNyraPrompt":"NYRA, tell me how an image finder learns mangoes vs bananas!"},{"id":"da-7-2","title":"Kids-Safe Searching & Pop-up Red Flags","hindiTitle":"सुरक्षित खोज और नकली विज्ञापन पहचानना","emojiVisual":"⚠️ \"CLICK NOW FREE PRIZE!!\"  ➡️  🚫 Trap Alarm!","explanation":"When searching for school projects (with a parent!), real study sites look calm and helpful. Flashing \"WIN 1 CRORE NOW!\" buttons are fake traps.","indianExample":"Never click random download buttons or tell OTP numbers to any caller or popup!","funFact":"Pausing for 3 seconds before tapping stops 99% of accidental clicks.","askNyraPrompt":"NYRA, show me 3 clues that a webpage popup is unsafe!"}],"activity":{"kind":"experiment","title":"Test the Fruit Pattern Machine!","instruction":"Suppose an AI helper was ONLY trained on yellow lemons and yellow bananas. Now you show it a GREEN unripe banana. Why might it guess wrong?","prompt":"Pick the smart explanation:","options":[{"label":"It never saw green banana examples in training!","emoji":"🍌","correct":true,"feedback":"Exact hit! AI only spots patterns from the examples it learned from."},{"label":"Because bananas dislike computers","emoji":"😄","correct":false,"feedback":"Fruits have no feelings about computers!"},{"label":"Because green cannot be photographed","emoji":"📷","correct":false,"feedback":"Cameras capture green just fine—the training examples missed it!"}],"successMessage":"Aha! You understand why diverse examples matter in AI!"},"quiz":[{"id":"da-7-q1","prompt":"What helps an AI tool recognize a dog vs a bicycle?","emoji":"🐶","options":["Studying thousands of labeled example pictures","Eating dog biscuits","Magic spells"],"correctAnswer":"Studying thousands of labeled example pictures","hint":"AI learns patterns from examples!","explanation":"Machine learning compares patterns across many labeled examples."},{"id":"da-7-q2","prompt":"Which popup is a RED FLAG you should never click?","emoji":"🚩","options":["\"HURRY! Claim Mystery Gift in 5 Seconds!\"","\"Next Lesson Button\" inside Fun & Learn","\"Pause Audio\" button"],"correctAnswer":"\"HURRY! Claim Mystery Gift in 5 Seconds!\"","hint":"Fake traps always rush you with fake prizes!","explanation":"Urgent fake-prize popups are unsafe tricks—close or call an adult."},{"id":"da-7-q3","prompt":"Which superpower belongs ONLY to humans (not AI)?","emoji":"💛","options":["True kindness, caring, and real-life imagination","Adding 10 numbers quickly","Checking spelling"],"correctAnswer":"True kindness, caring, and real-life imagination","hint":"Machines calculate fast, humans care deeply!","explanation":"Machines process data; only humans truly feel love, empathy, and moral care."}],"realLifeChallenge":{"title":"Play \"Train the Robot\" With Family","instruction":"Draw 4 leaves and 4 flowers on small slips. Mix them up and explain what \"features\" (petals vs veins) your family should look for to sort them!","familyTip":"Connect \"features\" to how helpful apps sort photos or letters."},"badge":{"id":"badge-da-7","title":"Pattern Trainer","emoji":"🧠"}},"8":{"zoneId":"digital_ai","classAge":8,"className":"3rd Class","pedagogyTier":"conceptual","moduleTitle":"Strong Passwords, Prompts & AI Fact-Checking","hindiSubtitle":"मजबूत पासवर्ड, स्पष्ट प्रश्न और तथ्य जाँच","ncertGoalNote":"Responsible digital literacy, clear communication with tools & verification habits","lessons":[{"id":"da-8-1","title":"Asking Clear Questions (Good Prompts)","hindiTitle":"सही और स्पष्ट सवाल पूछना","emojiVisual":"😕 \"Tell space\"   vs   🌟 \"Explain Moon phases for Class 3 with an example\"","explanation":"Whether asking a teacher or a learning assistant like NYRA, giving clear details—your class, topic, and what you find confusing—gives a much better explanation!","indianExample":"Saying \"Explain rainwater harvesting for Class 3 in 3 simple steps\" works far better than just \"water\".","funFact":"Clear thinking creates clear questions!","askNyraPrompt":"NYRA, show me how to turn a messy question into a clear Class 3 question!"},{"id":"da-8-2","title":"Why AI Can Sound Confident Yet Make Mistakes","hindiTitle":"AI कभी-कभी गलत क्यों बोल सकता है?","emojiVisual":"🤖 Guesses Next Best Words  ➡️  🧐 Always Double-Check!","explanation":"Language AIs predict helpful words based on patterns—so occasionally they can mix up a date or fact! Smart students cross-check important homework facts in school books or with teachers.","indianExample":"If an AI says Mumbai is the capital of India, you immediately check your Civics book: No, New Delhi is!","funFact":"YOU are the captain of your learning—never copy blindly!","askNyraPrompt":"NYRA, give me one true statement and one silly wrong fact to verify!"}],"activity":{"kind":"classify","title":"Sort: Strong Passphrase vs Weak Password!","instruction":"Never use easy personal dates or \"123456\"! Sort strong vs weak password ideas.","leftBucketLabel":"🔐 Strong Idea","rightBucketLabel":"🚨 Weak & Unsafe","classifyItems":[{"id":"p1","label":"GreenMango!94","emoji":"🥭","bucket":"left"},{"id":"p2","label":"123456","emoji":"🔓","bucket":"right"},{"id":"p3","label":"BlueKite#Sky","emoji":"🪁","bucket":"left"},{"id":"p4","label":"MyName2018","emoji":"📛","bucket":"right"}],"successMessage":"Awesome! Word-combos + symbols make passwords super tough!"},"quiz":[{"id":"da-8-q1","prompt":"Which question gives the clearest help from a study companion?","emoji":"💬","options":["\"Explain solid, liquid, and gas for Class 3 with kitchen examples.\"","\"Science\"","\"Do everything now\""],"correctAnswer":"\"Explain solid, liquid, and gas for Class 3 with kitchen examples.\"","hint":"Look for topic + grade + example request!","explanation":"Clear context helps any tutor give exact, age-friendly help."},{"id":"da-8-q2","prompt":"Why should you NEVER blindly copy an AI answer without reading it?","emoji":"📖","options":["Because AI can occasionally make factual mistakes and copying skips learning","Because paper melts","Because teachers ban reading"],"correctAnswer":"Because AI can occasionally make factual mistakes and copying skips learning","hint":"Think about verifying facts and growing your own brain!","explanation":"Checking answers with books/teachers keeps facts accurate and builds real understanding."},{"id":"da-8-q3","prompt":"Which detail makes a family password SAFER?","emoji":"🔑","options":["Mixing unrelated words, numbers, and a symbol","Using your birthday alone","Using the word \"password\""],"correctAnswer":"Mixing unrelated words, numbers, and a symbol","hint":"Long + unexpected combos are hardest to guess.","explanation":"Three unrelated words + symbol beats short dates every time!"}],"realLifeChallenge":{"title":"Fact-Check Detective","instruction":"Pick one amazing animal fact you heard recently and verify it in an encyclopedia, school book, or with a teacher/parent!","familyTip":"Ask: \"How do we know this source is trustworthy?\""},"badge":{"id":"badge-da-8","title":"Fact Checker","emoji":"🕵️"}},"9":{"zoneId":"digital_ai","classAge":9,"className":"4th Class","pedagogyTier":"conceptual","moduleTitle":"Deepfakes, Phishing & Real-World AI Uses","hindiSubtitle":"नकली मीडिया पहचानना और दैनिक जीवन में AI","ncertGoalNote":"Evaluating digital media credibility, AI in India & ethical screen use","lessons":[{"id":"da-9-1","title":"AI Around Us in Helpful Ways","hindiTitle":"हमारे आसपास उपयोगी AI उपकरण","emojiVisual":"🌾 Crop Check   🗺️ Traffic Maps   🗣️ Voice Translation","explanation":"In India today, responsible AI helps farmers spot plant diseases from leaf photos, translates school lessons across regional languages, and helps doctors scan X-rays faster—always guided by human experts!","indianExample":"Voice translation tools help people across Tamil, Hindi, Bengali, and Marathi understand public signs.","funFact":"AI works best as a helper tool alongside skilled farmers, doctors, and teachers.","askNyraPrompt":"NYRA, share 2 cool ways AI helps farmers or doctors in India!"},{"id":"da-9-2","title":"Spot Edited Images & Trick Messages","hindiTitle":"बदली हुई तस्वीरें और नकली संदेश पहचानना","emojiVisual":"🖼️ Funny Hands? Weird Shadows?  ➡️  🧐 Pause Before Believing!","explanation":"Today tools can create fake photos or clone voices! Before believing or forwarding a shocking video or WhatsApp message, check trusted news/official sources and inspect shadows, text, and hands.","indianExample":"If a message screams \"Forward to 10 people or lose your account!\"—that is a classic hoax!","funFact":"Not forwarding rumors stops misinformation immediately.","askNyraPrompt":"NYRA, teach me 3 clues to spot a fake forwarded message!"}],"activity":{"kind":"experiment","title":"Inbox Detective: Real School Note vs Phishing Trick!","instruction":"You see this alert: \"URGENT: Your school account closes in 1 hour! Send parent OTP to unknown-prize@xyz now!\"","prompt":"What gives this away as a PHISHING trick?","options":[{"label":"Fake urgency + asking for a secret OTP + weird sender!","emoji":"🚨","correct":true,"feedback":"Sharp eyes! Real schools never ask for bank/phone OTPs via scary links!"},{"label":"It uses capital letters, so it must be true","emoji":"📢","correct":false,"feedback":"Scammers often use ALL CAPS to panic you!"},{"label":"Asking for OTPs online is normal","emoji":"🔓","correct":false,"feedback":"NEVER share an OTP—not even if someone pretends to be from school or a bank!"}],"successMessage":"Phishing trap avoided! Awesome digital judgment!"},"quiz":[{"id":"da-9-q1","prompt":"Which is a POSITIVE, helpful real-world use of AI?","emoji":"🌱","options":["Translating study notes into regional Indian languages","Cloning someone’s voice to trick their grandma","Sending fake prize messages"],"correctAnswer":"Translating study notes into regional Indian languages","hint":"Look for helping people learn or stay healthy.","explanation":"Translation and accessibility tools help millions learn across languages!"},{"id":"da-9-q2","prompt":"What is the smartest rule about shocking viral forwards with no trusted source?","emoji":"✋","options":["Do NOT forward—verify first with parents or trusted sources","Share immediately to all groups","Click the unknown link to check"],"correctAnswer":"Do NOT forward—verify first with parents or trusted sources","hint":"Pause before sharing!","explanation":"Stopping unverified forwards keeps families and communities safe."},{"id":"da-9-q3","prompt":"If a tool creates an image, who is responsible for using it respectfully?","emoji":"🤝","options":["The human user who prompts and shares it","Only the electricity wire","Nobody"],"correctAnswer":"The human user who prompts and shares it","hint":"Tools don’t make ethical choices—people do!","explanation":"Humans are always responsible for fair, honest, and respectful use of tools."}],"realLifeChallenge":{"title":"Family Scam-Check Drill","instruction":"Teach one family elder this golden rule: \"Nobody—no bank, prize, or office—ever needs your OTP or PIN!\"","familyTip":"Celebrate when your child explains WHY urgency and OTP requests are red flags."},"badge":{"id":"badge-da-9","title":"Cyber Guardian","emoji":"🦅"}},"10":{"zoneId":"digital_ai","classAge":10,"className":"5th Class","pedagogyTier":"conceptual","moduleTitle":"AI Bias, Digital Footprint & Ethical Co-Pilot","hindiSubtitle":"डेटा निष्पक्षता, डिजिटल पदचिह्न और नैतिक उपयोग","ncertGoalNote":"Critical AI literacy: fairness/bias, digital footprint & human-in-the-loop ethics","lessons":[{"id":"da-10-1","title":"Fair Data = Fair AI (Understanding Bias)","hindiTitle":"सही और विविध डेटा क्यों ज़रूरी है?","emojiVisual":"🏥 Tested on 1 region only ➡️ Fails elsewhere! ✅ Diverse Data = Fair Help","explanation":"If an AI health or speech app only learns from one accent or one city, it may misunderstand rural dialects or different skin tones! Fairness requires inclusive, respectful data tested by humans.","indianExample":"Voice assistants in India work well only when trained across diverse accents—North, South, East, and Northeast!","funFact":"Checking if a tool works fairly for EVERY child is called ethical AI design.","askNyraPrompt":"NYRA, explain AI bias with a simple school sports-team example!"},{"id":"da-10-2","title":"Your Digital Footprint & Creative Ownership","hindiTitle":"डिजिटल पदचिह्न और ईमानदार श्रेय","emojiVisual":"👣 Every Comment & Post Leaves a Trail • Be Kind & Honest","explanation":"Everything posted or commented online leaves a lasting \"digital footprint.\" Plus, when researching with books or AI helpers, good students write in their OWN words and credit sources honestly!","indianExample":"Copying an essay word-for-word hides your own voice; using AI for ideas and writing yourself builds real skill!","funFact":"Think: \"Would I be proud if my teacher and parents read this comment?\"","askNyraPrompt":"NYRA, how can I use you as a study coach without letting you do my homework for me?"}],"activity":{"kind":"classify","title":"Ethical AI vs Unfair Shortcut!","instruction":"Sort smart study habits from unfair shortcuts.","leftBucketLabel":"🌟 Smart & Ethical","rightBucketLabel":"⚠️ Unfair Shortcut","classifyItems":[{"id":"e1","label":"Ask for Hint & Solve Yourself","emoji":"💡","bucket":"left"},{"id":"e2","label":"Submit AI Essay as Own","emoji":"📄","bucket":"right"},{"id":"e3","label":"Credit Book & Photo Sources","emoji":"📚","bucket":"left"},{"id":"e4","label":"Post Mean Comment Online","emoji":"💬","bucket":"right"}],"successMessage":"Wise digital leader! Ethics + curiosity = unstoppable!"},"quiz":[{"id":"da-10-q1","prompt":"A voice-quiz app understands city English well but fails regional Indian accents. What caused this?","emoji":"🗣️","options":["Training data bias—it missed diverse accents","The microphone dislikes tea","Accents are wrong"],"correctAnswer":"Training data bias—it missed diverse accents","hint":"Remember: tools only learn what examples they saw!","explanation":"Lack of diverse training examples causes biased, uneven performance."},{"id":"da-10-q2","prompt":"What is the BEST way to use an AI companion for a 5th Class science project?","emoji":"🔬","options":["Brainstorm ideas, ask why things happen, and build/write in your own words","Copy its whole essay without reading","Skip testing your experiment"],"correctAnswer":"Brainstorm ideas, ask why things happen, and build/write in your own words","hint":"Use AI as a coach, not a replacement for your brain!","explanation":"Active experimenting and writing in your own words builds true mastery."},{"id":"da-10-q3","prompt":"Before posting a classmate’s photo online, what is the respectful digital-citizenship step?","emoji":"🤝","options":["Get permission from the classmate and their parent","Post without asking","Add a silly caption secretly"],"correctAnswer":"Get permission from the classmate and their parent","hint":"Respect other people’s privacy too!","explanation":"Consent and respect protect everyone’s digital dignity."}],"realLifeChallenge":{"title":"Write Your Own \"AI Study Pledge\"","instruction":"Write 3 honest study promises in your notebook (e.g., \"I ask for hints first, I verify facts in textbooks, I stay kind online\").","familyTip":"Discuss how real-world inventions need human wisdom and ethics."},"badge":{"id":"badge-da-10","title":"Ethical Innovator","emoji":"⚖️"}}},"env_sustainability":{"3":{"zoneId":"env_sustainability","classAge":3,"className":"Nursery","pedagogyTier":"play","moduleTitle":"Green Friends & Saving Every Drop","hindiSubtitle":"पौधों से दोस्ती और पानी की बचत","ncertGoalNote":"Nature wonder, love for trees/animals & closing taps","lessons":[{"id":"ev-3-1","title":"Trees Are Our Shade & Bird Homes","hindiTitle":"पेड़ हमें छाया और पक्षियों को घर देते हैं","emojiVisual":"🌳  =  🐦 Bird Nest + 🍎 Fruit + 🌬️ Fresh Air","explanation":"Trees give cool shade in summer, sweet fruits, and cozy nests for little birds! Patting tree bark gently shows love for Mother Earth.","indianExample":"Neem and Banyan trees in our neighborhood keep the street cool even on sunny afternoons!","funFact":"Never pluck flowers for fun—bees need them for sweet honey!","askNyraPrompt":"NYRA, tell me a sweet Nursery story about a happy mango tree!"},{"id":"ev-3-2","title":"Turn Off the Tap Tight!","hindiTitle":"ब्रश करते समय नल बंद रखें","emojiVisual":"🪥 Brushing? ➡️ 🚰 Tap OFF!   💧 Save Water","explanation":"Clean drinking water is precious for people, puppies, and flowers. Closing the tap while soaping hands or brushing saves buckets of water every week!","indianExample":"Put a little bowl of clean water on the balcony for thirsty sparrows in summer!","funFact":"Tiny drips all day can fill an entire bucket!","askNyraPrompt":"NYRA, sing a short water-saving rhyme for Nursery!"}],"activity":{"kind":"experiment","title":"What Does a Little Plant Need to Grow?","instruction":"Your potted Tulsi plant looks thirsty in the morning. Which helper wakes it up happy?","prompt":"Tap what the plant needs right now:","options":[{"label":"Clean Water & Sunlight","emoji":"💧","correct":true,"feedback":"Yay! Water and warm sunlight help leaves grow bright green!"},{"label":"Soda & Candy","emoji":"🍬","correct":false,"feedback":"Plants don’t drink sugary soda—only clean water!"},{"label":"Dark Cupboard","emoji":"🚪","correct":false,"feedback":"Leaves need sunlight, not a dark cupboard!"}],"successMessage":"Your Tulsi plant is smiling green!"},"quiz":[{"id":"ev-3-q1","prompt":"While rubbing soap on your hands, what should the water tap be?","emoji":"🚰","options":["Turned OFF ✋","Running full blast 🌊","Left open all day"],"correctAnswer":"Turned OFF ✋","hint":"Only open water when rinsing soap!","explanation":"Turning the tap off while soaping saves lots of clean water."},{"id":"ev-3-q2","prompt":"Who builds nests safely up in tree branches?","emoji":"🌳","options":["Birds 🐦","Cars 🚗","Buses 🚌"],"correctAnswer":"Birds 🐦","hint":"Listen for \"cheep-cheep\" in the morning!","explanation":"Trees are safe homes for birds, squirrels, and insects."},{"id":"ev-3-q3","prompt":"Where should a banana peel go after eating?","emoji":"🍌","options":["In the dustbin 🗑️","On the footpath","Under the sofa"],"correctAnswer":"In the dustbin 🗑️","hint":"Keep our home and street clean!","explanation":"Peels on the ground can make someone slip—always use the dustbin."}],"realLifeChallenge":{"title":"Water Patrol Check","instruction":"Be the family \"Tap Guard\" today! Check every bathroom/kitchen tap gently to make sure none are dripping.","familyTip":"Cheer whenever your child remembers to turn off the tap while brushing."},"badge":{"id":"badge-ev-3","title":"Water Saver Cub","emoji":"💧"}},"4":{"zoneId":"env_sustainability","classAge":4,"className":"LKG","pedagogyTier":"play","moduleTitle":"Living vs Non-Living & Clean Parks","hindiSubtitle":"जीवित बनाम निर्जीव और साफ पार्क","ncertGoalNote":"Distinguishing living things & litter-free surroundings","lessons":[{"id":"ev-4-1","title":"Does It Breathe, Eat, and Grow?","hindiTitle":"साँस लेना, खाना और बढ़ना","emojiVisual":"🌻 Grows & Drinks   vs   🪨 Rock Stays Still","explanation":"Plants, pets, ants, and you are LIVING because you grow, breathe, and need food or water! Stones, chairs, and toys are non-living.","indianExample":"Notice how a small rose sapling grows taller each month while a brick stays the exact same size!","funFact":"Even though trees stand in one spot, they are alive and make fresh oxygen for us!","askNyraPrompt":"NYRA, ask me 3 Living vs Non-Living riddles for LKG!"},{"id":"ev-4-2","title":"Love Our Parks & Playground","hindiTitle":"पार्क और खेल का मैदान साफ रखना","emojiVisual":"🏞️ Clean Grass + 🗑️ Bin = Happy Playtime","explanation":"Wrappers dropped in parks hurt birds and cows that might swallow plastic. Carry wrappers back to a bin or home!","indianExample":"Taking a steel tiffin and cloth bag to picnics creates zero plastic litter!","funFact":"Clean parks keep mosquitoes and flies away too.","askNyraPrompt":"NYRA, tell me how keeping plastic off grass protects stray cows and dogs!"}],"activity":{"kind":"classify","title":"Sort: Living vs Non-Living!","instruction":"Put things that grow & breathe on the left, and non-living objects on the right.","leftBucketLabel":"🌱 Living Things","rightBucketLabel":"🪨 Non-Living","classifyItems":[{"id":"v1","label":"Butterfly","emoji":"🦋","bucket":"left"},{"id":"v2","label":"Wooden Chair","emoji":"🪑","bucket":"right"},{"id":"v3","label":"Tulsi Plant","emoji":"🌿","bucket":"left"},{"id":"v4","label":"Toy Train","emoji":"🚂","bucket":"right"}],"successMessage":"Brilliant! You spotted every living friend!"},"quiz":[{"id":"ev-4-q1","prompt":"Which one grows bigger over time?","emoji":"🌱","options":["A baby mango tree","A plastic spoon","A stone"],"correctAnswer":"A baby mango tree","hint":"Which one is alive?","explanation":"A living mango tree drinks water, uses sunlight, and grows tall!"},{"id":"ev-4-q2","prompt":"You finish a biscuit packet in the park and see no bin nearby. What do you do?","emoji":"🏞️","options":["Keep wrapper in bag until you reach a dustbin","Drop it under the swing","Hide it in bushes"],"correctAnswer":"Keep wrapper in bag until you reach a dustbin","hint":"Think of protecting park animals!","explanation":"Carrying litter to the nearest bin keeps parks safe for birds and pets."},{"id":"ev-4-q3","prompt":"What gives us fresh oxygen to breathe every single day?","emoji":"🍃","options":["Green plants and trees","Smoke from chimneys","Plastic bottles"],"correctAnswer":"Green plants and trees","hint":"Think of green leaves in sunlight!","explanation":"Green plants make fresh air for all living creatures."}],"realLifeChallenge":{"title":"Adopt One Potted Plant","instruction":"Pick one plant at home or on your balcony, give it a nickname, and gently water its soil twice this week!","familyTip":"Let your child watch new baby leaves sprout over the week."},"badge":{"id":"badge-ev-4","title":"Park Protector","emoji":"🌿"}},"5":{"zoneId":"env_sustainability","classAge":5,"className":"UKG","pedagogyTier":"play","moduleTitle":"Green & Blue Bins + Seasons of India","hindiSubtitle":"गीला-सूखा कचरा और भारत के मौसम","ncertGoalNote":"Waste segregation basics (Green vs Blue bin) & seasonal care","lessons":[{"id":"ev-5-1","title":"Two Magic Dustbins: Green & Blue","hindiTitle":"हरा (गीला) और नीला (सूखा) कूड़ेदान","emojiVisual":"🥬 Green Bin = Wet Food   |   📦 Blue Bin = Dry Paper/Plastic","explanation":"When we separate wet food waste (banana peels, leftover rice) into the GREEN bin, it turns into rich plant soil (compost)! Dry paper, bottles, and cardboard go in the BLUE bin to be recycled.","indianExample":"Across Indian towns under clean-city drives, green & blue bins make neighborhoods sparkle!","funFact":"Mixing wet peel on dry paper ruins paper recycling!","askNyraPrompt":"NYRA, quiz me on 4 items for Green Bin vs Blue Bin!"},{"id":"ev-5-2","title":"Summer, Monsoon & Winter Care","hindiTitle":"गर्मी, बारिश और सर्दी की देखभाल","emojiVisual":"☀️ Cool Water   🌧️ Raincoat   ❄️ Warm Sweater","explanation":"India enjoys sunny summers, splashing monsoons, and cozy winters! Each season helps different fruits grow—like summer mangoes and winter carrots.","indianExample":"In hot May-June, cotton clothes keep us cool; in monsoon July-August, trees look bright emerald green!","funFact":"Eating seasonal fruits from nearby farms is healthier and fresher!","askNyraPrompt":"NYRA, name one yummy Indian fruit or veggie from summer and winter!"}],"activity":{"kind":"classify","title":"Sort the Green & Blue Bins!","instruction":"Put Wet Food Peels in the Green Bin and Dry Recyclables in the Blue Bin.","leftBucketLabel":"🟢 Green (Wet)","rightBucketLabel":"🔵 Blue (Dry)","classifyItems":[{"id":"w1","label":"Apple Core","emoji":"🍎","bucket":"left"},{"id":"w2","label":"Newspaper","emoji":"📰","bucket":"right"},{"id":"w3","label":"Pea Pods","emoji":"🫛","bucket":"left"},{"id":"w4","label":"Cardboard Box","emoji":"📦","bucket":"right"}],"successMessage":"Clean Hero! Zero wet mess in the dry bin!"},"quiz":[{"id":"ev-5-q1","prompt":"Where do orange peels and tea leaves belong?","emoji":"🍊","options":["Green Wet Bin 🟢","Blue Dry Bin 🔵","On the road"],"correctAnswer":"Green Wet Bin 🟢","hint":"Peels rot naturally into compost!","explanation":"Food & kitchen scraps go in the Green wet-waste bin."},{"id":"ev-5-q2","prompt":"Which season brings dark rain clouds and joyful umbrellas?","emoji":"🌧️","options":["Monsoon","Winter","Summer"],"correctAnswer":"Monsoon","hint":"Think of July-August raindrops!","explanation":"Monsoon rains refill rivers, wells, and farms across India."},{"id":"ev-5-q3","prompt":"What helps save electricity when leaving an empty room?","emoji":"💡","options":["Switch OFF lights and fan","Leave fan running fast","Open fridge door for fun"],"correctAnswer":"Switch OFF lights and fan","hint":"Save power whenever nobody is in the room!","explanation":"Switching off unused lights and fans saves energy and helps the planet."}],"realLifeChallenge":{"title":"Two-Bin Check at Home","instruction":"Help set up or label a wet kitchen scrap bowl and a dry paper/bottle bag at home with a parent!","familyTip":"Let your child sort 3 clean dry items before recycling."},"badge":{"id":"badge-ev-5","title":"Two-Bin Buddy","emoji":"♻️"}},"6":{"zoneId":"env_sustainability","classAge":6,"className":"1st Class","pedagogyTier":"foundational","moduleTitle":"Parts of a Plant & Plastic-Free Habits","hindiSubtitle":"पौधे के भाग और कपड़े के थैले का उपयोग","ncertGoalNote":"EVS foundational plant parts & reducing single-use plastic","lessons":[{"id":"ev-6-1","title":"Root, Stem, Leaf, Flower & Seed","hindiTitle":"जड़, तना, पत्ती, फूल और बीज","emojiVisual":"🌺 Flower → 🍃 Leaf (Kitchen) → 🪵 Stem → 🌱 Roots (Drink Water)","explanation":"Every plant part has a special job! Roots drink water from soil, stems carry water up like a straw, leaves are the \"kitchen\" using sunlight, and flowers make seeds!","indianExample":"When we eat carrots (root), spinach (leaf), or sugarcane (stem), we eat different parts of plants!","funFact":"Leaves look green because of chlorophyll, which catches sunlight!","askNyraPrompt":"NYRA, quiz me on which plant part we eat—carrot vs spinach vs peas!"},{"id":"ev-6-2","title":"Cloth Bag Hero vs Plastic Bag","hindiTitle":"प्लास्टिक की जगह कपड़े का झोला","emojiVisual":"🛍️ Plastic (Pollutes 100s of years)  vs  👜 Jholaa (Used 100s of times!)","explanation":"Thin plastic bags choke drains and hurt stray animals, lasting for decades! Carrying a reusable cloth *jholaa* and steel water bottle cuts plastic waste hugely.","indianExample":"Grandparents carried cloth jholaas to sabzi mandi for generations—that was super eco-smart!","funFact":"One cloth bag replaces hundreds of throwaway plastic bags!","askNyraPrompt":"NYRA, give me 3 easy plastic-free swaps for my school bag!"}],"activity":{"kind":"experiment","title":"Plant Part Job Match!","instruction":"Which part of the plant acts like a \"Kitchen\" making food using sunlight and air?","prompt":"Tap the plant’s food kitchen:","options":[{"label":"Green Leaves","emoji":"🍃","correct":true,"feedback":"Correct! Leaves make food using sunlight, water, and air!"},{"label":"Deep Roots","emoji":"🌱","correct":false,"feedback":"Roots live underground in the dark and drink water & minerals."},{"label":"Bark","emoji":"🪵","correct":false,"feedback":"Stems/bark hold the plant upright and carry water!"}],"successMessage":"Plant scientist badge step complete!"},"quiz":[{"id":"ev-6-q1","prompt":"Which plant part grows UNDER the soil and absorbs water?","emoji":"🌱","options":["Roots","Flowers","Fruits"],"correctAnswer":"Roots","hint":"Roots anchor the plant deep in the ground!","explanation":"Roots hold soil tightly and drink up water and nutrients."},{"id":"ev-6-q2","prompt":"Going to buy vegetables with family! What is the BEST bag to carry?","emoji":"🥕","options":["Reusable cloth or jute bag","5 thin plastic pouches","No bag—drop veggies"],"correctAnswer":"Reusable cloth or jute bag","hint":"Washable and strong!","explanation":"Cloth and jute bags last for years with zero plastic litter."},{"id":"ev-6-q3","prompt":"When we eat palak (spinach), which part of the plant are we eating?","emoji":"🥬","options":["Leaves","Seeds","Roots"],"correctAnswer":"Leaves","hint":"Look at flat green palak!","explanation":"Spinach, coriander, and mint are yummy healthy leaves!"}],"realLifeChallenge":{"title":"Carry the Cloth Jholaa!","instruction":"Keep a folded cloth bag near your front door and remind your parent to carry it on the next grocery or fruit trip!","familyTip":"Count together how many plastic bags you avoided this week."},"badge":{"id":"badge-ev-6","title":"Green Leaf Explorer","emoji":"🍃"}},"7":{"zoneId":"env_sustainability","classAge":7,"className":"2nd Class","pedagogyTier":"foundational","moduleTitle":"The 3 Rs & Friendly Pollinators","hindiSubtitle":"3R (कम, पुनः उपयोग, रीसाइकिल) और परागणकर्ता मित्र","ncertGoalNote":"Reduce-Reuse-Recycle hierarchy & interdependence with bees/butterflies","lessons":[{"id":"ev-7-1","title":"Reduce, Reuse, Recycle in Order!","hindiTitle":"कम करें, फिर से इस्तेमाल करें, रीसाइकिल करें","emojiVisual":"1️⃣ REDUCE (Use Less) ➡️ 2️⃣ REUSE (Use Again) ➡️ 3️⃣ RECYCLE","explanation":"The smartest order is REDUCE first (don’t waste paper!), REUSE second (turn an old jam jar into a pencil holder!), and RECYCLE third (send old newspapers for recycling).","indianExample":"Using both sides of rough notebook pages before buying a new one saves trees!","funFact":"Turning empty glass jars into masala or crayon holders is smart Reusing!","askNyraPrompt":"NYRA, give me 3 creative ways to REUSE old cardboard or jars!"},{"id":"ev-7-2","title":"Thank You Bees & Butterflies!","hindiTitle":"मधुमक्खी और तितली हमारे फसल मित्र","emojiVisual":"🐝 🦋 Visit Flowers ➡️ Share Pollen ➡️ 🥭 🍎 Fruits Grow!","explanation":"Honeybees and butterflies drink sweet nectar and gently carry yellow pollen dust from flower to flower. Without pollinators, mango, apple, and pumpkin plants could not grow fruits!","indianExample":"Planting marigolds and hibiscus in pots welcomes colorful butterflies right to our balcony!","funFact":"1 out of every 3 bites of food we eat depends on pollinators!","askNyraPrompt":"NYRA, explain in Class 2 words how bees help mangoes grow!"}],"activity":{"kind":"classify","title":"Reuse vs Compost Sort!","instruction":"Can you Reuse it directly or Compost it for soil?","leftBucketLabel":"🫙 Reuse at Home","rightBucketLabel":"🪱 Compost for Soil","classifyItems":[{"id":"r1","label":"Clean Glass Jam Jar","emoji":"🫙","bucket":"left"},{"id":"r2","label":"Dry Garden Leaves","emoji":"🍂","bucket":"right"},{"id":"r3","label":"Steel Tiffin Box","emoji":"🍱","bucket":"left"},{"id":"r4","label":"Vegetable Peels","emoji":"🥔","bucket":"right"}],"successMessage":"3R Champion! Smart reuse & natural composting!"},"quiz":[{"id":"ev-7-q1","prompt":"Turning an old shoebox into a craft organizer is an example of:","emoji":"📦","options":["Reusing","Wasting","Burning"],"correctAnswer":"Reusing","hint":"Giving an old item a new second life!","explanation":"Reusing extends an object’s useful life without needing new factory work."},{"id":"ev-7-q2","prompt":"Why are honeybees and butterflies super important for farms?","emoji":"🐝","options":["They pollinate flowers so fruits and seeds can grow","They chew tree trunks","They bring snow"],"correctAnswer":"They pollinate flowers so fruits and seeds can grow","hint":"Think about pollen moving flower to flower!","explanation":"Pollinators help flowering plants form fruits, veggies, and seeds."},{"id":"ev-7-q3","prompt":"Which habit REDUCES paper waste in school?","emoji":"📓","options":["Writing cleanly on both sides of notebook pages","Tearing clean sheets for airplanes","Throwing half-empty notebooks"],"correctAnswer":"Writing cleanly on both sides of notebook pages","hint":"Use every page well!","explanation":"Using both sides cuts paper waste in half."}],"realLifeChallenge":{"title":"Upcycle a Pencil Cup","instruction":"Take an empty clean container/tin box with a parent, wrap it in old colorful magazine paper or yarn, and turn it into a desk organizer!","familyTip":"Celebrate \"zero-cost\" creativity made from reused household materials."},"badge":{"id":"badge-ev-7","title":"3R & Pollinator Ally","emoji":"🐝"}},"8":{"zoneId":"env_sustainability","classAge":8,"className":"3rd Class","pedagogyTier":"conceptual","moduleTitle":"Clean Air, Quiet Streets & Rainwater Harvesting","hindiSubtitle":"स्वच्छ हवा, कम शोर और वर्षा जल संचयन","ncertGoalNote":"Preparatory understanding of pollution types & traditional water conservation","lessons":[{"id":"ev-8-1","title":"Catching Raindrops Where They Fall","hindiTitle":"बारिश के पानी को सहेजना (Rainwater Harvesting)","emojiVisual":"🌧️ Roof Rain  ➡️  Filter Pipe  ➡️  🕳️ Ground Recharge Pit","explanation":"Instead of letting monsoon rain wash away down concrete roads, rainwater harvesting guides clean roof water into storage tanks or deep recharge pits—refilling underground wells for summer!","indianExample":"Rajasthan’s ancient stepwells (*baoris*) and modern rooftops across Bengaluru & Chennai save millions of liters of rain!","funFact":"Even small rooftop pipes can refill groundwater tables!","askNyraPrompt":"NYRA, explain rainwater harvesting for Class 3 in 4 clear steps!"},{"id":"ev-8-2","title":"Air & Noise Pollution Clues","hindiTitle":"वायु और ध्वनि प्रदूषण को समझना","emojiVisual":"🚲 Bicycle = Fresh Air + Quiet   |   📢 Excess Honking = Noise Stress","explanation":"Smoke from burning dry leaves/trash harms lungs and makes air smoggy. Constant loud honking creates noise pollution that scares birds and hurts ears!","indianExample":"Turning off car/scooter engines at long red lights (\"Red Light On, Gaadi Off\") saves fuel AND keeps city air cleaner!","funFact":"Composting fallen autumn leaves instead of burning them protects air AND makes fertilizer!","askNyraPrompt":"NYRA, give me 3 actions kids can suggest to cut air & noise pollution!"}],"activity":{"kind":"sequence","title":"Build a Rooftop Rainwater System!","instruction":"Tap the 4 steps in order from cloud to clean underground water!","sequenceSteps":[{"id":"rw1","label":"Rain Falls on Clean Roof","emoji":"🌧️","order":1},{"id":"rw2","label":"Pipe Guides Water Down","emoji":"🦯","order":2},{"id":"rw3","label":"Sand & Gravel Filter Cleans It","emoji":"🪨","order":3},{"id":"rw4","label":"Stored in Tank or Ground Pit","emoji":"💧","order":4}],"successMessage":"Every monsoon drop saved!"},"quiz":[{"id":"ev-8-q1","prompt":"What is the smartest eco-friendly thing to do with piles of dry fallen leaves?","emoji":"🍂","options":["Put them in a compost pit to make garden manure","Burn them on the roadside","Stuff them in storm drains"],"correctAnswer":"Put them in a compost pit to make garden manure","hint":"Burning leaves creates harmful smoke!","explanation":"Composting leaves keeps air smoke-free and enriches garden soil."},{"id":"ev-8-q2","prompt":"How does rainwater harvesting help cities in summer?","emoji":"🕳️","options":["It refills groundwater and tanks during monsoon for dry months","It makes roads flooded","It wastes rainwater"],"correctAnswer":"It refills groundwater and tanks during monsoon for dry months","hint":"Think of saving monsoon rain underground!","explanation":"Storing rain prevents runoff loss and keeps wells/tanks full longer."},{"id":"ev-8-q3","prompt":"Why should vehicles avoid unnecessary horn blowing near schools and hospitals?","emoji":"🏥","options":["Noise pollution hurts ears, disturbs patients & scatters birds","Horns run on water","Quiet streets slow walking"],"correctAnswer":"Noise pollution hurts ears, disturbs patients & scatters birds","hint":"Think about health and peace!","explanation":"Silence zones protect students’ focus, patients’ rest, and animals."}],"realLifeChallenge":{"title":"Water Bucket Audit","instruction":"Put a small bowl under a leaking tap or collect RO filter waste water in a bucket to water garden plants!","familyTip":"Ask your child how much water was saved for plants in one day."},"badge":{"id":"badge-ev-8","title":"Rainwater Ranger","emoji":"🌧️"}},"9":{"zoneId":"env_sustainability","classAge":9,"className":"4th Class","pedagogyTier":"conceptual","moduleTitle":"Ecosystem Food Webs & Habitat Protection","hindiSubtitle":"पारिस्थितिकी तंत्र और वन्यजीव संरक्षण","ncertGoalNote":"Interconnected food chains, soil health & biodiversity stewardship","lessons":[{"id":"ev-9-1","title":"Every Creature Fits the Web of Life","hindiTitle":"प्रकृति की खाद्य श्रृंखला (Food Web)","emojiVisual":"🌾 Grass ➡️ 🦗 Grasshopper ➡️ 🐸 Frog ➡️ 🐍 Snake ➡️ 🦅 Eagle","explanation":"Plants capture sunlight as Producers; plant-eaters, insect-eaters, and decomposers (like earthworms!) form a balanced chain. Removing even ONE link upsets the whole farm or forest!","indianExample":"Earthworms (*kenchua*) loosen soil naturally—that is why farmers call earthworms their best friend!","funFact":"Frogs help farmers by eating crop-damaging pests naturally!","askNyraPrompt":"NYRA, what happens to crops if too many frogs disappear from a pond?"},{"id":"ev-9-2","title":"Local Biodiversity & Sacred Groves","hindiTitle":"स्थानीय जैव-विविधता और प्रकृति की रक्षा","emojiVisual":"🌳 Sacred Groves • Wetlands • Native Trees = Rich Wildlife","explanation":"Planting NATIVE trees (Neem, Peepal, Jamun, Banyan) feeds local birds, squirrels, and bees far better than decorative non-native lawns. India’s ancient *Devrais* (sacred groves) protected rare plants for centuries!","indianExample":"Chipko movement villagers hugged Himalayan trees to protect hillsides from landslides and flooding!","funFact":"Tree roots weave like a giant net holding mountain soil safely during heavy rain!","askNyraPrompt":"NYRA, tell me the inspiring story of the Chipko movement for Class 4!"}],"activity":{"kind":"classify","title":"Sort: Producers vs Decomposers & Consumers!","instruction":"Place Sun-powered Plant Producers on the left, and Animals/Decomposers on the right.","leftBucketLabel":"☀️ Producers (Plants)","rightBucketLabel":"🦎 Consumers & Worms","classifyItems":[{"id":"f1","label":"Paddy Rice Plant","emoji":"🌾","bucket":"left"},{"id":"f2","label":"Earthworm","emoji":"🪱","bucket":"right"},{"id":"f3","label":"Mango Tree","emoji":"🌳","bucket":"left"},{"id":"f4","label":"Spotted Deer","emoji":"🦌","bucket":"right"}],"successMessage":"Balanced food web sorted cleanly!"},"quiz":[{"id":"ev-9-q1","prompt":"Why are earthworms and fungi called \"Nature’s Recyclers\" (Decomposers)?","emoji":"🪱","options":["They break dead leaves down into rich, fertile soil","They paint tree leaves green","They block sunlight"],"correctAnswer":"They break dead leaves down into rich, fertile soil","hint":"Think of what happens to fallen forest leaves!","explanation":"Decomposers return vital nutrients back to soil so new plants can grow."},{"id":"ev-9-q2","prompt":"In the Chipko Movement in Uttarakhand, what did villagers do to save mountain forests?","emoji":"🌲","options":["Peacefully hugged trees so they would not be cut down","Built plastic fences","Moved to the desert"],"correctAnswer":"Peacefully hugged trees so they would not be cut down","hint":"\"Chipko\" means \"to cling/hug\"!","explanation":"Women and villagers hugged trees to protect forests, soil, and water springs."},{"id":"ev-9-q3","prompt":"Why are wetlands and city lakes super important even if we don’t swim in them?","emoji":"🦢","options":["They soak up floodwater, recharge aquifers & shelter migratory birds","They waste empty land","They create plastic"],"correctAnswer":"They soak up floodwater, recharge aquifers & shelter migratory birds","hint":"Think of sponges during heavy rains!","explanation":"Lakes act like natural flood sponges and rich wildlife sanctuaries."}],"realLifeChallenge":{"title":"Neighborhood Bird & Tree Log","instruction":"Spend 10 minutes outside counting 3 different kinds of birds, insects, or trees near your home and sketch one leaf shape!","familyTip":"Notice how different insects visit flowering vs non-flowering plants."},"badge":{"id":"badge-ev-9","title":"Eco Web Guardian","emoji":"🌳"}},"10":{"zoneId":"env_sustainability","classAge":10,"className":"5th Class","pedagogyTier":"conceptual","moduleTitle":"Clean Energy, Carbon Footprint & Climate Action","hindiSubtitle":"स्वच्छ ऊर्जा, कार्बन पदचिह्न और हरित भविष्य","ncertGoalNote":"Renewable vs fossil energy, climate awareness & student sustainability projects","lessons":[{"id":"ev-10-1","title":"Clean Sun & Wind vs Smoky Coal","hindiTitle":"सौर-पवन ऊर्जा बनाम जीवाश्म ईंधन","emojiVisual":"☀️ Solar Panels  🌬️ Wind Turbines   vs   🏭 Burning Coal","explanation":"Fossil fuels (coal, petrol) took millions of years to form and release heat-trapping smoke when burned, warming our Earth. Solar, wind, and hydro energy replenish naturally and keep skies cleaner!","indianExample":"India’s giant solar parks (like Bhadla in Rajasthan and Cochin’s solar-powered airport!) run on bright sunshine!","funFact":"Cochin International Airport in Kerala was the world’s first airport fully powered by solar energy!","askNyraPrompt":"NYRA, explain how solar panels make electricity cleanly for Class 5!"},{"id":"ev-10-2","title":"Shrinking Our Everyday Carbon Footprint","hindiTitle":"दैनिक आदतों से कार्बन पदचिह्न घटाना","emojiVisual":"🚲 Walk/Cycle Short Trips  🥕 Local Food  🔌 Unplug Idle Devices","explanation":"Your \"carbon footprint\" is the trail of energy used for your rides, electricity, and goods. Walking short distances, sharing carpools/school buses, avoiding food waste, and planting native trees shrink it!","indianExample":"Throwing away food wastes ALL the water, sunshine, and tractor fuel that grew it!","funFact":"Putting ONLY as much food on your thali as you will eat is powerful climate action!","askNyraPrompt":"NYRA, help me list 4 ways my class can run a Zero Food-Waste campaign!"}],"activity":{"kind":"classify","title":"Sort: Renewable Clean Energy vs Non-Renewable Fuels!","instruction":"Separate clean renewable energy sources from exhaustible fossil fuels.","leftBucketLabel":"☀️ Clean Renewable","rightBucketLabel":"⛽ Exhaustible Fuel","classifyItems":[{"id":"en1","label":"Rooftop Solar Panel","emoji":"☀️","bucket":"left"},{"id":"en2","label":"Coal Power","emoji":"🪨","bucket":"right"},{"id":"en3","label":"Windmill Farm","emoji":"🌬️","bucket":"left"},{"id":"en4","label":"Diesel Petrol","emoji":"⛽","bucket":"right"}],"successMessage":"Clean-energy strategist! You know our green future!"},"quiz":[{"id":"ev-10-q1","prompt":"Why is solar energy called \"Renewable\"?","emoji":"☀️","options":["Sunlight naturally keeps arriving every day without running out soon","It comes in plastic bottles","It releases thick black smoke"],"correctAnswer":"Sunlight naturally keeps arriving every day without running out soon","hint":"Contrast sunlight with coal dug from underground.","explanation":"Solar and wind replenish daily without emitting greenhouse smoke."},{"id":"ev-10-q2","prompt":"How does wasting half your lunch plate hurt the environment too?","emoji":"🍛","options":["It wastes all the water, farm soil energy, and transport fuel spent growing it","Only the plate feels sad","It makes clouds heavier"],"correctAnswer":"It wastes all the water, farm soil energy, and transport fuel spent growing it","hint":"Trace the hidden resources behind one meal!","explanation":"Saving food conserves irrigation water, energy, and lowers methane waste."},{"id":"ev-10-q3","prompt":"For a 1 km trip to a neighborhood shop, which travel choice leaves the SMALLEST carbon footprint?","emoji":"🚲","options":["Walking or riding a bicycle","Driving an empty big SUV alone","Running two cars"],"correctAnswer":"Walking or riding a bicycle","hint":"Human pedal power burns zero fuel!","explanation":"Walking and cycling produce zero tailpipe emissions and build fitness!"}],"realLifeChallenge":{"title":"Clean-Plate & Unplug Challenge","instruction":"For 3 days, serve smaller portions first (take seconds only if hungry) AND check TV/charger switches before bedtime!","familyTip":"Track 1 week of food-waste-free dinners as a family gold star."},"badge":{"id":"badge-ev-10","title":"Solar Changemaker","emoji":"🌞"}}},"financial_literacy":{"3":{"zoneId":"financial_literacy","classAge":3,"className":"Nursery","pedagogyTier":"play","moduleTitle":"Meet Coins, Gullak & Sharing","hindiSubtitle":"सिक्के, गुल्लक और साझा करने की खुशी","ncertGoalNote":"Early coin awareness, piggy-bank saving habit & caring for toys","lessons":[{"id":"fl-3-1","title":"Shiny Coins in Our Gullak","hindiTitle":"मेरी प्यारी गुल्लक और सिक्के","emojiVisual":"🪙  ➡️  🐷 Gullak (Piggy Bank)","explanation":"Coins are shiny round metal pieces grown-ups use to buy milk, apples, and crayons! Putting a coin safely in your Gullak keeps it ready for a special day.","indianExample":"Clay *mitti ki gullak* from Indian melas teaches us to save little coins cheerfully!","funFact":"Taking care of our toys so they don’t break saves money too!","askNyraPrompt":"NYRA, tell me a tiny Nursery story about a clay Gullak!"},{"id":"fl-3-2","title":"Real Coins vs Play Stones","hindiTitle":"असली सिक्का बनाम खेलने के पत्थर","emojiVisual":"🪙 Shop Money   vs   🪨 Garden Pebble","explanation":"Shops give bananas or books only for real Indian coins and notes—not leaves or pebbles! Coins are for grown-ups to hold safely, NEVER put in our mouth.","indianExample":"Indian coins have the Lion Capital picture carved on one side!","funFact":"Always wash hands after holding coins because many hands touched them.","askNyraPrompt":"NYRA, remind me why we never put coins near our mouth!"}],"activity":{"kind":"classify","title":"What Goes Inside Your Gullak?","instruction":"Sort shiny saving coins vs play toys so your Gullak stays tidy!","leftBucketLabel":"🪙 Save in Gullak","rightBucketLabel":"🧸 Put in Toy Box","classifyItems":[{"id":"m1","label":"₹1 Coin","emoji":"🪙","bucket":"left"},{"id":"m2","label":"Rubber Duck","emoji":"🦆","bucket":"right"},{"id":"m3","label":"₹5 Coin","emoji":"🟡","bucket":"left"},{"id":"m4","label":"Building Block","emoji":"🧱","bucket":"right"}],"successMessage":"Clink-clink! Your Gullak is safe and tidy!"},"quiz":[{"id":"fl-3-q1","prompt":"What is a Gullak (piggy bank) used for?","emoji":"🐷","options":["Saving coins safely for later","Washing dishes","Throwing balls"],"correctAnswer":"Saving coins safely for later","hint":"Drop shiny coins through the little slot!","explanation":"A Gullak helps us save coins little by little."},{"id":"fl-3-q2","prompt":"What should you NEVER do with metal coins?","emoji":"⚠️","options":["Put them in your mouth","Save them with parents","Count them gently"],"correctAnswer":"Put them in your mouth","hint":"Think of choking and germs safety!","explanation":"Coins are dirty and dangerous in mouths—only handle with clean hands."},{"id":"fl-3-q3","prompt":"Which animal emblem is printed on Indian Rupee coins?","emoji":"🇮🇳","options":["Ashoka Lion Capital","Penguin","Dinosaur"],"correctAnswer":"Ashoka Lion Capital","hint":"Look at any ₹1 or ₹5 coin with a parent!","explanation":"Indian coins proudly show the 3-lion Ashoka Pillar emblem."}],"realLifeChallenge":{"title":"Coin Feel & Wash","instruction":"Ask a parent to show you a ₹1 and ₹5 coin on the palm of your hand—spot the Lions and numbers, then wash hands after!","familyTip":"Let your child drop 1 saved coin into a jar or clay gullak."},"badge":{"id":"badge-fl-3","title":"Gullak Cub","emoji":"🐷"}},"4":{"zoneId":"financial_literacy","classAge":4,"className":"LKG","pedagogyTier":"play","moduleTitle":"Must-Have Needs vs Fun Wants","hindiSubtitle":"ज़रूरी चीज़ें (Needs) और इच्छाएँ (Wants)","ncertGoalNote":"Distinguishing basic daily needs vs extra wants at play level","lessons":[{"id":"fl-4-1","title":"Healthy Needs Come First","hindiTitle":"सबसे पहले ज़रूरी चीज़ें","emojiVisual":"🥛 Milk + 👟 School Shoes = NEEDS   vs   🎈 Extra Balloon = WANT","explanation":"NEEDS are things we must have to stay healthy, safe, and learn—like drinking water, roti-dal, shoes, and warm clothes! WANTS are fun extras like a 5th toy car or cotton candy.","indianExample":"When shopping with Mama, food and school notebooks go into the basket before extra stickers!","funFact":"Taking care of needs first keeps everyone happy and strong.","askNyraPrompt":"NYRA, ask me 3 Needs vs Wants riddles for LKG!"},{"id":"fl-4-2","title":"Why Shops Cannot Give Everything Free","hindiTitle":"दुकान पर आदान-प्रदान","emojiVisual":"👨‍🌾 Farmer & Shopkeeper Work Hard  ➡️  🪙 Fair Exchange","explanation":"Farmers grow apples, tailors stitch uniforms, and bakers make bread with hard work! Paying with rupees thanks them fairly for their work.","indianExample":"Saying \"Thank you Uncle/Aunty\" when buying vegetables respects their hard work too!","funFact":"Money helps people trade smoothly without carrying goats or sacks of wheat everywhere!","askNyraPrompt":"NYRA, tell me a funny story about why we use rupees instead of trading goats!"}],"activity":{"kind":"classify","title":"Sort: Daily Need vs Fun Want!","instruction":"Place essential Needs on the left and extra Wants on the right.","leftBucketLabel":"🥗 Daily Need","rightBucketLabel":"🎈 Fun Want","classifyItems":[{"id":"n1","label":"Clean Water","emoji":"💧","bucket":"left"},{"id":"n2","label":"Ice Cream Cone","emoji":"🍦","bucket":"right"},{"id":"n3","label":"School Uniform","emoji":"👕","bucket":"left"},{"id":"n4","label":"Glitter Sticker","emoji":"✨","bucket":"right"}],"successMessage":"Wise shopper! Needs first, wants as treats!"},"quiz":[{"id":"fl-4-q1","prompt":"Which item is a true DAILY NEED for every child?","emoji":"🍚","options":["Healthy lunch and clean water","A giant remote-control drone","Ten extra party hats"],"correctAnswer":"Healthy lunch and clean water","hint":"What keeps your body healthy every day?","explanation":"Nutritious food and clean drinking water are essential needs."},{"id":"fl-4-q2","prompt":"Why do families pay money to the vegetable seller?","emoji":"🥬","options":["To pay fairly for farmers’ and sellers’ hard work","Because coins are too heavy","To lose pockets"],"correctAnswer":"To pay fairly for farmers’ and sellers’ hard work","hint":"Growing and transporting veggies takes effort!","explanation":"Rupees reward the time and work of farmers, drivers, and shopkeepers."},{"id":"fl-4-q3","prompt":"You already have 3 working crayons at home. Buying a 4th fancy pack is a:","emoji":"🖍️","options":["Want","Medical Need","Emergency"],"correctAnswer":"Want","hint":"Do you already have what you need to draw?","explanation":"Since you already have crayons, an extra fancy pack is a Want!"}],"realLifeChallenge":{"title":"Name 2 Needs in Your Fridge","instruction":"Open the kitchen cupboard or fridge with a parent and name 2 healthy Needs (milk, dal, atta) and 1 special weekend treat!","familyTip":"Praise your child when they pause and say \"I already have this toy at home!\""},"badge":{"id":"badge-fl-4","title":"Wise Pick Star","emoji":"🌟"}},"5":{"zoneId":"financial_literacy","classAge":5,"className":"UKG","pedagogyTier":"play","moduleTitle":"Indian Rupee Notes & Earning Through Work","hindiSubtitle":"भारतीय रुपये के नोट और मेहनत की कमाई","ncertGoalNote":"Recognizing Rupee symbol ₹, notes vs coins & respecting work","lessons":[{"id":"fl-5-1","title":"Look at the Rupee Sign ₹ & Notes","hindiTitle":"रुपये का चिह्न ₹ और रंग-बिरंगे नोट","emojiVisual":"₹10 Brown  |  ₹20 Greenish-Yellow  |  ₹50 Sky Blue  |  ₹100 Lavender","explanation":"Indian money is called the Rupee, written with the proud sign ₹! Notes come in different colors and numbers so everyone—even elders—can spot them easily.","indianExample":"Our currency notes show Mahatma Gandhi’s portrait and famous Indian landmarks on the back!","funFact":"The ₹ symbol combines Hindi \"र\" and English \"R\"!","askNyraPrompt":"NYRA, tell me the colors of ₹10, ₹20, ₹50, and ₹100 Indian notes!"},{"id":"fl-5-2","title":"Where Does Money Come From?","hindiTitle":"पैसे मेहनत और काम से आते हैं","emojiVisual":"👩‍🏫 Teach • 👨‍⚕️ Heal • 🌾 Farm • 👩‍🔧 Build  ➡️  Earn Income","explanation":"Money does NOT appear magically from ATM walls! Adults earn income by working hard—teaching, farming, driving, building, designing, or running shops. ATMs only hold money already earned and saved in a bank!","indianExample":"Even the bus driver and vegetable auntie earn honestly by serving neighbors!","funFact":"Bank accounts keep earned rupees safe until families need them.","askNyraPrompt":"NYRA, explain in UKG words how an ATM really works!"}],"activity":{"kind":"experiment","title":"How Does an ATM Give Money?","instruction":"Your cousin thinks an ATM machine makes free magic money for anyone! What is true?","prompt":"Pick the true fact:","options":[{"label":"It only gives money your family earned and saved in their bank!","emoji":"🏦","correct":true,"feedback":"Yes! You can only withdraw money already deposited in your bank account!"},{"label":"An ATM prints endless free cash for everyone","emoji":"🪄","correct":false,"feedback":"Nope! If a bank account is empty, the ATM gives zero!"},{"label":"It turns plastic cards into chocolate","emoji":"🍫","correct":false,"feedback":"Haha, nice wish, but debit cards link to bank savings!"}],"successMessage":"Smart truth unlocked about ATMs and saving!"},"quiz":[{"id":"fl-5-q1","prompt":"Which symbol stands for Indian Rupees?","emoji":"🇮🇳","options":["₹","$","€"],"correctAnswer":"₹","hint":"Notice the Hindi र + R shape!","explanation":"₹ is India’s official Rupee symbol."},{"id":"fl-5-q2","prompt":"Whose smiling portrait appears on all modern Indian Rupee notes?","emoji":"💵","options":["Mahatma Gandhi","King Ashoka","A cartoon bear"],"correctAnswer":"Mahatma Gandhi","hint":"The Father of the Nation!","explanation":"Mahatma Gandhi’s portrait helps identify genuine Indian banknotes."},{"id":"fl-5-q3","prompt":"Which note has HIGHER value—a ₹50 note or a ₹10 note?","emoji":"⚖️","options":["₹50 note","₹10 note","Both are equal"],"correctAnswer":"₹50 note","hint":"Compare 50 vs 10!","explanation":"₹50 equals five ₹10 notes, so ₹50 buys more."}],"realLifeChallenge":{"title":"Spot 3 Jobs That Help Our Street","instruction":"Name 3 people in your neighborhood who earn by helping (milk seller, sweeper uncle, teacher, tailor) and greet one warmly!","familyTip":"Connect dignified hard work to honest earning."},"badge":{"id":"badge-fl-5","title":"Rupee Explorer","emoji":"💵"}},"6":{"zoneId":"financial_literacy","classAge":6,"className":"1st Class","pedagogyTier":"foundational","moduleTitle":"Coin Combos, Price Tags & Smart Waiting","hindiSubtitle":"सिक्कों के जोड़े, कीमत पर्ची और धैर्य से बचत","ncertGoalNote":"Reading price tags, combining ₹1/₹2/₹5/₹10 coins & delayed gratification","lessons":[{"id":"fl-6-1","title":"Reading a Price Tag & Checking Change","hindiTitle":"कीमत पढ़ना और सही सिक्के चुनना","emojiVisual":"✏️ Pencil = ₹5   +   🧽 Eraser = ₹5   =   One ₹10 Coin!","explanation":"Every item in a shop shows a Price Tag in ₹! Matching coins to pay the exact price—or checking if ₹10 pays for a ₹7 notebook—makes you a super smart shopper.","indianExample":"Two ₹5 coins make ₹10, and five ₹2 coins also make ₹10!","funFact":"Always check price tags BEFORE taking something to the counter!","askNyraPrompt":"NYRA, give me 2 fun Rupee coin-combo puzzles for Class 1!"},{"id":"fl-6-2","title":"Save a Little Today for a Bigger Goal","hindiTitle":"बड़े लक्ष्य के लिए छोटी-छोटी बचत","emojiVisual":"₹5 today + ₹5 next week + ₹5 later ➡️ 📚 Big Storybook!","explanation":"Spending every coin immediately on small candies leaves nothing for big dreams! Waiting patiently lets small coins grow into a storybook, paintbox, or football.","indianExample":"Saving ₹10 every Sunday for a month builds ₹40 by month-end!","funFact":"Waiting just 2 days before buying an extra toy helps check if you still want it!","askNyraPrompt":"NYRA, help me plan a savings goal for a ₹30 storybook!"}],"activity":{"kind":"experiment","title":"Pay Exact Rupees at the Toy Shop!","instruction":"A shiny spinning top costs ₹15! Which exact combination of a note & coin pays ₹15?","prompt":"Tap the exact ₹15 payment:","options":[{"label":"One ₹10 note + One ₹5 coin","emoji":"🪙","correct":true,"feedback":"10 + 5 = ₹15! Exact change!"},{"label":"One ₹10 note + One ₹2 coin","emoji":"💰","correct":false,"feedback":"10 + 2 = ₹12—that is ₹3 short!"},{"label":"One ₹20 note","emoji":"💵","correct":false,"feedback":"₹20 is too much without getting ₹5 change back!"}],"successMessage":"Shopkeeper gives you a big gold star for exact pay!"},"quiz":[{"id":"fl-6-q1","prompt":"How many ₹2 coins together equal ONE ₹10 coin?","emoji":"🪙","options":["5 coins","2 coins","10 coins"],"correctAnswer":"5 coins","hint":"Skip count by 2s: 2, 4, 6, 8, 10!","explanation":"Five ₹2 coins make 2+2+2+2+2 = ₹10."},{"id":"fl-6-q2","prompt":"An eraser costs ₹4. You hand the shopkeeper a ₹10 note. How much change comes back?","emoji":"🧽","options":["₹6","₹4","₹14"],"correctAnswer":"₹6","hint":"10 minus 4!","explanation":"10 - 4 = ₹6 change returned to you."},{"id":"fl-6-q3","prompt":"You want a ₹40 paint set and have ₹15 saved. What is the BEST plan?","emoji":"🎨","options":["Wait and save ₹25 more patiently","Cry at the shop","Throw away your ₹15"],"correctAnswer":"Wait and save ₹25 more patiently","hint":"Patient saving reaches big goals!","explanation":"Goal-based saving turns small amounts into things you truly treasure."}],"realLifeChallenge":{"title":"Check 2 Price Tags at Home","instruction":"Check the MRP (Maximum Retail Price) printed on a biscuit packet or toothpaste box at home with a parent!","familyTip":"Explain that MRP means a shop cannot charge more than that printed rupee price."},"badge":{"id":"badge-fl-6","title":"Smart Shopper","emoji":"🛍️"}},"7":{"zoneId":"financial_literacy","classAge":7,"className":"2nd Class","pedagogyTier":"foundational","moduleTitle":"Making a Budget Jar & Comparing Value","hindiSubtitle":"बजट के 3 डिब्बे और सही कीमत तुलना","ncertGoalNote":"Save-Spend-Share jars, shopping lists vs impulse buys & value comparison","lessons":[{"id":"fl-7-1","title":"The 3-Jar Rule: Save, Spend, Share","hindiTitle":"तीन डिब्बों का नियम: बचत, खर्च और मदद","emojiVisual":"🏦 SAVE (Future)  |  🛒 SPEND (Small Need)  |  🤝 SHARE (Kindness)","explanation":"When you receive gift money on festivals like Diwali or birthdays, splitting it into 3 jars builds wisdom: most goes to SAVE, a bit to SPEND, and a small coin to SHARE with someone in need!","indianExample":"Using your Share jar to buy winter socks or dog biscuits for a street puppy spreads double joy!","funFact":"Even ₹5 from ₹50 into Share grows a generous heart!","askNyraPrompt":"NYRA, help me split ₹100 birthday money into Save, Spend, and Share jars!"},{"id":"fl-7-2","title":"Shopping List Beats Impulse Traps","hindiTitle":"खरीदारी की सूची बनाकर चलना","emojiVisual":"📝 Written List = Stay Focused  |  🍭 Counter Candy = Impulse Trap!","explanation":"Shops put bright toys and candies right near the billing counter so you grab them without planning—that is an \"impulse buy\"! Sticking to a home shopping list saves both money and tummy aches.","indianExample":"Check the pantry BEFORE shopping so you don’t accidentally buy 2 extra packs of salt!","funFact":"Comparing two brands by weight and price shows real value!","askNyraPrompt":"NYRA, why do supermarkets put chocolates right next to the cash counter?"}],"activity":{"kind":"classify","title":"Planned List vs Impulse Trap!","instruction":"Sort items written on the Family List vs sudden counter grabs.","leftBucketLabel":"📝 Planned List","rightBucketLabel":"⚡ Impulse Trap","classifyItems":[{"id":"b1","label":"A4 Science Notebook","emoji":"📓","bucket":"left"},{"id":"b2","label":"Plastic Toy at Billing","emoji":"🦖","bucket":"right"},{"id":"b3","label":"Whole Wheat Atta","emoji":"🌾","bucket":"left"},{"id":"b4","label":"Fizzy Sugar Candy","emoji":"🍭","bucket":"right"}],"successMessage":"Budget pro! Your wallet stays strong!"},"quiz":[{"id":"fl-7-q1","prompt":"In the 3-Jar method (Save, Spend, Share), what is the \"Share\" jar for?","emoji":"🤝","options":["Helping a person, animal, or community in need","Buying extra video games","Hiding broken pencils"],"correctAnswer":"Helping a person, animal, or community in need","hint":"Sharing creates community kindness!","explanation":"The Share jar builds empathy and generosity from childhood."},{"id":"fl-7-q2","prompt":"Pack A has 4 pencils for ₹20. Pack B has 2 pencils of the SAME quality for ₹16. Which gives MORE value per rupee?","emoji":"✏️","options":["Pack A (₹5 per pencil)","Pack B (₹8 per pencil)","Pack B is cheaper per pencil"],"correctAnswer":"Pack A (₹5 per pencil)","hint":"Find the cost of 1 pencil in each pack: 20÷4 vs 16÷2!","explanation":"Pack A costs ₹5 per pencil while Pack B costs ₹8 per pencil!"},{"id":"fl-7-q3","prompt":"What is the easiest way to avoid buying junk near the billing counter?","emoji":"📝","options":["Carry a written shopping list and stick to it","Never look at prices","Shop when super hungry"],"correctAnswer":"Carry a written shopping list and stick to it","hint":"Plan before entering the shop!","explanation":"A checklist keeps families focused on real needs."}],"realLifeChallenge":{"title":"Write Next Grocery List With Parents","instruction":"Help check kitchen shelves and write 5 needed items on paper before the next market trip!","familyTip":"Let your child cross off each item once placed in the basket."},"badge":{"id":"badge-fl-7","title":"Three-Jar Planner","emoji":"🫙"}},"8":{"zoneId":"financial_literacy","classAge":8,"className":"3rd Class","pedagogyTier":"conceptual","moduleTitle":"Weekly Allowance Budgeting & Bills","hindiSubtitle":"साप्ताहिक बजट और बिल रसीद समझना","ncertGoalNote":"Planning a mini budget, checking shop bills & spotting hidden fees","lessons":[{"id":"fl-8-1","title":"How a Mini Budget Balances Income & Expenses","hindiTitle":"आय और खर्च का संतुलन (Budget)","emojiVisual":"💵 Available ₹100  ➡️  📚 Books ₹50 + 🎨 Art ₹30 + 🐷 Save ₹20 = ₹100!","explanation":"A budget is a simple plan for EVERY rupee before you spend it! Total spending + savings must NEVER exceed your available money—otherwise you end up borrowing.","indianExample":"Planning ₹200 for a school book fair (1 storybook ₹120, 1 bookmark ₹20, ₹60 saved back) stops overspending!","funFact":"Checking a printed bill ensures you were only charged for items you actually took!","askNyraPrompt":"NYRA, help me plan a ₹150 budget for a school stationery shopping trip!"},{"id":"fl-8-2","title":"Fixed Expenses vs Surprise Costs","hindiTitle":"तय खर्च बनाम अचानक खर्च","emojiVisual":"🚌 School Bus Monthly Fee (Fixed)  vs  🩺 Broken Bat / Fever Medicine (Emergency)","explanation":"Every month, families pay regular *fixed bills* (electricity, school fee, milk, internet) AND keep an \"Emergency Buffer\" aside for surprise repairs or doctor visits.","indianExample":"Setting aside savings in a bank helps families handle surprises smoothly without panic.","funFact":"Even ₹20 left aside every week becomes an emergency safety cushion!","askNyraPrompt":"NYRA, explain why families keep an emergency savings jar or bank fund!"}],"activity":{"kind":"experiment","title":"Balance the ₹100 Fair Budget!","instruction":"You have ₹100 for the school craft fair. You already bought glue & chart paper for ₹65. Which combo fits INSIDE your remaining ₹35?","prompt":"Choose the combo that fits your budget cleanly:","options":[{"label":"Stickers ₹20 + Save ₹15","emoji":"✅","correct":true,"feedback":"₹65 + ₹20 + ₹15 = ₹100! Perfect budget balance!"},{"label":"Toy Whistle ₹45","emoji":"🚨","correct":false,"feedback":"₹65 + ₹45 = ₹110—you went ₹10 over budget!"},{"label":"Two Badges ₹40","emoji":"❌","correct":false,"feedback":"₹40 is more than your ₹35 left!"}],"successMessage":"Budget balanced to the exact rupee!"},"quiz":[{"id":"fl-8-q1","prompt":"You have ₹120. After buying a ₹75 storybook and a ₹25 geometry box, how much can you still put into savings?","emoji":"🧮","options":["₹20","₹45","₹10"],"correctAnswer":"₹20","hint":"Spent = 75 + 25 = ₹100; remaining from 120?","explanation":"₹75 + ₹25 = ₹100 spent, leaving ₹20 to save!"},{"id":"fl-8-q2","prompt":"Why should families check an electricity bill or grocery receipt before throwing it away?","emoji":"🧾","options":["To spot wrong prices, double scans, and track monthly spending","To fold airplanes only","Receipts always give free money"],"correctAnswer":"To spot wrong prices, double scans, and track monthly spending","hint":"Catch mistakes and track expenses!","explanation":"Checking bills catches billing errors and reveals where money goes."},{"id":"fl-8-q3","prompt":"Which family cost is a \"Surprise / Emergency Expense\"?","emoji":"🚑","options":["Fixing a sudden burst water pipe","Monthly school transport fee","Daily morning milk"],"correctAnswer":"Fixing a sudden burst water pipe","hint":"Look for an unplanned urgent repair.","explanation":"Milk and school fees are planned monthly; burst pipes are emergencies."}],"realLifeChallenge":{"title":"Check One Shop Bill","instruction":"Look at a real market or grocery receipt with a parent and add two small item prices together to verify the shop’s subtotal!","familyTip":"Ask what taxes or \"discounts\" look like on the paper bill."},"badge":{"id":"badge-fl-8","title":"Budget Balancer","emoji":"📊"}},"9":{"zoneId":"financial_literacy","classAge":9,"className":"4th Class","pedagogyTier":"conceptual","moduleTitle":"How Banks Work, Interest & Digital Payments Safety","hindiSubtitle":"बैंक खाता, ब्याज और सुरक्षित डिजिटल भुगतान","ncertGoalNote":"Bank deposits, simple concept of interest & UPI/QR payment safety awareness","lessons":[{"id":"fl-9-1","title":"How Savings Accounts Grow Gently (Interest)","hindiTitle":"बैंक में पैसे रखने पर मिलने वाला ब्याज","emojiVisual":"🏦 Deposit ₹1,000  ➡️  🌱 Bank Pays Extra Thank-You (Interest) ➡️ ₹1,040!","explanation":"Banks keep family savings locked safely against theft and reward savers with a small thank-you bonus called INTEREST each year! That is why saved money grows slowly over time.","indianExample":"Even children can open a minor savings passbook with parents or join Post Office savings schemes in India!","funFact":"Saving early gives interest MORE years to grow like a mango tree!","askNyraPrompt":"NYRA, explain bank interest to a 4th Class student with a mango tree example!"},{"id":"fl-9-2","title":"Digital UPI & QR Code Safety Rules","hindiTitle":"UPI और QR कोड से भुगतान की सुरक्षा","emojiVisual":"📲 Pay Money = Need PIN   |   📥 Receive Money = NEVER Need PIN!","explanation":"In India, families often pay shops by scanning a QR code using UPI! Remember the golden rule: you enter your secret UPI PIN ONLY when SENDING money—NEVER to receive money or claim a prize!","indianExample":"Always confirm the shopkeeper’s real name shown on screen after scanning a QR code!","funFact":"Nobody trustworthy ever asks you to share your 4/6-digit UPI PIN.","askNyraPrompt":"NYRA, give me 2 safety scenarios about UPI PIN traps!"}],"activity":{"kind":"classify","title":"Digital Payment: Safe Rule vs Scam Alert!","instruction":"Keep family bank accounts secure by sorting safe habits vs scam tricks.","leftBucketLabel":"🛡️ Safe Rule","rightBucketLabel":"🚨 Scam Alert","classifyItems":[{"id":"u1","label":"Check Shop Name on QR","emoji":"🏪","bucket":"left"},{"id":"u2","label":"Enter PIN to \"Receive\" Cash","emoji":"🔓","bucket":"right"},{"id":"u3","label":"Keep UPI PIN Secret","emoji":"🤫","bucket":"left"},{"id":"u4","label":"Tell OTP to Phone Caller","emoji":"📞","bucket":"right"}],"successMessage":"Digital Rupee Guardian! Nobody can trick you!"},"quiz":[{"id":"fl-9-q1","prompt":"A caller says: \"I am sending ₹500 to your mom! Just type your UPI PIN to RECEIVE it.\" True or Trap?","emoji":"⚠️","options":["TRAP! You NEVER enter a PIN to receive money","True—always type PIN to receive","Give half the PIN"],"correctAnswer":"TRAP! You NEVER enter a PIN to receive money","hint":"Does receiving money in your hand ever need a secret lock code?","explanation":"PINs ONLY unlock outgoing payments—entering a PIN sends your own money away!"},{"id":"fl-9-q2","prompt":"Why is keeping ₹5,000 in a bank savings account safer than under a mattress?","emoji":"🏦","options":["It stays safe from loss/theft AND earns small yearly interest","Mattresses eat paper notes","Banks double money overnight"],"correctAnswer":"It stays safe from loss/theft AND earns small yearly interest","hint":"Safety + steady growth!","explanation":"Banks protect cash, track records in a passbook, and pay steady interest."},{"id":"fl-9-q3","prompt":"If a bank pays 5% yearly interest on ₹100, what happens after 1 full year?","emoji":"📈","options":["It becomes ₹105 (you gained ₹5)","It shrinks to ₹95","It stays ₹50"],"correctAnswer":"It becomes ₹105 (you gained ₹5)","hint":"5 out of 100 is added!","explanation":"₹100 original savings + ₹5 interest reward = ₹105."}],"realLifeChallenge":{"title":"Inspect a Bank Passbook or Fake-Note Check With Parents","instruction":"Ask a parent to show you the shiny color-shifting thread and Gandhi watermark on a real ₹100 or ₹500 note under light!","familyTip":"Show your child where \"Reserve Bank of India\" is printed on Indian banknotes."},"badge":{"id":"badge-fl-9","title":"Smart Saver Pro","emoji":"🏦"}},"10":{"zoneId":"financial_literacy","classAge":10,"className":"5th Class","pedagogyTier":"conceptual","moduleTitle":"Micro-Entrepreneurship, Profit & Smart Consumer","hindiSubtitle":"लागत-मुनाफा, छोटा उद्यम और जागरूक उपभोक्ता","ncertGoalNote":"Cost vs Selling price, profit/loss intuition, consumer rights & avoiding debt traps","lessons":[{"id":"fl-10-1","title":"Cost, Revenue & Honest Profit (Lemonade Stand)","hindiTitle":"लागत, बिक्री और ईमानदार लाभ","emojiVisual":"🍋 Lemons+Sugar+Cups = Cost ₹60  |  Sales ₹100  ➡️  Profit = ₹40!","explanation":"If you make handmade greeting cards or fresh nimbu-pani for a school fair, subtract ALL ingredient & paper costs from total sales first! Only what remains after covering costs is real Profit.","indianExample":"Many village women’s Self-Help Groups (*Swasahayata Samuh*) calculate raw-material costs carefully so their crafts earn fair profit!","funFact":"If selling price is LOWER than cost, the stall runs at a Loss!","askNyraPrompt":"NYRA, test me with a Class 5 school craft-stall profit problem!"},{"id":"fl-10-2","title":"Consumer Rights & Borrowing Caution","hindiTitle":"ग्राहक के अधिकार और उधार से सावधानी","emojiVisual":"✅ Check Expiry Date + ISI/FSSAI Mark  |  ⚠️ \"Buy Now Pay Later\" Can Trap!","explanation":"Smart consumers always check Expiry Date, Net Weight, and FSSAI/ISI safety marks before paying! Also, borrowing for \"Wants\" (like fancy gadgets on high-interest loans) traps families in stress—save first instead!","indianExample":"Look for the green vegetarian dot and FSSAI license number on packed Indian snacks!","funFact":"Saving up ahead costs zero extra interest—borrowing adds extra charges!","askNyraPrompt":"NYRA, explain why saving up beats borrowing for a shiny toy or bike!"}],"activity":{"kind":"experiment","title":"School Bookmark Stall Check!","instruction":"Meera spent ₹80 on chart paper & ribbons to craft 10 bookmarks. She sold all 10 bookmarks for ₹12 each. Did she earn a Profit or Loss?","prompt":"Calculate Sales (10 × ₹12) minus Cost (₹80):","options":[{"label":"Profit of ₹40!","emoji":"🏆","correct":true,"feedback":"10 × ₹12 = ₹120 earned; ₹120 - ₹80 cost = ₹40 honest profit!"},{"label":"Loss of ₹40","emoji":"📉","correct":false,"feedback":"Check total sales: ₹120 is GREATER than ₹80 cost!"},{"label":"Profit of ₹120","emoji":"🧮","correct":false,"feedback":"Don’t forget to subtract her ₹80 material cost!"}],"successMessage":"Young Entrepreneur badge goal unlocked!"},"quiz":[{"id":"fl-10-q1","prompt":"What must you check on a juice carton BEFORE buying it?","emoji":"🧃","options":["Expiry/Best Before date, seal intactness & FSSAI mark","Only the cartoon mascot","Whether the cap is loose"],"correctAnswer":"Expiry/Best Before date, seal intactness & FSSAI mark","hint":"Food safety matters!","explanation":"Checking expiry date, seal, and FSSAI mark protects health and consumer rights."},{"id":"fl-10-q2","prompt":"A stall spends ₹150 making clay diyas and earns ₹130 selling them. What is the result?","emoji":"🪔","options":["₹20 Loss","₹20 Profit","₹280 Profit"],"correctAnswer":"₹20 Loss","hint":"Cost (₹150) > Sales (₹130)!","explanation":"Because costs exceeded sales by ₹20, the stall made a ₹20 loss."},{"id":"fl-10-q3","prompt":"An ad shouts: \"ZERO COST today—just pay ₹200/month forever!\" What is the smart question to ask?","emoji":"🧐","options":["\"What is the TOTAL cost over all months compared to paying upfront?\"","\"Where do I sign blindly?\"","\"Can I buy 5?\""],"correctAnswer":"\"What is the TOTAL cost over all months compared to paying upfront?\"","hint":"Multiply monthly payments to see the hidden total!","explanation":"Calculating total repayment exposes hidden fees and keeps families debt-free."}],"realLifeChallenge":{"title":"FSSAI & Expiry Audit on 3 Pantry Items","instruction":"Inspect 3 packaged foods in your kitchen, read their Manufacturing Date, Best Before date, and Veg/Non-Veg mark with a parent!","familyTip":"Ask what happens if a shop tries to charge above MRP (it is against consumer law!)."},"badge":{"id":"badge-fl-10","title":"Young Entrepreneur","emoji":"🏆"}}},"indian_heritage":{"3":{"zoneId":"indian_heritage","classAge":3,"className":"Nursery","pedagogyTier":"play","moduleTitle":"Warm Namaste & Our Beautiful Symbols","hindiSubtitle":"प्यारा नमस्ते और भारत के राष्ट्रीय प्रतीक","ncertGoalNote":"Pride in Indian symbols, warm greetings & cultural joy","lessons":[{"id":"ih-3-1","title":"Namaste With Folded Hands","hindiTitle":"हाथ जोड़कर प्यारा नमस्ते","emojiVisual":"🙏  \"Namaste!\" = Warm Heart Greeting","explanation":"Across India, joining our two palms softly and saying \"Namaste\" or \"Namaskar\" shows respect and kindness to grandparents, teachers, and friends!","indianExample":"Touching Dada-Dadi’s feet or waving with a bright smile brings joy to elders.","funFact":"Saying \"Namaste\" needs zero touching—so it keeps hands clean too!","askNyraPrompt":"NYRA, tell me how people say hello in different Indian languages!"},{"id":"ih-3-2","title":"Peacock, Lotus & Tiger Friends","hindiTitle":"मोर, कमल और बाघ हमारे गौरव","emojiVisual":"🦚 National Bird   |   🪷 National Flower   |   🐅 National Animal","explanation":"India’s National Bird is the dancing Peacock, our National Flower is the pink Lotus blooming in ponds, and our strong National Animal is the Royal Bengal Tiger!","indianExample":"When monsoon rains fall, peacocks spread their colorful feathers like a rainbow fan!","funFact":"The Lotus stays spotless clean even above muddy pond water!","askNyraPrompt":"NYRA, tell a cute Nursery story about a dancing peacock!"}],"activity":{"kind":"experiment","title":"Find India’s National Flower!","instruction":"Which lovely flower floats in ponds and is India’s National Flower?","prompt":"Tap the National Flower:","options":[{"label":"Pink Lotus","emoji":"🪷","correct":true,"feedback":"Yes! The lovely Lotus (Kamal) is India’s National Flower!"},{"label":"Cactus","emoji":"🌵","correct":false,"feedback":"A cactus grows prickly thorns in deserts!"},{"label":"Onion","emoji":"🧅","correct":false,"feedback":"An onion is a kitchen veggie, not a flower!"}],"successMessage":"Hooray! You know India’s joyful national symbols!"},"quiz":[{"id":"ih-3-q1","prompt":"Which colorful bird dances in the rain and is India’s National Bird?","emoji":"🪶","options":["Peacock 🦚","Penguin 🐧","Bat 🦇"],"correctAnswer":"Peacock 🦚","hint":"Look at its blue-green fan of feathers!","explanation":"The Peacock (Mayur) is India’s National Bird."},{"id":"ih-3-q2","prompt":"What greeting do we say while joining our two hands together?","emoji":"🙏","options":["Namaste","Bye-bye","Oops"],"correctAnswer":"Namaste","hint":"Warm Indian greeting!","explanation":"Namaste greets elders and friends with warmth and respect."},{"id":"ih-3-q3","prompt":"Which striped big cat is India’s National Animal?","emoji":"🐾","options":["Royal Bengal Tiger 🐅","Hippo 🦛","Kangaroo 🦘"],"correctAnswer":"Royal Bengal Tiger 🐅","hint":"Orange fur with black stripes!","explanation":"The Bengal Tiger is India’s proud National Animal."}],"realLifeChallenge":{"title":"Morning Namaste Smile","instruction":"Greet every elder at home tomorrow morning with folded hands 🙏 and a cheerful \"Namaste!\"","familyTip":"Ask your child which regional greeting your family uses (Sat Sri Akal, Vanakkam, Adab, Johar, Nomoshkar)."},"badge":{"id":"badge-ih-3","title":"Lotus Smile","emoji":"🪷"}},"4":{"zoneId":"indian_heritage","classAge":4,"className":"LKG","pedagogyTier":"play","moduleTitle":"Joyful Festivals & Our Tricolor Flag","hindiSubtitle":"रंग-बिरंगे त्योहार और तिरंगा झंडा","ncertGoalNote":"Appreciating India’s festivals & Tiranga colors","lessons":[{"id":"ih-4-1","title":"Festivals of Lights, Harvest & Colors","hindiTitle":"दीप, फसल और रंगों के त्योहार","emojiVisual":"🪔 Diwali   🎨 Holi   🌾 Pongal & Baisakhi   🌙 Eid","explanation":"India is a garden of celebrations! Families light clay diyas on Diwali, celebrate sweet harvests during Pongal, Onam, Lohri & Baisakhi, share sewaiyan on Eid, and splash natural flower colors on Holi!","indianExample":"Neighborhood friends share laddoos, gujiyas, and festive hugs together!","funFact":"Clay diyas give work to local pottery artists (*kumhars*)!","askNyraPrompt":"NYRA, tell me how children celebrate Pongal or Onam in South India!"},{"id":"ih-4-2","title":"Colors of Our Tricolor Flag (Tiranga)","hindiTitle":"हमारा प्यारा तिरंगा झंडा","emojiVisual":"🟧 Saffron (Courage)  ⬜ White + Blue Wheel (Peace)  🟩 Green (Growth)","explanation":"India’s flag has three stripes: Saffron at top for courage, White in middle for peace with a 24-spoke Navy Blue Ashoka Chakra wheel, and Green at bottom for fertile land & growth!","indianExample":"On 15th August and 26th January, schools hoist the Tiranga and sing the National Anthem proudly.","funFact":"The Ashoka Chakra in the center has 24 spokes representing steady forward movement!","askNyraPrompt":"NYRA, teach me a quick LKG quiz on the 3 stripes of the Tiranga!"}],"activity":{"kind":"sequence","title":"Build the Indian Tiranga Top to Bottom!","instruction":"Tap the 3 stripes in exact order from TOP (1) to BOTTOM (3).","sequenceSteps":[{"id":"f1","label":"Saffron Stripe (Top)","emoji":"🟧","order":1},{"id":"f2","label":"White + Ashoka Chakra (Middle)","emoji":"⬜","order":2},{"id":"f3","label":"Green Stripe (Bottom)","emoji":"🟩","order":3}],"successMessage":"Jai Hind! You arranged the Tiranga cleanly!"},"quiz":[{"id":"ih-4-q1","prompt":"Which stripe sits at the TOP of India’s national flag?","emoji":"🇮🇳","options":["Saffron (Orange)","Green","Purple"],"correctAnswer":"Saffron (Orange)","hint":"Remember: Saffron → White → Green!","explanation":"Saffron sits on top, White with Ashoka Chakra in middle, Green at bottom."},{"id":"ih-4-q2","prompt":"Which warm festival celebrates welcoming sunny harvests in Tamil Nadu with sweet boiling rice?","emoji":"🌾","options":["Pongal","Halloween","April Fools"],"correctAnswer":"Pongal","hint":"A famous South Indian harvest festival!","explanation":"Pongal is celebrated across Tamil Nadu to thank sun, rain, cattle, and farmers."},{"id":"ih-4-q3","prompt":"Which eco-friendly light helps village potters earn on Diwali?","emoji":"🪔","options":["Clay Mitti Diya","Loud firecrackers","Broken glass"],"correctAnswer":"Clay Mitti Diya","hint":"Warm glow with zero smoke noise!","explanation":"Clay diyas are smoke-free, biodegradable, and support local potters."}],"realLifeChallenge":{"title":"Share a Festival Sweet Story","instruction":"Ask Dada-Dadi or parents which festival food they loved most when they were 4 years old!","familyTip":"Let your child draw a glowing clay diya or colorful harvest rangoli."},"badge":{"id":"badge-ih-4","title":"Tiranga Star","emoji":"🇮🇳"}},"5":{"zoneId":"indian_heritage","classAge":5,"className":"UKG","pedagogyTier":"play","moduleTitle":"Panchatantra Animal Wisdom & Traditional Games","hindiSubtitle":"पंचतंत्र की कहानियाँ और भारतीय पारंपरिक खेल","ncertGoalNote":"Oral storytelling heritage (Panchatantra) & active indigenous games","lessons":[{"id":"ih-5-1","title":"Clever Animals of Panchatantra","hindiTitle":"पंचतंत्र की बुद्धिमान कहानियाँ","emojiVisual":"🐦 Unity Breaks Traps!  |  🐢 Slow & Steady Wins!","explanation":"Long ago in India, Pandit Vishnu Sharma wrote the famous *Panchatantra* animal stories so young kids learn wisdom through fun tales—like tiny doves flying up TOGETHER carrying a hunter’s net!","indianExample":"Even the clever Monkey and Crocodile story reminds us to stay calm when solving a tough spot!","funFact":"Panchatantra stories have been translated into over 50 languages worldwide!","askNyraPrompt":"NYRA, tell me the short UKG story of the United Doves from Panchatantra!"},{"id":"ih-5-2","title":"Joyful Indian Playground Games","hindiTitle":"भारत के मज़ेदार पारंपरिक खेल","emojiVisual":"🏃 Kho-Kho   🤸 Langdi & Stapoo (Hopscotch)   ♟️ Pachisi (Ludo)","explanation":"Before video screens existed, Indian kids played energetic outdoor games like *Stapoo* (Hopscotch), *Pithoo* (Seven Stones), *Kho-Kho*, and indoor *Pallanguzhi* / *Pachisi*!","indianExample":"Did you know Ludo grew out of India’s ancient game *Pachisi* and Chess grew from *Chaturanga*?","funFact":"Outdoor games keep our legs quick and teach fair teamwork!","askNyraPrompt":"NYRA, teach me how to play Stapoo (Indian hopscotch) safely!"}],"activity":{"kind":"classify","title":"Sort: Active Outdoor Play vs Calm Indoor Play!","instruction":"Sort classic Indian games into Outdoor Field Games vs Cozy Indoor Board Games.","leftBucketLabel":"🏃 Outdoor Active","rightBucketLabel":"🎲 Indoor Mind Game","classifyItems":[{"id":"g1","label":"Kho-Kho","emoji":"🏃","bucket":"left"},{"id":"g2","label":"Chaturanga / Chess","emoji":"♟️","bucket":"right"},{"id":"g3","label":"Stapoo Hopscotch","emoji":"🦘","bucket":"left"},{"id":"g4","label":"Pachisi / Ludo","emoji":"🎲","bucket":"right"}],"successMessage":"Traditional games champion!"},"quiz":[{"id":"ih-5-q1","prompt":"In the Panchatantra story of the trapped doves, how did the tiny birds escape the net?","emoji":"🕊️","options":["They worked together and flew up at the same time","They argued loudly","They hid under grass alone"],"correctAnswer":"They worked together and flew up at the same time","hint":"\"Unity is Strength!\"","explanation":"Together in unity, even tiny friends solve huge challenges."},{"id":"ih-5-q2","prompt":"Which famous strategy board game first began in ancient India as \"Chaturanga\"?","emoji":"♟️","options":["Chess","Ice Hockey","Bowling"],"correctAnswer":"Chess","hint":"Played on 64 black-and-white squares!","explanation":"Chaturanga evolved into modern Chess!"},{"id":"ih-5-q3","prompt":"In the Thirsty Crow story, how did the smart crow raise the water inside the pot?","emoji":"🐦‍⬛","options":["Dropped pebbles one by one into the pot","Broke the clay pot","Gave up right away"],"correctAnswer":"Dropped pebbles one by one into the pot","hint":"Tiny pebbles push water level up!","explanation":"Patience and observation solved what strength alone could not!"}],"realLifeChallenge":{"title":"Play a Chalk Stapoo or Ludo Round","instruction":"Play one round of Ludo, Carrom, or Hopscotch with family tonight and cheer for everyone—win or lose!","familyTip":"Let grandma/grandpa teach one childhood street game they loved."},"badge":{"id":"badge-ih-5","title":"Panchatantra Pal","emoji":"📖"}},"6":{"zoneId":"indian_heritage","classAge":6,"className":"1st Class","pedagogyTier":"foundational","moduleTitle":"Wonders of Architecture & Simple Yoga","hindiSubtitle":"भारत की ऐतिहासिक धरोहर और सरल योगासन","ncertGoalNote":"Appreciating diverse Indian monuments & joyful mindful yoga","lessons":[{"id":"ih-6-1","title":"Famous Indian Landmarks Across Directions","hindiTitle":"उत्तर से दक्षिण तक प्रसिद्ध स्मारक","emojiVisual":"🕌 Red Fort (Delhi) • 🏰 Hawa Mahal (Jaipur) • 🛕 Konark (Odisha)","explanation":"India’s builders crafted stone palaces, forts, sun temples shaped like giant stone chariots (Konark), and marble marvels—showing extraordinary math and art skills!","indianExample":"Have you seen the Red Fort or Konark Wheel printed right on the back of Indian currency notes?","funFact":"Hawa Mahal in Jaipur has 953 little windows (*jharokhas*) that keep cool breezes blowing naturally!","askNyraPrompt":"NYRA, tell me which landmark sits on the ₹50 or ₹10 Indian note!"},{"id":"ih-6-2","title":"Playful Yoga Poses Like Nature","hindiTitle":"प्रकृति जैसे प्यारे योगासन","emojiVisual":"🌳 Vrikshasana (Tree)  |  🦋 Baddha Konasana (Butterfly)  |  🐍 Bhujangasana","explanation":"Yoga started in India thousands of years ago to keep body, breath, and mind peaceful! Many poses copy nature—standing tall on one leg like a Banyan Tree (*Vrikshasana*) improves balance!","indianExample":"Taking 3 slow \"Bee Breaths\" (*Bhramari*) calms down wiggles before study time!","funFact":"21st June is celebrated worldwide as International Day of Yoga!","askNyraPrompt":"NYRA, guide me through a safe 1-minute Tree Pose for Class 1!"}],"activity":{"kind":"experiment","title":"Why Did Builders Give Hawa Mahal 953 Small Windows?","instruction":"Jaipur gets very hot in summer! Why did artisans build hundreds of tiny latticed windows in Hawa Mahal?","prompt":"Choose the clever reason:","options":[{"label":"To catch cool breeze and cool rooms without electricity!","emoji":"🌬️","correct":true,"feedback":"Exactly! Ancient Indian builders used smart natural airflow engineering!"},{"label":"To fit 953 refrigerators","emoji":"🧊","correct":false,"feedback":"Electricity didn’t exist back then—it was pure natural wind cooling!"},{"label":"To hide bicycles","emoji":"🚲","correct":false,"feedback":"Nope—Hawa Mahal literally means Palace of Winds!"}],"successMessage":"Heritage architect discovery unlocked!"},"quiz":[{"id":"ih-6-q1","prompt":"Which famous Jaipur monument means \"Palace of Winds\" and uses natural breeze cooling?","emoji":"🌬️","options":["Hawa Mahal","Qutub Minar","Gateway of India"],"correctAnswer":"Hawa Mahal","hint":"\"Hawa\" means wind in Hindi!","explanation":"Hawa Mahal’s 953 windows cool the palace naturally."},{"id":"ih-6-q2","prompt":"What does \"Vrikshasana\" (Tree Pose) help children build?","emoji":"🌳","options":["Balance, leg strength, and calm focus","Sleepiness all day","Louder shouting"],"correctAnswer":"Balance, leg strength, and calm focus","hint":"Stand steady like a tall tree!","explanation":"Balancing like a tree strengthens posture and concentration."},{"id":"ih-6-q3","prompt":"How should students treat ancient temples, forts, and museum walls?","emoji":"🏛️","options":["Admire without scribbling, touching carvings, or littering","Carve names with chalk/keys","Drop snack wrappers"],"correctAnswer":"Admire without scribbling, touching carvings, or littering","hint":"Protect heritage for future kids!","explanation":"Keeping monuments clean preserves centuries of craftsmanship."}],"realLifeChallenge":{"title":"Hold a 10-Second Tree Pose","instruction":"Try standing gently in Vrikshasana (one foot against your lower ankle, palms together 🙏) for 10 slow breaths on each side!","familyTip":"Do it beside a wall with parents for fun safe balance."},"badge":{"id":"badge-ih-6","title":"Yoga & Fort Guide","emoji":"🛕"}},"7":{"zoneId":"indian_heritage","classAge":7,"className":"2nd Class","pedagogyTier":"foundational","moduleTitle":"Unity in Diversity: Food, Attire & Folk Dances","hindiSubtitle":"विविधता में एकता: वेशभूषा, भोजन और लोकनृत्य","ncertGoalNote":"Respecting regional diversity across Indian states (clothing, food & dance)","lessons":[{"id":"ih-7-1","title":"A Kaleidoscope of Indian Clothes & Cuisines","hindiTitle":"हर राज्य का अनोखा पहनावा और स्वाद","emojiVisual":"🏔️ Pheran (Kashmir) • 🏖️ Mundu/Saree (Kerala) • 🌾 Phulkari (Punjab)","explanation":"India’s warm deserts, snowy Himalayas, green coasts, and Northeast hills shaped wonderfully different clothing and dishes—like Kashmir’s wool *Pheran*, Assam’s *Mekhela Chador*, Maharashtra’s *Nauvari*, Rajasthan’s crisp *Dal-Baati*, and South India’s steamed *Idli-Dosa*!","indianExample":"Climates inspire clothes: cool coastal regions love airy cotton, while snowy Ladakh loves warm wool!","funFact":"Different foods use crops grown locally—rice on rainy coasts, wheat & millets in dry plains!","askNyraPrompt":"NYRA, tell me one delicious traditional dish from 4 different corners of India!"},{"id":"ih-7-2","title":"Dancing Stories From Every State","hindiTitle":"भारत के प्रसिद्ध शास्त्रीय और लोकनृत्य","emojiVisual":"🥁 Bhangra (Punjab) • 💃 Garba (Gujarat) • 🌸 Bihu (Assam) • 🎭 Kathakali","explanation":"Dance tells stories of harvests, seasons, and joy! *Bihu* greets Assamese spring, *Garba* spins around glowing lamps in Gujarat, *Bhangra* leaps to dhol beats in Punjab, and *Bharatanatyam* speaks through hand *mudras*!","indianExample":"Even hand gestures (*mudras*) in classical dance can show a blooming lotus, a running deer, or gentle rain!","funFact":"India recognizes 8 vibrant classical dances plus hundreds of regional folk dances!","askNyraPrompt":"NYRA, explain what hand mudras show in Bharatanatyam or Kathak!"}],"activity":{"kind":"classify","title":"Match Traditions to Region Clues!","instruction":"Sort these joyful traditions into North/West India vs East/South India.","leftBucketLabel":"🏜️ North / West India","rightBucketLabel":"🌴 East / South India","classifyItems":[{"id":"c1","label":"Garba & Dandiya (Gujarat)","emoji":"🪔","bucket":"left"},{"id":"c2","label":"Bihu Dance (Assam)","emoji":"🌸","bucket":"right"},{"id":"c3","label":"Bhangra (Punjab)","emoji":"🥁","bucket":"left"},{"id":"c4","label":"Onam Sadya & Idli (South)","emoji":"🍌","bucket":"right"}],"successMessage":"Across every corner, India shines together!"},"quiz":[{"id":"ih-7-q1","prompt":"Why do people in coastal Kerala eat lots of rice & coconut, while Rajasthan eats bajra & wheat?","emoji":"🍛","options":["Different local soils and rainfall grow different traditional crops","Trucks are illegal","Spices pick sides"],"correctAnswer":"Different local soils and rainfall grow different traditional crops","hint":"Think of monsoon coasts vs drier plains!","explanation":"Geography shapes local crops, clothes, and festivals beautifully."},{"id":"ih-7-q2","prompt":"Which cheerful dance celebrates harvest & spring in Assam?","emoji":"🌺","options":["Bihu","Ballet","Waltz"],"correctAnswer":"Bihu","hint":"Famous festival and dance of Assam!","explanation":"Bihu celebrates the spring harvest and New Year in Assam."},{"id":"ih-7-q3","prompt":"What does \"Unity in Diversity\" mean for our classroom friends?","emoji":"🤝","options":["Respecting each friend’s language, food, and festival as one happy team","Only liking one food","Laughing at unfamiliar accents"],"correctAnswer":"Respecting each friend’s language, food, and festival as one happy team","hint":"Many colors making one rainbow!","explanation":"Celebrating differences with kindness makes our country strong and united."}],"realLifeChallenge":{"title":"Taste or Draw Another Region’s Dish","instruction":"Learn how to say \"Thank You\" in one Indian language different from your own home language (e.g., *Dhanyavaad, Nandri, Shukriya, Dhanyabaad*)!","familyTip":"Share a story from your family’s home state or favorite trip."},"badge":{"id":"badge-ih-7","title":"Unity Ambassador","emoji":"🌈"}},"8":{"zoneId":"indian_heritage","classAge":8,"className":"3rd Class","pedagogyTier":"conceptual","moduleTitle":"Ancient Indian Scholars: Aryabhata & Sushruta","hindiSubtitle":"प्राचीन भारत के महान वैज्ञानिक: आर्यभट और सुश्रुत","ncertGoalNote":"Indian Knowledge Systems: Zero/astronomy (Aryabhata) & early medicine/hygiene","lessons":[{"id":"ih-8-1","title":"Aryabhata: Stars, Earth’s Spin & Place Value Zero","hindiTitle":"आर्यभट: शून्य और पृथ्वी का घूमना","emojiVisual":"⭕ Zero (0) Place Value  •  🌍 Earth Spins on Its Axis!","explanation":"Over 1,500 years ago, mathematician-astronomer Aryabhata worked near Kusumapura (Patna). Indian scholars perfected the decimal place-value system with ZERO (0)—and Aryabhata explained correctly that Earth rotates on its axis causing day & night!","indianExample":"India named its very first satellite launched in 1975 \"Aryabhata\" in his honor!","funFact":"Without place-value Zero, writing 105 vs 15 or calculating large space orbits would be nearly impossible!","askNyraPrompt":"NYRA, explain why place-value Zero from India changed math forever!"},{"id":"ih-8-2","title":"Sushruta & Ayurveda: Clean Healing & Kitchen Spices","hindiTitle":"सुश्रुत और आयुर्वेद की ज्ञान परंपरा","emojiVisual":"🌿 Haldi (Turmeric) • Tulsi • Clean Surgical Care","explanation":"Ancient Indian physician Sushruta wrote detailed guides emphasizing clean instruments, boiling/hygiene, and careful medical training long before modern hospitals! Everyday Indian kitchens also cherish safe traditions like warm turmeric milk for coughs.","indianExample":"Washing hands and sterilizing medical tools keeps infections away—emphasized centuries ago in *Sushruta Samhita*!","funFact":"Always follow real doctors’ advice for serious illness alongside healthy kitchen nutrition!","askNyraPrompt":"NYRA, tell me 2 interesting Class 3 facts about Sushruta’s medical work!"}],"activity":{"kind":"experiment","title":"Why Did Aryabhata Say Stars Appear to Move West?","instruction":"Look out a spinning carousel—the trees outside seem to slide backwards even though trees stand still! What did Aryabhata explain about Sunrise & Sunset?","prompt":"Pick Aryabhata’s true discovery:","options":[{"label":"Earth spins eastwards on its axis, making Sun & stars seem to cross the sky!","emoji":"🌍","correct":true,"feedback":"Spot on! Aryabhata compared it to sitting in a moving boat seeing riverbank trees pass backwards!"},{"label":"A giant bird pulls the Sun with a rope","emoji":"🐦","correct":false,"feedback":"Aryabhata used scientific observation, not myths!"},{"label":"Earth is flat like a coin","emoji":"🪙","correct":false,"feedback":"Indian astronomers knew Earth is a sphere!"}],"successMessage":"Brilliant astronomy discovery unlocked!"},"quiz":[{"id":"ih-8-q1","prompt":"Why did Aryabhata compare Earth’s rotation to riding in a forward-moving boat?","emoji":"⛵","options":["Just as shore trees appear to move backward, spinning Earth makes stars appear to move","Boats fly in space","Stars swim in rivers"],"correctAnswer":"Just as shore trees appear to move backward, spinning Earth makes stars appear to move","hint":"Motion perspective!","explanation":"Because Earth rotates west-to-east, the Sun and stars appear to rise east and set west."},{"id":"ih-8-q2","prompt":"What was India’s first satellite launched in 1975 named after?","emoji":"🛰️","options":["Aryabhata","Hawa Mahal","Stapoo"],"correctAnswer":"Aryabhata","hint":"Honoring the great astronomer-mathematician!","explanation":"India’s first space satellite carried Aryabhata’s name proudly."},{"id":"ih-8-q3","prompt":"Which ancient Indian text is famous for describing surgical care and medical training?","emoji":"📜","options":["Sushruta Samhita","Panchatantra","Dictionary"],"correctAnswer":"Sushruta Samhita","hint":"Named after ancient physician Sushruta!","explanation":"Sushruta documented detailed surgical tools, training, and cleanliness."}],"realLifeChallenge":{"title":"Boat Perspective Test","instruction":"Next time you ride a bicycle or bus, notice how lamp posts seem to slide past while actually standing still—just like Aryabhata’s example!","familyTip":"Talk about how ancient Indian curiosity led to real scientific breakthroughs."},"badge":{"id":"badge-ih-8","title":"Scholar Explorer","emoji":"🔭"}},"9":{"zoneId":"indian_heritage","classAge":9,"className":"4th Class","pedagogyTier":"conceptual","moduleTitle":"Modern Indian Scientists: C.V. Raman & Dr. Kalam","hindiSubtitle":"सी.वी. रमन, डॉ. ए.पी.जे. अब्दुल कलाम और विज्ञान की ज्योति","ncertGoalNote":"Inspiring modern Indian scientists, curiosity & perseverance","lessons":[{"id":"ih-9-1","title":"Sir C.V. Raman: Asking \"Why Is the Sea Deep Blue?\"","hindiTitle":"सी.वी. रमन: नीले समुद्र का रहस्य","emojiVisual":"🚢 Ship Voyage (1921) ➡️ 💧 Why Deep Blue? ➡️ 🏆 Nobel Prize (Raman Effect)","explanation":"Sailing back to India in 1921, physicist C.V. Raman stared at the deep blue sea and wondered WHY water looked richer blue than just sky reflection! Using simple prism & glass experiments in Kolkata, he proved how light scatters off molecules—winning Asia’s first Nobel Prize in Physics!","indianExample":"India celebrates **National Science Day** every February 28th to remember the Raman Effect discovery!","funFact":"His curious question on a ship voyage changed modern physics and lasers!","askNyraPrompt":"NYRA, explain why National Science Day is celebrated on February 28 in India!"},{"id":"ih-9-2","title":"Dr. A.P.J. Abdul Kalam: Newspaper Boy to Rocket Scientist","hindiTitle":"डॉ. कलाम: सपनों और मेहनत की उड़ान","emojiVisual":"🗞️ Delivered Papers in Rameswaram ➡️ 🚀 Built India’s Space Rockets ➡️ 🇮🇳 President","explanation":"Born in coastal Rameswaram, young Kalam watched seabirds soar and dreamed of flight! Even while selling newspapers to help his family, he studied hard, led India’s space satellite vehicle SLV-3, and inspired millions of students as India’s \"People’s President.\"","indianExample":"\"Dream is not what you see in sleep; dream is the thing which doesn’t let you sleep!\" — Dr. Kalam.","funFact":"He loved visiting schools and answering kids’ curious questions even after retiring!","askNyraPrompt":"NYRA, tell me an inspiring childhood moment from Dr. A.P.J. Abdul Kalam’s life!"}],"activity":{"kind":"experiment","title":"What Sparked C.V. Raman’s Famous Discovery?","instruction":"Which simple everyday question led C.V. Raman to investigate molecular light scattering?","prompt":"Tap the spark of curiosity:","options":[{"label":"\"Why does deep ocean water scatter blue light?\"","emoji":"🌊","correct":true,"feedback":"Yes! One honest \"Why?\" while looking at the sea led to a Nobel Prize!"},{"label":"\"Why do cats hate baths?\"","emoji":"🐱","correct":false,"feedback":"Cute question, though Raman studied light & crystal physics!"},{"label":"\"Which movie had longest songs?\"","emoji":"🎬","correct":false,"feedback":"Raman observed the Mediterranean Sea on his ship voyage!"}],"successMessage":"Scientist’s mindset activated: never stop asking WHY!"},"quiz":[{"id":"ih-9-q1","prompt":"Why does India celebrate National Science Day on 28 February every year?","emoji":"🏅","options":["To mark Sir C.V. Raman discovering the Raman Effect of light","First day of summer","Cricket final"],"correctAnswer":"To mark Sir C.V. Raman discovering the Raman Effect of light","hint":"Honoring the 1928 light-scattering discovery!","explanation":"On 28 Feb 1928, C.V. Raman announced the Raman Effect, later winning the 1930 Nobel Prize."},{"id":"ih-9-q2","prompt":"What inspiring lesson shines through Dr. A.P.J. Abdul Kalam’s early years in Rameswaram?","emoji":"🚀","options":["Hard work, reading, and big dreams can overcome modest beginnings","Only rich kids can build rockets","Never ask questions"],"correctAnswer":"Hard work, reading, and big dreams can overcome modest beginnings","hint":"Think of his newspaper-delivery mornings and love for books!","explanation":"Curiosity, discipline, and perseverance carried him from small-town Rameswaram to space history."},{"id":"ih-9-q3","prompt":"Also remember ISRO’s Chandrayaan-3! Which part of the Moon did India reach gently in 2023?","emoji":"🌕","options":["Near the Lunar South Pole","Center of the Sun","Deep underwater"],"correctAnswer":"Near the Lunar South Pole","hint":"A sunny & icy milestone near the Moon’s bottom pole!","explanation":"ISRO’s Vikram lander softly touched down near the Moon’s South Pole region in 2023."}],"realLifeChallenge":{"title":"Keep a 3-Day \"Why?\" Notebook","instruction":"Just like C.V. Raman, write down 3 \"Why?\" questions about sky, water, or plants you spot this week and research answers with parents!","familyTip":"Celebrate curious questions even if adults need to look up the answer together!"},"badge":{"id":"badge-ih-9","title":"Science Torchbearer","emoji":"🚀"}},"10":{"zoneId":"indian_heritage","classAge":10,"className":"5th Class","pedagogyTier":"conceptual","moduleTitle":"Crafts, Sustainability & Constitutional Values","hindiSubtitle":"हस्तशिल्प विरासत और संवैधानिक मूल्य (समानता, बंधुत्व)","ncertGoalNote":"Appreciating artisans, ecological heritage & Constitution’s values of justice/fraternity","lessons":[{"id":"ih-10-1","title":"Living Crafts: Khadi, Pottery & Bamboo Weaving","hindiTitle":"खादी, मिट्टी और बाँस की कारीगरी","emojiVisual":"🧵 Handloom Silk & Khadi  •  🎍 Northeast Bamboo Craft  •  🏺 Terracotta","explanation":"Indian artisans weave cotton on wooden looms, shape breathable bamboo baskets in Assam & Tripura, and paint Madhubani stories using plant dyes! Supporting handmade local crafts keeps centuries of skill alive and uses eco-friendly materials.","indianExample":"Bamboo grows fast without chemicals—making Northeast Indian bamboo bottles & mats sustainable genius!","funFact":"Handloom weaving employs millions of rural families and uses tiny amounts of electricity compared to big factories!","askNyraPrompt":"NYRA, tell me about 2 traditional sustainable Indian crafts and the states they come from!"},{"id":"ih-10-2","title":"Our Constitution’s Promises: Fairness & Fraternity","hindiTitle":"संविधान के मूल्य: समानता, न्याय और भाईचारा","emojiVisual":"⚖️ Equality  •  🗣️ Free Thought  •  🤝 Fraternity (Caring Like Family)","explanation":"Led by Dr. B.R. Ambedkar and the Constituent Assembly, India’s Constitution gives every citizen equal rights regardless of gender, religion, caste, or region—AND lists Fundamental Duties like protecting rivers/forests, respecting science, and promoting harmony (*brotherhood*)!","indianExample":"Even in a school classroom, fair turns, welcoming everyone, and caring for school desks practice Constitutional values every day!","funFact":"26 November is celebrated as Constitution Day (*Samvidhan Divas*) across India!","askNyraPrompt":"NYRA, explain Dr. B.R. Ambedkar’s values of equality & education for Class 5!"}],"activity":{"kind":"classify","title":"Constitutional Citizen Values Check!","instruction":"Sort actions that uphold Fraternity & Fundamental Duties vs unfair habits.","leftBucketLabel":"⚖️ Fair & Civic Duty","rightBucketLabel":"🚫 Unfair Action","classifyItems":[{"id":"cv1","label":"Include Every Kid in Play","emoji":"🤝","bucket":"left"},{"id":"cv2","label":"Carve Bench in Park","emoji":"🪑","bucket":"right"},{"id":"cv3","label":"Protect Trees & Rivers","emoji":"🌊","bucket":"left"},{"id":"cv4","label":"Tease Classmate Accent","emoji":"😒","bucket":"right"}],"successMessage":"Responsible young citizen of India!"},"quiz":[{"id":"ih-10-q1","prompt":"Who chaired the Drafting Committee of the Indian Constitution and championed equal rights & education for all?","emoji":"📘","options":["Dr. B.R. Ambedkar","Alexander the Great","Sir Isaac Newton"],"correctAnswer":"Dr. B.R. Ambedkar","hint":"Architect of India’s Constitution!","explanation":"Dr. Bhimrao Ramji Ambedkar guided equality, justice, and constitutional rights."},{"id":"ih-10-q2","prompt":"Why is natural plant-dyed handloom & bamboo craft great for both people AND the planet?","emoji":"🎍","options":["It supports skilled local artisans and avoids synthetic plastic waste","It requires bulldozers","It melts in sunlight"],"correctAnswer":"It supports skilled local artisans and avoids synthetic plastic waste","hint":"Think of livelihoods + biodegradable materials!","explanation":"Local eco-crafts preserve heritage skills while staying gentle on Earth."},{"id":"ih-10-q3","prompt":"Which Fundamental Duty in India’s Constitution talks directly to students’ daily mindset?","emoji":"🔬","options":["Developing scientific temper, curiosity, and protecting the environment","Never reading new books","Keeping taps open"],"correctAnswer":"Developing scientific temper, curiosity, and protecting the environment","hint":"Think of truth, science, and green nature!","explanation":"Article 51A encourages scientific temper, humanism, inquiry, and caring for nature."}],"realLifeChallenge":{"title":"Spot a Handmade Craft at Home","instruction":"Find one handmade item at home (clay pot, woven basket, handloom dupatta, or wooden toy) and thank whoever crafted or preserved it!","familyTip":"Look up together which Indian state’s craft tradition it comes from."},"badge":{"id":"badge-ih-10","title":"Citizen & Heritage Star","emoji":"⚖️"}}},"life_skills_sel":{"3":{"zoneId":"life_skills_sel","classAge":3,"className":"Nursery","pedagogyTier":"play","moduleTitle":"My Feelings & Clean Little Hands","hindiSubtitle":"मेरी भावनाएँ और साफ-सफाई की अच्छी आदतें","ncertGoalNote":"Naming basic feelings (happy/sad/angry), polite magic words & handwashing","lessons":[{"id":"ls-3-1","title":"Faces Show How We Feel Inside","hindiTitle":"चेहरा बताता है मन की बात","emojiVisual":"😊 Happy  •  😢 Sad  •  😠 Grumpy  •  😨 Scared","explanation":"All feelings are okay! Smiling feels bubbly inside; feeling grumpy or sad is okay too—just use soft words like \"I feel sad\" or hug Mama/Papa instead of hitting!","indianExample":"Taking 2 deep belly breaths like smelling a fresh rose 🌸 calms grumpy feelings fast!","funFact":"Every child—and even grown-ups—feels sad or frustrated sometimes!","askNyraPrompt":"NYRA, play a silly feeling-faces game with me for Nursery!"},{"id":"ls-3-2","title":"Soap Bubbles Chase Germs Away!","hindiTitle":"साबुन के झाग भगाएँ कीटाणु","emojiVisual":"🧼 Soap + 20-Second Song  ➡️  ✨ Sparkling Clean Hands!","explanation":"Tiny invisible germs hide after playing with sand, pets, or using the toilet. Washing fronts, backs, and thumbs with soap for a happy birthday song keeps tummies strong!","indianExample":"Remember to wash hands right before touching roti, fruits, or rice!","funFact":"Singing \"Twinkle Twinkle\" once takes right about 20 handwashing seconds!","askNyraPrompt":"NYRA, sing a cute 15-second handwash song!"}],"activity":{"kind":"experiment","title":"Your Toy Block Tower Fell Down!","instruction":"Oh no, your tall block tower tumbled down! What helps your heart feel better safely?","prompt":"Choose the calm kind action:","options":[{"label":"Take a deep breath & rebuild together!","emoji":"😌","correct":true,"feedback":"Super! Breathing deeply lets us try again with a smile!"},{"label":"Throw blocks at the wall","emoji":"💥","correct":false,"feedback":"Throwing hurts walls, toys, or friends—let’s take a breath instead!"},{"label":"Bite your shirt","emoji":"😣","correct":false,"feedback":"Use gentle words or ask a parent for a hug!"}],"successMessage":"Calm heart champion!"},"quiz":[{"id":"ls-3-q1","prompt":"What 2 magic words do we say when asking politely or receiving a treat?","emoji":"✨","options":["\"Please\" & \"Thank You\"","\"Gimme now!\"","\"Quiet!\""],"correctAnswer":"\"Please\" & \"Thank You\"","hint":"Polite magic words make everyone smile!","explanation":"\"Please\" asks gently and \"Thank You\" shows gratitude."},{"id":"ls-3-q2","prompt":"When MUST we wash our hands with soap and water?","emoji":"🧼","options":["Before eating & after toilet/park play","Never ever","Only with dry tissue"],"correctAnswer":"Before eating & after toilet/park play","hint":"Chase away sticky dirt and germs!","explanation":"Soap and water before food and after toilet stops germs from making us sick."},{"id":"ls-3-q3","prompt":"A friend dropped their crayons. How can you show kindness?","emoji":"🖍️","options":["Help pick up the crayons together","Step over them laughing","Hide them"],"correctAnswer":"Help pick up the crayons together","hint":"Kind hands make friends happy!","explanation":"Helping when someone drops things builds warm friendship."}],"realLifeChallenge":{"title":"Smell the Rose, Blow the Candle Breath","instruction":"Practice breathing in slowly like smelling a rose 🌸, then puffing out gently like cooling hot milk ☕—three times before bedtime!","familyTip":"Validate feelings first (\"I see you feel upset\") before problem-solving."},"badge":{"id":"badge-ls-3","title":"Kind Hands Hero","emoji":"🧼"}},"4":{"zoneId":"life_skills_sel","classAge":4,"className":"LKG","pedagogyTier":"play","moduleTitle":"Sharing Turns, Colorful Tiffin & Home Safety","hindiSubtitle":"बारी से खेलना, पौष्टिक टिफिन और घर में सुरक्षा","ncertGoalNote":"Taking turns, healthy rainbow food & home/sharp-object safety","lessons":[{"id":"ls-4-1","title":"Sharing Turns on the Swing","hindiTitle":"झूले और खिलौनों में बारी का नियम","emojiVisual":"👧 Push 10 Swings  ➡️  🔄 Next Friend’s Turn! = 2 Happy Friends","explanation":"Waiting for our turn can feel hard, yet taking turns means EVERYONE gets to play happily! \"May I play next after you?\" is a superhero friend sentence.","indianExample":"During recess, sharing slices of orange or waiting calmly at the slide keeps games fun.","funFact":"Sharing a smile actually makes your own brain release happy feel-good energy!","askNyraPrompt":"NYRA, teach me 2 friendly words to ask for a turn on a swing!"},{"id":"ls-4-2","title":"Eat a Rainbow Tiffin & Stay Safe From Hot/Sharp Things","hindiTitle":"रंग-बिरंगा टिफिन और सुरक्षित हाथ","emojiVisual":"🥕🍊🥬🥗 Healthy Rainbow   |   🔥🔪🚫 Stay Back From Stove & Scissors!","explanation":"Eating colorful foods—orange carrots, green spinach, yellow dal, white curd—gives superpowers to run and think! And in the kitchen, hot pans, knives, and matchboxes are STRICTLY for adults.","indianExample":"Drink fresh homemade buttermilk (*chaas*) or lemon water instead of sugary fizzy drinks!","funFact":"Orange carrots help eyes see crisp and bright!","askNyraPrompt":"NYRA, help me build a yummy colorful LKG tiffin box!"}],"activity":{"kind":"classify","title":"Safe to Touch vs Ask Grown-Up!","instruction":"Sort harmless play items vs dangerous kitchen/tool hazards.","leftBucketLabel":"🧸 Safe for Kids","rightBucketLabel":"⚠️ Adults Only","classifyItems":[{"id":"s1","label":"Soft Ball","emoji":"⚽","bucket":"left"},{"id":"s2","label":"Hot Kettle / Gas","emoji":"🫖","bucket":"right"},{"id":"s3","label":"Storybook","emoji":"📖","bucket":"left"},{"id":"s4","label":"Sharp Kitchen Knife","emoji":"🔪","bucket":"right"}],"successMessage":"Safe kitchen explorer! Always stay clear of hot & sharp tools!"},"quiz":[{"id":"ls-4-q1","prompt":"You see a shiny bottle of floor cleaner under the sink. What should you do?","emoji":"🚫","options":["Leave it alone and NEVER taste or open it","Smell or sip it","Pour it on toys"],"correctAnswer":"Leave it alone and NEVER taste or open it","hint":"Cleaning bottles are unsafe poisons!","explanation":"Never open, sniff, or taste medicines or cleaning bottles without a parent."},{"id":"ls-4-q2","prompt":"Your friend is riding the tricycle you want right now. What is kind?","emoji":"🚲","options":["Ask politely: \"Can I have the next turn?\" and wait kindly","Push them off","Kick the wheel"],"correctAnswer":"Ask politely: \"Can I have the next turn?\" and wait kindly","hint":"Gentle words win turns cleanly!","explanation":"Asking nicely and waiting safely keeps playtime joyful for everyone."},{"id":"ls-4-q3","prompt":"Which tiffin snack gives long-lasting energy for learning?","emoji":"🍱","options":["Idli / Paratha roll with fruit slices","Only chips and soda","Three chocolate bars"],"correctAnswer":"Idli / Paratha roll with fruit slices","hint":"Look for real grains + colorful fruit!","explanation":"Wholesome homemade food and fruit power muscles and bright brains."}],"realLifeChallenge":{"title":"Eat 3 Colors Today","instruction":"Count 3 naturally colorful healthy foods on your plates today (e.g., yellow dal, green cucumber, red tomato/apple)!","familyTip":"Let your child help pack their steel water bottle before bedtime."},"badge":{"id":"badge-ls-4","title":"Safety & Share Star","emoji":"🌈"}},"5":{"zoneId":"life_skills_sel","classAge":5,"className":"UKG","pedagogyTier":"play","moduleTitle":"Road Signals, Safe Circle & Memorizing Help Info","hindiSubtitle":"सड़क के नियम, सुरक्षित स्पर्श और आपात मदद","ncertGoalNote":"Traffic light & zebra-crossing habits + Safe/Unsafe touch & trusted adult circle","lessons":[{"id":"ls-5-1","title":"Red Means Stop! Zebra Crossing Rules","hindiTitle":"लाल बत्ती, हरी बत्ती और ज़ेबरा क्रॉसिंग","emojiVisual":"🔴 STOP   🟡 WAIT   🟢 GO   •   🚶 Look Right–Left–Right With Adult!","explanation":"Never run into a road after a rolling ball! Hold a parent’s hand firmly, use the white Zebra stripes, and check BOTH directions even on quiet streets.","indianExample":"Wear a bicycle helmet on your head and buckle car seatbelts every single ride!","funFact":"White stripes on the road are called a Zebra Crossing because they match zebra stripes!","askNyraPrompt":"NYRA, quiz me on Red, Yellow, and Green traffic lights!"},{"id":"ls-5-2","title":"My Body Belongs to Me (Safe vs Unsafe Touch)","hindiTitle":"सुरक्षित घेरा और \"ना\" कहने की हिम्मत","emojiVisual":"🤗 Happy Safe Hug (With Trusted Parent)  |  ✋ Loud \"NO!\" + Tell Mama/Teacher!","explanation":"A SAFE touch feels caring, like Mama’s hug, Grandpa’s high-five, or a doctor checking you WITH your parent right beside you! An UNSAFE touch feels scary, confusing, or asks you to keep a \"secret.\" Say loud \"NO!\", run to a safe place, and ALWAYS tell your trusted adults!","indianExample":"Never accept sweets or car rides from strangers—memorize your parent’s full name and phone corner!","funFact":"It is NEVER your fault if someone breaks a touch rule—trusted parents always want to protect you!","askNyraPrompt":"NYRA, gently review the 3-step Safe Circle rule (\"NO, Go, Tell\") for UKG!"}],"activity":{"kind":"sequence","title":"Safe Street Crossing Order!","instruction":"Put the 3 safe steps to cross the road with your parent in order.","sequenceSteps":[{"id":"tr1","label":"Hold Parent’s Hand at Curb","emoji":"🤝","order":1},{"id":"tr2","label":"Look Right, Left & Wait for Green","emoji":"👀","order":2},{"id":"tr3","label":"Walk Calmly on Zebra Stripes","emoji":"🚶","order":3}],"successMessage":"Road safety hero! Hold hand → Look both ways → Walk cleanly!"},"quiz":[{"id":"ls-5-q1","prompt":"A kind-looking stranger at the park gate offers chocolate if you walk away with them. What do you do?","emoji":"✋","options":["Say loud \"NO!\", step back, and run straight to your parent/teacher","Take the candy and follow quietly","Whisper back"],"correctAnswer":"Say loud \"NO!\", step back, and run straight to your parent/teacher","hint":"Never leave with someone without your parent’s direct permission!","explanation":"Stay in public view, say firm NO, and run immediately to your trusted adult."},{"id":"ls-5-q2","prompt":"What does a YELLOW traffic light tell drivers?","emoji":"🚦","options":["Slow down and prepare to stop safely","Drive twice as fast","Honk loudly"],"correctAnswer":"Slow down and prepare to stop safely","hint":"Caution between Green and Red!","explanation":"Yellow warns vehicles to slow down cleanly before Red."},{"id":"ls-5-q3","prompt":"If anyone ever tells you \"Keep this weird touch a secret from your parents,\" what should you do?","emoji":"🛡️","options":["Tell your parents or teacher RIGHT AWAY—never keep unsafe secrets!","Stay silent forever","Hide in your room"],"correctAnswer":"Tell your parents or teacher RIGHT AWAY—never keep unsafe secrets!","hint":"Safe surprises (like a birthday card) feel joyful; unsafe secrets never do!","explanation":"Always tell a trusted adult immediately; real grown-ups keep you safe."}],"realLifeChallenge":{"title":"Learn Your Parent’s Name & Safe Codeword","instruction":"Practice saying your full name, your parent’s real first & last name, and your home area name with a parent!","familyTip":"Consider choosing a fun secret family safety password if someone else ever needs to pick up your child."},"badge":{"id":"badge-ls-5","title":"Safety Shield Star","emoji":"🚦"}},"6":{"zoneId":"life_skills_sel","classAge":6,"className":"1st Class","pedagogyTier":"foundational","moduleTitle":"Active Listening, Empathy & Tidying Up","hindiSubtitle":"ध्यान से सुनना, सहानुभूति और अपनी चीज़ें संभालना","ncertGoalNote":"Communication skills (eye contact/listening), empathy & personal responsibility","lessons":[{"id":"ls-6-1","title":"Whole-Body Listening & Kind Voices","hindiTitle":"पूरे ध्यान से सुनने की कला","emojiVisual":"👀 Eyes Look  •  👂 Ears Listen  •  👄 Wait Turn Before Speaking","explanation":"Great communicators don’t interrupt while someone is talking! Looking kindly at the speaker and waiting for a pause shows respect—and helps you actually understand your friend’s story!","indianExample":"In a class circle, nodding gently while your classmate speaks makes even shy kids feel brave!","funFact":"Empathy means asking: \"How would I feel if I dropped my lunch box today?\"","askNyraPrompt":"NYRA, teach me a quick 3-sentence way to comfort a sad classmate!"},{"id":"ls-6-2","title":"Packing Your Own School Bag Night Before","hindiTitle":"रात को खुद अपना बस्ता तैयार करना","emojiVisual":"📚 Books + ✏️ Pencil Pouch + 💧 Clean Bottle  ➡️  🌅 Calm Morning!","explanation":"Checking your timetable at 8 PM and keeping shoes and socks ready avoids noisy, stressed mornings! Small daily habits grow strong independence.","indianExample":"Sharpening two pencils the night before means never panicking right before a spelling test!","funFact":"Taking just 5 minutes to tidy desk toys saves 20 minutes of searching next morning!","askNyraPrompt":"NYRA, create a 4-point night checklist for a 1st Class student!"}],"activity":{"kind":"classify","title":"Friendly Communicator vs Rude Interrupter!","instruction":"Sort warm conversation skills from interrupting habits.","leftBucketLabel":"💬 Kind Listener","rightBucketLabel":"🙈 Oops Interrupter","classifyItems":[{"id":"k1","label":"Wait Until Friend Finishes","emoji":"👂","bucket":"left"},{"id":"k2","label":"Shout Over Someone Talking","emoji":"📢","bucket":"right"},{"id":"k3","label":"Ask \"Are You Okay?\"","emoji":"💛","bucket":"left"},{"id":"k4","label":"Walk Away Mid-Story","emoji":"🚶","bucket":"right"}],"successMessage":"Empathy & listening superhero!"},"quiz":[{"id":"ls-6-q1","prompt":"A new student joins your class looking shy at lunch. What shows true EMPATHY?","emoji":"💛","options":["Smile, introduce yourself, and invite them to sit near you","Stare silently and whisper","Ignore them all week"],"correctAnswer":"Smile, introduce yourself, and invite them to sit near you","hint":"Think of how you would hope someone welcomes YOU on Day 1!","explanation":"Empathy turns shy moments into lifelong friendships."},{"id":"ls-6-q2","prompt":"Why is packing your school bag before bedtime such a smart habit?","emoji":"🎒","options":["Mornings stay calm and you never forget books or water","Bags sleep better full of toys","It adds extra homework"],"correctAnswer":"Mornings stay calm and you never forget books or water","hint":"Save morning rush!","explanation":"Evening prep gives calm breakfasts and zero missing items."},{"id":"ls-6-q3","prompt":"When you accidentally bump someone’s elbow in the hallway, what should you say right away?","emoji":"🤝","options":["\"Sorry! Are you okay?\"","\"Watch out yourself!\"","Run away quickly"],"correctAnswer":"\"Sorry! Are you okay?\"","hint":"Apologizing shows strength, not weakness!","explanation":"Sincere apologies fix accidents gently and respectfully."}],"realLifeChallenge":{"title":"Solo Bag-Pack Tonight","instruction":"Pack your school books, pencil pouch, and handkerchief yourself tonight, then ask a parent to give your checklist a thumbs-up!","familyTip":"Celebrate effort and routine rather than rushing in morning!"},"badge":{"id":"badge-ls-6","title":"Empathy & Ready Star","emoji":"🎒"}},"7":{"zoneId":"life_skills_sel","classAge":7,"className":"2nd Class","pedagogyTier":"foundational","moduleTitle":"Fixing Disagreements Peacefully & Saying Clear Boundaries","hindiSubtitle":"झगड़ा शांति से सुलझाना और स्पष्ट संवाद","ncertGoalNote":"Conflict resolution (\"I feel\" statements), anti-bullying awareness & fire/first-aid basics","lessons":[{"id":"ls-7-1","title":"Using \"I Feel\" Statements Instead of Blaming","hindiTitle":"\"मुझे कैसा लगा\" बोलकर बात सुलझाना","emojiVisual":"😠 \"YOU always ruin it!\"  vs  😌 \"I felt sad when my drawing tore. Let’s fix it together.\"","explanation":"Pointing fingers starts shouting matches! Starting with \"I feel ___ when ___\" shares your honest heart calmly so friends listen and apologize smoothly.","indianExample":"If two siblings want the same bat, try Rock-Paper-Scissors or a 5-minute timer swap!","funFact":"Compromise means BOTH friends win a fair solution!","askNyraPrompt":"NYRA, turn \"You stole my eraser!\" into a calm \"I feel\" sentence!"},{"id":"ls-7-2","title":"Tiny Scrape First-Aid & Standing Up Against Teasing","hindiTitle":"छोटी चोट पर प्राथमिक मदद और चिढ़ाने से बचाव","emojiVisual":"🩹 Clean Water + Band-Aid + Tell Teacher  |  🛡️ Teasing ≠ Just a Joke","explanation":"For a small knee scrape, wash gently with clean water, tell a parent/teacher, and cover cleanly—never rub mud on wounds! Also remember: repeated mean teasing is NOT funny—kind friends say \"Stop, that’s not okay!\" and tell an adult.","indianExample":"Memorize India’s emergency helpline **112** (and **108** ambulance) for real grown-up emergencies!","funFact":"Standing beside a teased friend is one of the bravest superpowers!","askNyraPrompt":"NYRA, give me 2 polite brave lines to stop unkind teasing at school!"}],"activity":{"kind":"experiment","title":"Two Friends Want the Same Board Game!","instruction":"Kabir wants Snakes & Ladders; Diya wants Carrom right now during 20 minutes of free time. What solves this fairly?","prompt":"Pick the fair win-win solution:","options":[{"label":"Play 10 mins Carrom, then 10 mins Snakes & Ladders!","emoji":"🤝","correct":true,"feedback":"Fair turn-taking! Both friends enjoy their favorite game!"},{"label":"Hide the dice so nobody plays","emoji":"😤","correct":false,"feedback":"Nobody wins when we spoil the game!"},{"label":"Shout louder to win","emoji":"📢","correct":false,"feedback":"Volume never makes something fair!"}],"successMessage":"Peaceful peacemaker mastery!"},"quiz":[{"id":"ls-7-q1","prompt":"Which sentence solves a clash calmly using an \"I Feel\" message?","emoji":"💬","options":["\"I felt frustrated when my ruler broke—could we be more careful next time?\"","\"You are the worst friend ever!\"","\"I’ll break your pencil back!\""],"correctAnswer":"\"I felt frustrated when my ruler broke—could we be more careful next time?\"","hint":"Talk about your feelings rather than calling names!","explanation":"\"I feel\" statements keep friends talking without escalating anger."},{"id":"ls-7-q2","prompt":"If a classmate gets a small knee scrape in the playground, what helps safely?","emoji":"🩹","options":["Walk them calmly to the teacher/nurse and rinse cleanly with water","Put playground sand on it","Laugh at their tear"],"correctAnswer":"Walk them calmly to the teacher/nurse and rinse cleanly with water","hint":"Keep germs out and call an adult!","explanation":"Clean water and adult/nurse care prevent infection safely."},{"id":"ls-7-q3","prompt":"What is India’s single national emergency helpline number for police/fire/urgent help?","emoji":"📞","options":["112","99999","0000"],"correctAnswer":"112","hint":"One–One–Two!","explanation":"112 connects to urgent emergency services across India (only call in real emergencies with/for adults!)."}],"realLifeChallenge":{"title":"Make a Mini \"Calm-Down Plan\"","instruction":"Draw 3 calm tools you like when angry (e.g., 5 deep breaths, drink cool water, draw on paper, hug a pillow) on an index card!","familyTip":"Keep emergency contacts (parents, neighbor, 112) clearly visible near the home phone/fridge."},"badge":{"id":"badge-ls-7","title":"Peacemaker Star","emoji":"🕊️"}},"8":{"zoneId":"life_skills_sel","classAge":8,"className":"3rd Class","pedagogyTier":"conceptual","moduleTitle":"Teamwork Roles, Focus Routine & Growth Mindset","hindiSubtitle":"टीमवर्क, समय प्रबंधन और \"मैं सीख सकता हूँ\" सोच","ncertGoalNote":"Collaborative group roles, daily time balance & \"Power of Yet\" resilience","lessons":[{"id":"ls-8-1","title":"The Magic Word \"YET\" (Growth Mindset)","hindiTitle":"जादुई शब्द \"अभी तक\" (Growth Mindset)","emojiVisual":"😕 \"I can’t do division!\"  ➡️  🌟 \"I haven’t mastered division YET!\"","explanation":"Mistakes mean your brain is stretching new pathways—like lifting light weights builds muscles! Adding \"YET\" turns quitting into steady practice!","indianExample":"Even champions like Neeraj Chopra and P.V. Sindhu missed thousands of throws and shots while practicing!","funFact":"Saying \"What step confused me?\" solves harder problems 3× faster than calling yourself \"bad at Math\"!","askNyraPrompt":"NYRA, give me an encouraging Class 3 mindset boost for a tricky topic!"},{"id":"ls-8-2","title":"Team Roles Make Group Projects Joyful","hindiTitle":"समूह कार्य में सबकी अलग भूमिका","emojiVisual":"🎨 Illustrator + 📝 Writer + 🎤 Presenter + ⏰ Timekeeper = Dream Team!","explanation":"When 4 classmates work on a science chart, one draws neatly, one checks spellings, one gathers facts, and one speaks clearly! Listening to shy teammates’ ideas often reveals the brightest spark.","indianExample":"In team relay races, cheering teammates matters just as much as running fast!","funFact":"Good leaders listen MORE than they boss people around.","askNyraPrompt":"NYRA, how can our 4-student group divide work fairly on an EVS poster?"}],"activity":{"kind":"classify","title":"Growth Mindset vs Fixed Give-Up!","instruction":"Sort encouraging \"Power of Yet\" thoughts vs hopeless phrases.","leftBucketLabel":"🌱 Growth Mindset","rightBucketLabel":"🧱 Fixed Give-Up","classifyItems":[{"id":"gm1","label":"\"Mistakes teach me where to look!\"","emoji":"💡","bucket":"left"},{"id":"gm2","label":"\"I’ll never understand this!\"","emoji":"😔","bucket":"right"},{"id":"gm3","label":"\"Let me ask NYRA for a hint!\"","emoji":"🤖","bucket":"left"},{"id":"gm4","label":"\"Practice is pointless!\"","emoji":"🚫","bucket":"right"}],"successMessage":"Resilient learner mindset unlocked!"},"quiz":[{"id":"ls-8-q1","prompt":"You scored lower than expected on a tricky test. What shows a true GROWTH MINDSET?","emoji":"🌱","options":["Check which question tripped you up and practice that step calmly","Crumple the paper and quit","Blame the pencil"],"correctAnswer":"Check which question tripped you up and practice that step calmly","hint":"Errors are clues for where to grow next!","explanation":"Reviewing mistakes builds confidence and mastery every time."},{"id":"ls-8-q2","prompt":"In a 4-person school project, one quiet teammate hasn’t spoken yet. What should a great teammate do?","emoji":"🤝","options":["Ask kindly: \"What idea do you want to share for our chart?\"","Speak over everyone alone","Ignore them"],"correctAnswer":"Ask kindly: \"What idea do you want to share for our chart?\"","hint":"Great teams unlock every voice!","explanation":"Inviting quiet voices ensures everyone contributes their best talent."},{"id":"ls-8-q3","prompt":"You have 1 hour after school: homework takes 25 mins, play takes 25 mins, packing bag takes 10 mins. What happens if you watch cartoons for 45 mins first?","emoji":"⏰","options":["Play & homework get squeezed into bedtime stress","The clock adds extra hours","Homework vanishes"],"correctAnswer":"Play & homework get squeezed into bedtime stress","hint":"Time blocks stay 60 mins total!","explanation":"Finishing priority tasks first leaves relaxed worry-free playtime."}],"realLifeChallenge":{"title":"Reframe 1 Hard Thing With \"YET\"","instruction":"Tell a parent one skill you are practicing right now (cycling, reading Hindi cleanly, division) using \"I am getting better at ___ every week!\"","familyTip":"Praise specific effort (\"You kept practicing carefully!\") instead of just \"You’re smart.\""},"badge":{"id":"badge-ls-8","title":"Growth Mindset Star","emoji":"🌟"}},"9":{"zoneId":"life_skills_sel","classAge":9,"className":"4th Class","pedagogyTier":"conceptual","moduleTitle":"Stage Confidence, Peer Pressure & Stress Care","hindiSubtitle":"मंच पर आत्मविश्वास, साथी दबाव से बचाव और मानसिक शांति","ncertGoalNote":"Clear public speaking prep, resisting unsafe peer pressure & balanced rest","lessons":[{"id":"ls-9-1","title":"Conquering Stage Butterflies (Speak With Structure)","hindiTitle":"मंच के डर को आत्मविश्वास में बदलना","emojiVisual":"🎤 Smile + Deep Breath  ➡️  1️⃣ Opening  2️⃣ 2 Clear Points  3️⃣ Thank You!","explanation":"Even famous speakers feel tummy butterflies before going on stage! That energy simply means your body cares. Structure your talk in 3 simple parts, make eye contact with one friendly listener, and speak slightly slower than usual.","indianExample":"Practicing your class assembly poem aloud twice in front of a mirror cuts stage jitters by half!","funFact":"Pausing 1 second between sentences makes you sound super confident!","askNyraPrompt":"NYRA, help me write a crisp 3-line morning assembly speech on Kindness!"},{"id":"ls-9-2","title":"Saying \"No Thanks!\" to Unsafe Peer Pressure","hindiTitle":"साथियों के गलत दबाव में \"नहीं\" कहने का साहस","emojiVisual":"✋ True Friends Respect Safe Boundaries • Dare ≠ Brave!","explanation":"Sometimes friends tease \"Come on, try copying homework!\" or \"Cross without looking, don’t be scared!\" True bravery means saying a relaxed, firm \"No thanks, I’m not doing that\"—even when the crowd laughs.","indianExample":"Changing the subject—\"Hey, let’s race around the field instead!\"—lets you step away gracefully!","funFact":"Real friends respect your safety and honesty; fake dares never show true friendship.","askNyraPrompt":"NYRA, give me 3 cool ways to say NO when friends dare something unsafe!"}],"activity":{"kind":"experiment","title":"Handle a Tricky Playground Dare!","instruction":"Two older kids dare you to climb onto an unsafe broken fence (\"If you don’t, you’re a baby!\"). What shows REAL confidence?","prompt":"Choose the strongest response:","options":[{"label":"\"No thanks, that’s unsafe. Let’s play cricket instead!\"","emoji":"🦁","correct":true,"feedback":"True courage! Respecting your own safety beats any silly dare!"},{"label":"Climb anyway to prove them wrong","emoji":"🩹","correct":false,"feedback":"Getting hurt over a dare is risky, not brave!"},{"label":"Throw stones at them","emoji":"❌","correct":false,"feedback":"Aggression never helps—walk away calmly!"}],"successMessage":"Confident decision-maker!"},"quiz":[{"id":"ls-9-q1","prompt":"Right before speaking at school assembly, your heart beats fast. What is the BEST reset?","emoji":"🌬️","options":["Take 2 slow belly breaths, stand tall, and start steadily","Sprint out the gate","Rush 100 words in 5 seconds"],"correctAnswer":"Take 2 slow belly breaths, stand tall, and start steadily","hint":"Slow breath calms nerves instantly!","explanation":"Slow exhalations steady your voice and pace naturally."},{"id":"ls-9-q2","prompt":"Why is 9–10 hours of calm sleep WITHOUT screens near bed crucial for 4th Graders?","emoji":"😴","options":["Sleep locks in new memories, repairs muscles & brightens mood","Only babies sleep","Cartoons teach while sleeping"],"correctAnswer":"Sleep locks in new memories, repairs muscles & brightens mood","hint":"Brains organize everything you learned while you rest!","explanation":"Quality sleep powers focus, growth, emotional calm, and memory."},{"id":"ls-9-q3","prompt":"A friend offers to let you copy their entire homework so you can play earlier. Why say NO?","emoji":"📝","options":["Copying steals YOUR chance to learn and breaks honesty","Writing hurts pens","Teachers love identical mistakes"],"correctAnswer":"Copying steals YOUR chance to learn and breaks honesty","hint":"Ask them to EXPLAIN one question instead of copying!","explanation":"Asking for an explanation helps you actually build skill honestly."}],"realLifeChallenge":{"title":"60-Second Family Mini-Talk","instruction":"Give a calm 3-sentence mini-speech to your family tonight about your favorite hobby or book—using eye contact and a smiling \"Thank you!\"","familyTip":"Clap warmly and share ONE specific thing your child did well (clear voice, smile, steady speed)."},"badge":{"id":"badge-ls-9","title":"Brave Voice Leader","emoji":"🎤"}},"10":{"zoneId":"life_skills_sel","classAge":10,"className":"5th Class","pedagogyTier":"conceptual","moduleTitle":"Goal Setting (SMART Steps), Leadership & Gratitude","hindiSubtitle":"लक्ष्य निर्धारण, नेतृत्व और कृतज्ञता","ncertGoalNote":"Self-management, inclusive leadership, handling disappointment & gratitude journaling","lessons":[{"id":"ls-10-1","title":"Turning Big Wishes Into Clear Weekly Steps","hindiTitle":"बड़े सपनों को साप्ताहिक कदमों में बदलना","emojiVisual":"🥅 \"Get fit\" (Vague)  vs  ✅ \"Cycle or skip rope 15 mins every Mon-Wed-Fri!\"","explanation":"Wishes stay dreams until you add WHEN, HOW LONG, and HOW YOU WILL CHECK! Small 15-minute steady habits beat 3-hour last-minute cramming every single time.","indianExample":"Reading just 5 pages of a Hindi or English storybook every night reads 150 pages a month effortlessly!","funFact":"Writing a goal down doubles your chance of actually doing it!","askNyraPrompt":"NYRA, help me break \"Improve my handwriting & reading\" into a 7-day 5th Class plan!"},{"id":"ls-10-2","title":"Inclusive Leadership & Gratitude Reflection","hindiTitle":"सबको साथ लेकर चलना और आभार मानना","emojiVisual":"🦁 Leader Helps Teammates Shine  •  📓 Note 3 Good Things Daily","explanation":"Being House Captain or Team Monitor isn’t about bossing—it is about spotting where teammates feel stuck, giving fair credit, and saying \"Well done!\" And ending each day naming 3 small things you feel thankful for trains your mind to notice joy.","indianExample":"Thrive together by thanking bus drivers, school helpers (*didis/bhaiyas*), and grandparents every week!","funFact":"Studies show gratitude habits noticeably lower exam stress!","askNyraPrompt":"NYRA, give me 2 thoughtful leadership scenarios for a 5th Class student!"}],"activity":{"kind":"sequence","title":"Lead a School Eco-Club Drive!","instruction":"Put these 4 inclusive leadership steps in logical order from planning to thank-you.","sequenceSteps":[{"id":"ld1","label":"Listen to Team Ideas Fairly","emoji":"👂","order":1},{"id":"ld2","label":"Assign Clear Tasks & Dates","emoji":"📋","order":2},{"id":"ld3","label":"Help Anyone Stuck Midway","emoji":"🤝","order":3},{"id":"ld4","label":"Celebrate & Thank Every Helper","emoji":"🏆","order":4}],"successMessage":"Servant-leader spirit! Every teammate shines!"},"quiz":[{"id":"ls-10-q1","prompt":"Which study goal is clearest and easiest to actually finish this week?","emoji":"🎯","options":["\"Practice 10 minutes of reading aloud after evening milk Mon–Fri\"","\"Read everything someday\"","\"Read 200 books tonight\""],"correctAnswer":"\"Practice 10 minutes of reading aloud after evening milk Mon–Fri\"","hint":"Specific time + realistic daily step!","explanation":"Clear, small, scheduled habits beat vague giant promises."},{"id":"ls-10-q2","prompt":"Your team lost a close inter-house quiz despite working hard. What does a great leader say?","emoji":"🤝","options":["\"Proud of our effort! Let’s congratulate the winners and note what to sharpen next time.\"","\"It was all your fault for missing Question 2!\"","\"Never joining a quiz again!\""],"correctAnswer":"\"Proud of our effort! Let’s congratulate the winners and note what to sharpen next time.\"","hint":"Sportsmanship + gracious growth!","explanation":"Gracious sportsmanship builds trust and motivates teams to come back stronger."},{"id":"ls-10-q3","prompt":"Before criticizing a classmate’s mistake, what 3-question kindness filter helps?","emoji":"💭","options":["\"Is it True? Is it Kind? Is it Helpful?\"","\"Is it Loud? Is it Funny? Is it Mean?\"","\"Will it go viral?\""],"correctAnswer":"\"Is it True? Is it Kind? Is it Helpful?\"","hint":"THINK before speaking!","explanation":"True, Kind, and Helpful feedback strengthens relationships cleanly."}],"realLifeChallenge":{"title":"Write 1 Real Thank-You Note","instruction":"Write a 2-sentence handwritten thank-you card to someone who quietly helps you (grandparent, school helper, teacher, or sibling)!","familyTip":"Start a dinner ritual where everyone shares 1 good thing from their day."},"badge":{"id":"badge-ls-10","title":"Kind Leader Star","emoji":"👑"}}},"art_creativity":{"3":{"zoneId":"art_creativity","classAge":3,"className":"Nursery","pedagogyTier":"play","moduleTitle":"Color Mixing Magic & Happy Beats","hindiSubtitle":"रंगों का जादू और ताल-लय का खेल","ncertGoalNote":"Playful primary color mixing, rhythm clapping & body expression","lessons":[{"id":"ac-3-1","title":"When Two Colors Hug, a New Color Pops!","hindiTitle":"जब दो रंग मिलें तो नया रंग बने","emojiVisual":"🔴 Red + 🟡 Yellow = 🟠 ORANGE!   •   🔵 Blue + 🟡 Yellow = 🟢 GREEN!","explanation":"Red, Yellow, and Blue are the 3 magic Primary Colors! Mixing Red and Yellow finger paint makes sunny Marigold Orange—just like magic in a bowl!","indianExample":"Turmeric yellow (*haldi*) and natural red kumkum make bright orange tika colors!","funFact":"Every rainbow color begins from mixing primary colors!","askNyraPrompt":"NYRA, ask me a fun color-mixing riddle for Nursery!"},{"id":"ac-3-2","title":"Clap, Stomp & Dance With Sound Beats!","hindiTitle":"ताली और पैरों की लय पहचानो","emojiVisual":"👏 Clap–Clap   🦶 Stomp   👏 Clap–Clap   🦶 Stomp!","explanation":"Music lives inside our hands and feet! Making slow gentle beats like falling rain (pat-pat-pat) or steady marching beats wakes up our listening ears.","indianExample":"Listening to festive Dholak beats or clapping along to folk rhymes!","funFact":"Even spoons gently tapped on a plastic bowl make cozy rhythms!","askNyraPrompt":"NYRA, invent a 4-beat clap-and-giggle rhyme for Nursery!"}],"activity":{"kind":"experiment","title":"Magic Paint Mixer!","instruction":"You pour shiny BLUE paint 🔵 and sunny YELLOW paint 🟡 into a cup and stir! What brand-new color appears?","prompt":"Tap the new mixed color:","options":[{"label":"Leafy GREEN!","emoji":"🟢","correct":true,"feedback":"Magic! Blue + Yellow = Fresh Leafy Green!"},{"label":"Pitch Black","emoji":"⚫","correct":false,"feedback":"Blue and yellow are bright colors—they turn leafy green!"},{"label":"Snow White","emoji":"⚪","correct":false,"feedback":"Mixing two bright paints makes a bright middle color!"}],"successMessage":"Yay! You’re a Rainbow Color Magician!"},"quiz":[{"id":"ac-3-q1","prompt":"Mix Red paint 🔴 and Yellow paint 🟡 together. Which color appears?","emoji":"🎨","options":["Orange 🟠","Green 🟢","Blue 🔵"],"correctAnswer":"Orange 🟠","hint":"Like a juicy Nagpur orange fruit!","explanation":"Red + Yellow creates bright Orange!"},{"id":"ac-3-q2","prompt":"Which two colors mix to make Purple/Violet 🟣?","emoji":"🍇","options":["Red 🔴 + Blue 🔵","Yellow 🟡 + White ⚪","Green 🟢 + Yellow 🟡"],"correctAnswer":"Red 🔴 + Blue 🔵","hint":"Think of juicy grapes!","explanation":"Red + Blue makes royal Purple!"},{"id":"ac-3-q3","prompt":"Which tool is safest and most fun for drawing big rainbow clouds?","emoji":"🖍️","options":["Chunky wax crayons or finger paint","Sharp ink pen","Kitchen fork"],"correctAnswer":"Chunky wax crayons or finger paint","hint":"Easy for tiny hands to grip!","explanation":"Thick crayons help little fingers build steady grip while creating joy."}],"realLifeChallenge":{"title":"Leaf Printing Magic","instruction":"Dip one fallen leaf lightly in water-paint (or place paper OVER a leaf and rub gently with a crayon!) to reveal secret leaf veins!","familyTip":"Pin your child’s art proudly on the fridge to boost creative confidence!"},"badge":{"id":"badge-ac-3","title":"Rainbow Mixer","emoji":"🎨"}},"4":{"zoneId":"art_creativity","classAge":4,"className":"LKG","pedagogyTier":"play","moduleTitle":"Sa-Re-Ga-Ma Swaras & Shape Pictures","hindiSubtitle":"सा-रे-गा-मा के सुर और आकार से चित्र","ncertGoalNote":"Discovering Indian musical notes (Swaras) & turning simple shapes into art","lessons":[{"id":"ac-4-1","title":"Climbing the 7 Musical Stairs: Sa Re Ga Ma!","hindiTitle":"संगीत की सात सीढ़ियाँ: सा-रे-गा-मा","emojiVisual":"🎶 Sa  →  Re  →  Ga  →  Ma  →  Pa  →  Dha  →  Ni  →  Sa!","explanation":"Indian music climbs 7 sweet notes like joyful stairs—Sa, Re, Ga, Ma, Pa, Dha, Ni! Going UP sounds brighter and higher like climbing steps; coming DOWN slides back softly!","indianExample":"Even sweet temple bells, wooden *bansuri* flutes, and *harmoniums* play Sa-Re-Ga-Ma!","funFact":"\"Sa\" and \"Pa\" sound so steady together that instruments tune to them!","askNyraPrompt":"NYRA, teach me a playful animal rhyme about Sa-Re-Ga-Ma!"},{"id":"ac-4-2","title":"Turn Circles & Triangles Into Rockets & Owls!","hindiTitle":"गोले और त्रिकोण से अनोखे चित्र बनाना","emojiVisual":"🔺 + 🟥 + ⭕  ➡️  🚀 Rocket or 🏠 Cozy House!","explanation":"Every great artist starts with simple shapes! Stack a square, triangle roof, and small circle window—suddenly you drew a cozy house or a space rocket!","indianExample":"Traditional *Warli* folk artists in Maharashtra tell whole village stories using ONLY circles, triangles, and lines!","funFact":"A circle + two triangle ears + three whisker lines instantly becomes a kitty!","askNyraPrompt":"NYRA, give me 3 easy shape-drawing ideas for LKG!"}],"activity":{"kind":"sequence","title":"Climb the First 4 Swaras!","instruction":"Tap the Indian musical ladder notes in climbing order from 1 to 4.","sequenceSteps":[{"id":"sw1","label":"Sa (सा)","emoji":"🎵","order":1},{"id":"sw2","label":"Re (रे)","emoji":"🎶","order":2},{"id":"sw3","label":"Ga (गा)","emoji":"🎼","order":3},{"id":"sw4","label":"Ma (मा)","emoji":"✨","order":4}],"successMessage":"Melodious! Sa–Re–Ga–Ma rises bright and sweet!"},"quiz":[{"id":"ac-4-q1","prompt":"Which wooden flute is blown gently sideways to make sweet Indian melodies?","emoji":"🎶","options":["Bansuri (Flute)","Drum","Hammer"],"correctAnswer":"Bansuri (Flute)","hint":"Made of hollow bamboo!","explanation":"The bamboo Bansuri produces soothing wind music in Indian folk & classical traditions."},{"id":"ac-4-q2","prompt":"Which shapes combine nicely to draw an Ice-Cream Cone?","emoji":"🍦","options":["Circle scoop on an upside-down Triangle","Five long rectangles","Only straight dashes"],"correctAnswer":"Circle scoop on an upside-down Triangle","hint":"Round scoop + pointy cone!","explanation":"Simple shapes join together into recognizable, fun art!"},{"id":"ac-4-q3","prompt":"In Indian music, which note starts the 7-note Swara ladder?","emoji":"🪜","options":["Sa","Zed","Beep"],"correctAnswer":"Sa","hint":"Sa-Re-Ga-Ma...","explanation":"Sa (Shadja) is the joyful home note of the 7 Swaras."}],"realLifeChallenge":{"title":"Draw a House Using 3 Shapes","instruction":"Draw a picture using at least 1 circle (sun/wheel), 1 square (house/bus), and 1 triangle (roof/tree) and color it cheerfully!","familyTip":"Ask your child to make up a 2-line story about who lives inside their drawing."},"badge":{"id":"badge-ac-4","title":"Swara & Shape Artist","emoji":"🎵"}},"5":{"zoneId":"art_creativity","classAge":5,"className":"UKG","pedagogyTier":"play","moduleTitle":"Beginning–Middle–End Stories & Origami Folding","hindiSubtitle":"कहानी के तीन भाग और कागज़ मोड़ने की कला","ncertGoalNote":"Storytelling structure (3-part narrative) & fine-motor paper folding craft","lessons":[{"id":"ac-5-1","title":"Every Good Story Has 3 Cozy Parts","hindiTitle":"कहानी की शुरुआत, बीच और अंत","emojiVisual":"🌅 Beginning (Who & Where) ➡️ ⚡ Middle (Problem!) ➡️ 🌈 End (Solved!)","explanation":"When you invent a story—about a brave squirrel or a lost kite—start with WHO & WHERE (Beginning), add an exciting adventure or problem (Middle), and wrap up with how they solved it (End)!","indianExample":"Puppet shows (*Kathputli* of Rajasthan) act out funny beginning-middle-end stories with colorful puppets!","funFact":"Changing your voice—high squeak for mouse, deep boom for lion—brings stories alive!","askNyraPrompt":"NYRA, start a silly Beginning for a UKG story so I can finish the Middle and End!"},{"id":"ac-5-2","title":"Paper Folding Wonder (Paper Boat & Hat)","hindiTitle":"कागज़ से नाव और टोपी बनाना","emojiVisual":"📄 Square Paper + Crease Folds ➡️ ⛵ Monsoon Paper Boat!","explanation":"Without using glue or scissors, crisp folds turn flat old newspaper into soaring airplanes, cozy paper hats, and monsoon puddle boats! Pressing folds smoothly teaches patience and hand focus.","indianExample":"Floating colorful paper boats down monsoon courtyard streams is a classic Indian childhood joy!","funFact":"Even space telescope solar panels fold up tightly using paper-folding math!","askNyraPrompt":"NYRA, give me easy spoken steps to fold a paper triangle hat!"}],"activity":{"kind":"sequence","title":"Arrange the Story Parts in Order!","instruction":"Put this mini story about \"Kittu the Lost Kite\" from Beginning (1) to End (3).","sequenceSteps":[{"id":"st1","label":"Beginning: Kittu flew a red kite in the park.","emoji":"🪁","order":1},{"id":"st2","label":"Middle: Gusty wind blew the string onto a low bush!","emoji":"💨","order":2},{"id":"st3","label":"End: Dada gently lifted it free and they smiled!","emoji":"🌈","order":3}],"successMessage":"Storyteller star! Clear Beginning → Middle → End!"},"quiz":[{"id":"ac-5-q1","prompt":"Which part of a story introduces the characters and setting?","emoji":"📖","options":["The Beginning","The Very Last Word","The Page Number"],"correctAnswer":"The Beginning","hint":"Once upon a time...","explanation":"The Beginning introduces Who, Where, and What they are doing."},{"id":"ac-5-q2","prompt":"What traditional puppet art from Rajasthan tells musical folk stories using wooden string dolls?","emoji":"🎭","options":["Kathputli","Origami crane","Skywriting"],"correctAnswer":"Kathputli","hint":"\"Kath\" means wood and \"Putli\" means doll!","explanation":"Rajasthan’s Kathputli artisans craft vibrant string puppets for storytelling."},{"id":"ac-5-q3","prompt":"What happens if you reuse old newspaper to fold a paper boat instead of fresh blank paper?","emoji":"⛵","options":["You have fun crafting AND save fresh paper trees!","The boat refuses to float","Clouds disappear"],"correctAnswer":"You have fun crafting AND save fresh paper trees!","hint":"Eco-friendly crafting!","explanation":"Using scrap/newspaper lets you practice folding sustainably."}],"realLifeChallenge":{"title":"Sock Puppet Mini-Show","instruction":"Slip a clean odd sock over your hand, invent a friendly character name, and perform a 30-second Beginning–Middle–End story for family!","familyTip":"Ask what happened in the Middle problem and how the puppet fixed it."},"badge":{"id":"badge-ac-5","title":"Story Weaver","emoji":"🎭"}},"6":{"zoneId":"art_creativity","classAge":6,"className":"1st Class","pedagogyTier":"foundational","moduleTitle":"Warm vs Cool Colors & Meet Indian Instruments","hindiSubtitle":"गर्म-ठंडे रंग और भारतीय वाद्ययंत्र","ncertGoalNote":"Color moods (warm vs cool), folk Rangoli symmetry & percussion/string/wind instruments","lessons":[{"id":"ac-6-1","title":"Warm Sunshine Colors vs Cool Ocean Colors","hindiTitle":"गर्म रंग और ठंडे (शीतल) रंग","emojiVisual":"☀️ Warm: Red, Orange, Yellow   |   🌊 Cool: Blue, Green, Violet","explanation":"Artists pick colors to paint feelings! Red, orange, and yellow feel warm and energetic like bright bonfires or sunflowers. Blue, green, and violet feel calm and refreshing like raindrops and river shade.","indianExample":"Paint a bright summer festival with warm yellows & oranges, and a misty monsoon mountain with cool greens & blues!","funFact":"Dotted *Rangoli* borders often alternate warm & cool petals so designs sparkle!","askNyraPrompt":"NYRA, suggest a colorful festival scene using warm colors and one night scene using cool colors!"},{"id":"ac-6-2","title":"Beat, Blow & Pluck: Meet Tabla, Bansuri & Sitar","hindiTitle":"थाप, फूँक और तार के भारतीय वाद्ययंत्र","emojiVisual":"🥁 Tabla (Tap/Percussion) • 🎶 Bansuri (Wind) • 🎸 Sitar (Strings)","explanation":"Instruments make sound in three joyful families: TAPPING skin drums (Tabla, Mridangam, Dholak), BLOWING air (Bansuri, Shehnai), or PLUCKING vibrating strings (Sitar, Veena, Santoor)!","indianExample":"Even a brass plate struck gently or a clay pot (*Ghatam* in South India!) becomes a rhythmic percussion instrument!","funFact":"Every sound starts when something tiny vibrates back and forth!","askNyraPrompt":"NYRA, describe how Tabla and Sitar sound different for Class 1!"}],"activity":{"kind":"classify","title":"Sort: Warm Colors vs Cool Colors!","instruction":"Put sunny/fiery colors in Warm Mood and soothing ocean/forest colors in Cool Mood.","leftBucketLabel":"☀️ Warm Mood","rightBucketLabel":"🌊 Cool Mood","classifyItems":[{"id":"cl1","label":"Sunny Yellow","emoji":"🟡","bucket":"left"},{"id":"cl2","label":"Sky Blue","emoji":"🔵","bucket":"right"},{"id":"cl3","label":"Fiery Red","emoji":"🔴","bucket":"left"},{"id":"cl4","label":"Forest Green","emoji":"🟢","bucket":"right"}],"successMessage":"Color mood master! Warm & cool palettes sorted!"},"quiz":[{"id":"ac-6-q1","prompt":"Which Indian instrument makes sound when air is gently blown across holes?","emoji":"🌬️","options":["Bansuri","Tabla","Sitar"],"correctAnswer":"Bansuri","hint":"A wind instrument made of bamboo!","explanation":"Bansuri is a wind instrument; Tabla is tapped and Sitar is plucked."},{"id":"ac-6-q2","prompt":"Which set contains ONLY Cool Colors?","emoji":"🌊","options":["Blue, Green, Violet","Red, Orange, Yellow","Orange, Pink, Red"],"correctAnswer":"Blue, Green, Violet","hint":"Think of rivers, trees, and twilight sky!","explanation":"Blues, greens, and purples give a calm, cool visual feel."},{"id":"ac-6-q3","prompt":"How does a Sitar or Veena create sweet notes?","emoji":"🎵","options":["Plucking stretched metal strings cleanly","Tapping leather drumheads","Shaking a tin can"],"correctAnswer":"Plucking stretched metal strings cleanly","hint":"A stringed instrument!","explanation":"Plucked strings vibrate to produce rich classical notes."}],"realLifeChallenge":{"title":"Dot-to-Dot Rice-Flour Rangoli","instruction":"Draw a 3×3 grid of dots on scrap paper and connect them around into a symmetric flower, star, or diya border!","familyTip":"Show your child how South Indian *Kolam* and North Indian *Rangoli* turn simple dot grids into endless beauty."},"badge":{"id":"badge-ac-6","title":"Palette & Tabla Star","emoji":"🥁"}},"7":{"zoneId":"art_creativity","classAge":7,"className":"2nd Class","pedagogyTier":"foundational","moduleTitle":"Warli Stick Art, Rhyming Couplets & Clay Sculpting","hindiSubtitle":"वारली लोककला, तुकबंदी कविता और मिट्टी की कलाकृति","ncertGoalNote":"Exploring tribal Warli art geometry, creative couplets & 3D tactile clay modeling","lessons":[{"id":"ac-7-1","title":"Warli Art: Triangles Show Daily Village Life!","hindiTitle":"वारली कला: त्रिकोण और गोले से जीवन चित्रण","emojiVisual":"🔺▽  Joined Tips = Dancing Villager  •  ⭕ Circle = Sun/Moon","explanation":"Maharashtra’s Warli artists paint white rice-paste scenes on earthy mud walls using ONLY circles (sun/moon), triangles (two tip-to-tip triangles form a person!), and squares (sacred huts)!","indianExample":"Warli paintings often show joyful *Tarpa* harvest dances, trees, birds, and plowing farms together in harmony!","funFact":"Two triangles meeting point-to-point create an expressive dancing silhouette in seconds!","askNyraPrompt":"NYRA, explain how to draw a Warli dancer step-by-step!"},{"id":"ac-7-2","title":"Fun Story Settings & Rhyming Couplets","hindiTitle":"कल्पनाशील कहानी और तुकबंदी की पंक्तियाँ","emojiVisual":"🌧️ \"Little raindrops on the glass, / Paint green diamonds on the grass!\"","explanation":"Creative writers add vivid 5-sense details (\"crunchy samosa\", \"silver moonlight\") AND playful end-rhymes like *tree/bee* or *star/far* to turn plain lines into memorable poems!","indianExample":"Notice how Hindi *doha* & English rhyming lines bounce like music when read aloud!","funFact":"Inventing a \"What if...\" twist (What if a mango tree talked for 1 day?) kicks off amazing original stories!","askNyraPrompt":"NYRA, help me finish a fun 2-line rhyming poem about a monsoon frog!"}],"activity":{"kind":"experiment","title":"How Do Warli Artists Draw People?","instruction":"Look closely at classic Warli folk figures! Which two geometric shapes meet tip-to-tip to form the human chest and waist?","prompt":"Tap the classic Warli body secret:","options":[{"label":"Two Triangles meeting at their tips!","emoji":"⏳","correct":true,"feedback":"Spot on! Two tip-touching triangles + circle head + bent stick arms make iconic Warli dancers!"},{"label":"Five giant hexagons","emoji":"🛑","correct":false,"feedback":"Warli keeps geometry super crisp with circles, triangles, and lines!"},{"label":"Wavy spirals only","emoji":"🌀","correct":false,"feedback":"Spirals show dancing circles (*Tarpa*), while bodies use triangles!"}],"successMessage":"Warli folk artist eye unlocked!"},"quiz":[{"id":"ac-7-q1","prompt":"Traditionally, what white natural material did Warli artists use as paint on mud walls?","emoji":"🍚","options":["Rice paste mixed with water & natural gum","Plastic spray cans","Motor oil"],"correctAnswer":"Rice paste mixed with water & natural gum","hint":"A white grain grown locally!","explanation":"Crushed rice paste gave Warli murals their crisp white lines on red-ochre earth."},{"id":"ac-7-q2","prompt":"Which rhyming pair completes: \"Up above the banyan tree, / Hums a busy yellow ___!\"","emoji":"🐝","options":["bee","bus","rock"],"correctAnswer":"bee","hint":"Sounds just like \"tree\"!","explanation":"Tree / Bee creates a bouncy rhyming couplet."},{"id":"ac-7-q3","prompt":"Why is modeling figures from soft clay or wheat dough awesome for young creators?","emoji":"🏺","options":["It builds 3D spatial planning AND strengthens finger control","Clay paints walls permanently","It melts pencils"],"correctAnswer":"It builds 3D spatial planning AND strengthens finger control","hint":"Think of 3D front, back, and sides!","explanation":"Clay sculpting trains 3D vision and fine finger coordination."}],"realLifeChallenge":{"title":"Draw a Mini Warli Scene + 2-Line Poem","instruction":"Draw 2 tip-to-tip triangle Warli dancers holding hands under a sun circle, and write a cheerful 2-line caption underneath!","familyTip":"Ask what festival or harvest day the characters are celebrating."},"badge":{"id":"badge-ac-7","title":"Warli Storyteller","emoji":"⏳"}},"8":{"zoneId":"art_creativity","classAge":8,"className":"3rd Class","pedagogyTier":"conceptual","moduleTitle":"Madhubani Folk Patterns & Dialogues in Stories","hindiSubtitle":"मधुबनी चित्रकला और जीवंत संवाद लेखन","ncertGoalNote":"Exploring Mithila/Madhubani nature motifs, foreground/background & character dialogue","lessons":[{"id":"ac-8-1","title":"Madhubani (Mithila) Art: Nature & Double Borders","hindiTitle":"मधुबनी कला की बारीकी और दोहरी रेखाएँ","emojiVisual":"🐟 Twin Fish • 🦚 Peacock • 🌺 Lotus Filled With Crisp Line Patterns!","explanation":"Originating from Bihar’s Mithila region (pioneered by women artists like Sita Devi & Baua Devi!), Madhubani paintings fill almost EVERY inch with double outlines, leaves, flowers, fish, and peacocks—using natural dyes like turmeric, indigo, and neem charcoal!","indianExample":"Instead of leaving blank corners, Madhubani fills spaces with tiny petals, wave lines, or diamonds (*kachni/bharni*)!","funFact":"Historically, artists painted with bamboo twigs wrapped in soft cotton dipped in plant dyes!","askNyraPrompt":"NYRA, tell me 3 key design rules of Madhubani art so I can try drawing a fish motif!"},{"id":"ac-8-2","title":"Making Stories Pop With Dialogue & Show-Don’t-Tell","hindiTitle":"संवाद और भावों से कहानी सजाना","emojiVisual":"😐 \"Rohan was scared.\"  vs  🌟 \"Rohan’s knees wobbled as thunder boomed!\"","explanation":"Showing actions (\"hands trembled\", \"eyes sparkled\") + crisp character dialogues lets readers picture your story like a cinema movie inside their minds!","indianExample":"Adding lively dialogue between a clever squirrel and a grumpy crow instantly pulls listeners in!","funFact":"Foreground = big close-up objects at bottom; Background = smaller distant hills at top!","askNyraPrompt":"NYRA, rewrite \"The cat was happy\" using Show-Don’t-Tell for Class 3!"}],"activity":{"kind":"classify","title":"Sort: \"Show-Don’t-Tell\" vs Plain Telling!","instruction":"Spot vivid sensory sentences vs flat plain labels.","leftBucketLabel":"✨ Vivid \"Show\" Detail","rightBucketLabel":"📄 Plain Telling","classifyItems":[{"id":"st1","label":"\"Sweat trickled down under the sizzling May sun.\"","emoji":"☀️","bucket":"left"},{"id":"st2","label":"\"It was hot outside.\"","emoji":"🌡️","bucket":"right"},{"id":"st3","label":"\"She bounced on her toes grinning ear to ear!\"","emoji":"😄","bucket":"left"},{"id":"st4","label":"\"She was excited.\"","emoji":"😐","bucket":"right"}],"successMessage":"Vivid writer unlocked! Readers can SEE your scenes!"},"quiz":[{"id":"ac-8-q1","prompt":"Which feature is a signature hallmark of Bihar’s Madhubani (Mithila) paintings?","emoji":"🦚","options":["Double line borders & detailed nature motifs filling the whole frame","Blank empty white corners only","Black-and-white barcodes"],"correctAnswer":"Double line borders & detailed nature motifs filling the whole frame","hint":"Double outlines + intricate hatching patterns!","explanation":"Madhubani fills spaces richly with fish, sun, peacocks, and floral borders."},{"id":"ac-8-q2","prompt":"In landscape drawing, how do artists show a mountain is FAR AWAY in the background?","emoji":"🏔️","options":["Draw it smaller & softer higher up near the horizon","Draw it 10× bigger covering everything","Put it in neon circles"],"correctAnswer":"Draw it smaller & softer higher up near the horizon","hint":"Think of perspective distance!","explanation":"Foreground objects appear large and bold; distant background hills look smaller."},{"id":"ac-8-q3","prompt":"Which line best SHOWS a puppy is excited instead of just telling?","emoji":"🐶","options":["\"Bruno’s tail thumped like a drum as he leaped at the door!\"","\"Bruno felt glad.\"","\"The dog sat.\""],"correctAnswer":"\"Bruno’s tail thumped like a drum as he leaped at the door!\"","hint":"Look for action + sound image!","explanation":"Showing wagging tails and joyful leaps makes stories spring off the page."}],"realLifeChallenge":{"title":"Madhubani Border Bookmark","instruction":"Cut a strip of thick card/old wedding card, draw a double-line Madhubani zigzag border with a big flower or fish inside, and color with bright patterns!","familyTip":"Encourage steady double-line patience rather than rushing."},"badge":{"id":"badge-ac-8","title":"Mithila Creator","emoji":"🦚"}},"9":{"zoneId":"art_creativity","classAge":9,"className":"4th Class","pedagogyTier":"conceptual","moduleTitle":"Rhythm Taal Cycles, Storyboards & Comic Panels","hindiSubtitle":"ताल चक्र (तीनताल/कहरवा) और कॉमिक स्टोरीबोर्ड","ncertGoalNote":"Exploring rhythmic time cycles (Taal), visual comic pacing & perspective","lessons":[{"id":"ac-9-1","title":"Counting Beats in Indian Taal (Clap–Wave Rhythm)","hindiTitle":"भारतीय संगीत में ताल और सम (Sam) का आनंद","emojiVisual":"🥁 1-2-3-4 | 5-6-7-8 (Kaharwa 8-Beat Cycle returning to BEAT 1!)","explanation":"While melodies sing up and down (*Raga*), rhythm walks in steady circles called **Taal**! An 8-beat *Kaharwa* cycle counts 1-2-3-4-5-6-7-8 and lands joyfully back on Beat 1 (called *Sam*) with a crisp clap!","indianExample":"Popular folk & film songs often groove happily on 8-beat Kaharwa or 6-beat Dadra cycles!","funFact":"Drummers remember beats using spoken syllables like \"Dha Ge Na Ti Na Ka Dhin Na\" (*Bols*)!","askNyraPrompt":"NYRA, teach me how to clap an 8-beat Kaharwa rhythm with Beat 1 emphasis!"},{"id":"ac-9-2","title":"Comic Panels & Storyboarding (Art + Writing)","hindiTitle":"चित्रकथा (Comic Storyboard) बनाना","emojiVisual":"📦 Panel 1 (Wide Scene) ➡️ 💬 Panel 2 (Action) ➡️ 💥 Panel 3 (Punchline)","explanation":"Film directors and graphic novelists sketch quick **Storyboards**—3 to 6 comic boxes showing different camera angles (Wide shot, Close-up face, Speech bubble!) before making final art!","indianExample":"Classic Indian comics like *Amar Chitra Katha* and *Tinkle* blend crisp speech bubbles, sound words (*ZOOM!*, *DHUM!*), and facial expressions!","funFact":"Cloud-shaped bubbles mean silent THOUGHTS, while pointed bubbles mean SPOKEN words!","askNyraPrompt":"NYRA, help me plan a funny 4-panel comic about a talking schoolbag!"}],"activity":{"kind":"classify","title":"Comic Bubble & Shot Match!","instruction":"Sort comic-book visual tools by their storyteller purpose.","leftBucketLabel":"💬 Dialogue & Action Tools","rightBucketLabel":"🎞️ Silent Thought & Wide Framing","classifyItems":[{"id":"cm1","label":"Pointed Speech Tail","emoji":"🗨️","bucket":"left"},{"id":"cm2","label":"Puffy Cloud Bubble","emoji":"💭","bucket":"right"},{"id":"cm3","label":"Jagged \"CRASH!\" Starburst","emoji":"💥","bucket":"left"},{"id":"cm4","label":"Wide Playground Establishing Shot","emoji":"🏞️","bucket":"right"}],"successMessage":"Comic storyboard director!"},"quiz":[{"id":"ac-9-q1","prompt":"In graphic comics, what does a puffy cloud-shaped bubble connected by tiny circles mean?","emoji":"💭","options":["The character is THINKING silently inside their head","Someone is screaming through a megaphone","It is raining"],"correctAnswer":"The character is THINKING silently inside their head","hint":"Contrast thought clouds vs sharp speech tails!","explanation":"Cloud bubbles show inner thoughts while pointed tails show spoken words."},{"id":"ac-9-q2","prompt":"In Indian classical & folk rhythm (Taal), what is \"Sam\" (Beat 1)?","emoji":"👏","options":["The accented home beat where musicians and dancers land together","A broken string","The last page"],"correctAnswer":"The accented home beat where musicians and dancers land together","hint":"Where every rhythmic circle comes home!","explanation":"Sam is Beat 1—the exciting anchor of every Indian Taal cycle."},{"id":"ac-9-q3","prompt":"Why draw a rough 4-box pencil storyboard BEFORE painting a big poster or skit?","emoji":"✏️","options":["To plan order, framing, and fix gaps easily before spending lots of time","Pencils never erase","To waste extra glue"],"correctAnswer":"To plan order, framing, and fix gaps easily before spending lots of time","hint":"Plan first, polish second!","explanation":"Storyboarding saves effort and makes pacing much sharper."}],"realLifeChallenge":{"title":"Create a 4-Panel Mini Comic Strip","instruction":"Divide one blank page into 4 boxes and draw a funny 4-step adventure of your pet, backpack, or favorite fruit using both speech & thought bubbles!","familyTip":"Let your child read the character voices aloud after finishing!"},"badge":{"id":"badge-ac-9","title":"Taal & Comic Director","emoji":"🎞️"}},"10":{"zoneId":"art_creativity","classAge":10,"className":"5th Class","pedagogyTier":"conceptual","moduleTitle":"Poster Design, Contrast & Creative Innovation Showcase","hindiSubtitle":"पोस्टर डिज़ाइन, दृश्य संतुलन और रचनात्मक अभिव्यक्ति","ncertGoalNote":"Visual hierarchy, typography contrast, multi-arts synthesis & persuasive storytelling","lessons":[{"id":"ac-10-1","title":"Three Rules of Eye-Catching Poster Design","hindiTitle":"प्रभावशाली पोस्टर डिज़ाइन के 3 नियम","emojiVisual":"1️⃣ Bold Headline  2️⃣ High Color Contrast  3️⃣ Clean White Space!","explanation":"Great social-awareness posters (Save Water, Read Daily, Zero Waste) never cram 200 tiny words everywhere! Use ONE bold 5-word headline, ONE crisp central illustration, and plenty of calm breathing space around edges so passersby read it in 3 seconds!","indianExample":"Notice how dark blue letters on bright yellow poster board pop clearly across an entire hallway—unlike yellow text on white paper!","funFact":"Professional designers call visual priority \"Hierarchy\"—Biggest title grabs eyes first!","askNyraPrompt":"NYRA, review my idea for a \"Save Sparrow Birds\" school poster using contrast & hierarchy!"},{"id":"ac-10-2","title":"Blending Music, Drama & Visual Art (Ek Bharat Expression)","hindiTitle":"संगीत, नाटक और कला का संगम","emojiVisual":"🎭 Skit Script + 🎨 Painted Backdrop + 🥁 Sound Effects = Live Theatre!","explanation":"NEP 2020 celebrates **Art-Integrated Learning**—using skits, puppet theatre, folk song parodies, or comic zines to explain Science, Math, and History memorably! Creatively performing a water-cycle play helps an entire school remember science better than rote notes.","indianExample":"Even coconut-shell taps can create horse-hoof sound effects (*Foley art*) behind a stage curtain!","funFact":"Combining two art forms multiplies audience emotion and memory!","askNyraPrompt":"NYRA, help me design creative homemade sound effects for a jungle story skit!"}],"activity":{"kind":"experiment","title":"Fix the Unreadable School Poster!","instruction":"A friend wrote a \"Book Fair Friday\" poster in tiny light-pink pencil over dark-red paper, plus 10 cramped paragraphs. Nobody stops to read it! What fixes it FASTEST?","prompt":"Choose the winning design upgrade:","options":[{"label":"Short bold cream/white headline + high contrast + single clear book drawing!","emoji":"🎨","correct":true,"feedback":"Brilliant! High light-on-dark contrast + short bold hierarchy catches eyes immediately!"},{"label":"Add 50 more tiny pink sentences","emoji":"📄","correct":false,"feedback":"More cramped low-contrast text hides the message even more!"},{"label":"Remove the day and time completely","emoji":"⏰","correct":false,"feedback":"Readers still need key When/Where info clearly visible!"}],"successMessage":"Visual design master!"},"quiz":[{"id":"ac-10-q1","prompt":"Which color combo gives the HIGHEST readability from across a school corridor?","emoji":"👀","options":["Bold Navy Blue text on Cream/Yellow paper","Pale Yellow text on White paper","Dark Brown text on Black paper"],"correctAnswer":"Bold Navy Blue text on Cream/Yellow paper","hint":"Strong light-vs-dark contrast wins!","explanation":"High contrast between background and letters makes posters effortless to read."},{"id":"ac-10-q2","prompt":"What is \"Visual Hierarchy\" in creative posters and slides?","emoji":"📐","options":["Sizing the main title biggest, key date medium, and notes clean so eyes know where to look first","Making every single word identical size","Writing upside down"],"correctAnswer":"Sizing the main title biggest, key date medium, and notes clean so eyes know where to look first","hint":"1st read → 2nd read → 3rd read!","explanation":"Hierarchy guides viewers smoothly through the message in seconds."},{"id":"ac-10-q3","prompt":"How could a 5th Grader creatively craft thunderstorm sound effects for a class play with ZERO speakers?","emoji":"⛈️","options":["Gently wobble a flexible steel thali/cardboard sheet & snap fingers for raindrops","Break the classroom window","Stay completely silent"],"correctAnswer":"Gently wobble a flexible steel thali/cardboard sheet & snap fingers for raindrops","hint":"Everyday Foley sound effects!","explanation":"Creative percussion turns household trays and finger-snaps into cinema soundscapes!"}],"realLifeChallenge":{"title":"Design a Clean Campaign Poster","instruction":"Sketch an A4 poster for any school cause (\"Keep Tap Shut\", \"Plant Native Trees\", or \"Kindness Week\") using a 4-word bold headline, high contrast, and clear margins!","familyTip":"Hold the poster 3 meters away to test if every word is still readable!"},"badge":{"id":"badge-ac-10","title":"Design & Stage Maestro","emoji":"✨"}}},"stem_innovation":{"3":{"zoneId":"stem_innovation","classAge":3,"className":"Nursery","pedagogyTier":"play","moduleTitle":"My 5 Amazing Senses & Sunny Shadows","hindiSubtitle":"हमारी पाँच इंद्रियाँ और धूप-परछाई का खेल","ncertGoalNote":"Sensory exploration (eyes, ears, nose, tongue, skin) & playful shadow wonder","lessons":[{"id":"st-3-1","title":"Our 5 Super Senses Explore the World","hindiTitle":"आँख, कान, नाक, जीभ और त्वचा के 5 जादू","emojiVisual":"👀 See  👂 Hear  👃 Smell  👅 Taste  ✋ Touch & Feel!","explanation":"Our bodies carry 5 built-in explorers! Eyes spot bright rainbows, ears catch cuckoo songs, nose smells hot parathas, tongue tastes sweet mangoes, and fingers feel soft cotton vs rough bark!","indianExample":"Close your eyes gently and guess crushed mint (*pudina*) or orange peel just by smelling!","funFact":"Our fingertips have thousands of tiny feelers to sense warm, cool, soft, or prickly!","askNyraPrompt":"NYRA, ask me a 5-Senses guessing riddle for Nursery!"},{"id":"st-3-2","title":"Why Does My Shadow Follow Me in Sunlight?","hindiTitle":"धूप में मेरी परछाई क्यों बनती है?","emojiVisual":"☀️ Bright Sun + 🧒 Your Body Blocks Light  ➡️  🌑 Shadow on Ground!","explanation":"Light travels straight like tiny zooming arrows! Because your body is solid, sunlight cannot pass right through you—leaving a dark shadow silhouette dancing behind you!","indianExample":"Stand outside in morning sun and watch your shadow stretch tall like a giant!","funFact":"In a pitch-dark room with zero light, shadows disappear completely!","askNyraPrompt":"NYRA, tell me how to make funny hand-puppet shadows with a torch!"}],"activity":{"kind":"classify","title":"Touch Detective: Soft vs Hard!","instruction":"Feel with your imagination! Sort soft cuddly things vs hard solid things.","leftBucketLabel":"☁️ Soft & Squishy","rightBucketLabel":"🪨 Hard & Solid","classifyItems":[{"id":"sf1","label":"Cotton Ball","emoji":"☁️","bucket":"left"},{"id":"sf2","label":"Steel Spoon","emoji":"🥄","bucket":"right"},{"id":"sf3","label":"Fluffy Pillow","emoji":"🛏️","bucket":"left"},{"id":"sf4","label":"Garden Stone","emoji":"🪨","bucket":"right"}],"successMessage":"Super sense scientist!"},"quiz":[{"id":"st-3-q1","prompt":"Which sense organ lets you smell fresh roses and warm soup?","emoji":"🌹","options":["Nose 👃","Knee 🦵","Elbow 💪"],"correctAnswer":"Nose 👃","hint":"Take a gentle sniff!","explanation":"Our nose detects lovely aromas and warns against burnt smoke."},{"id":"st-3-q2","prompt":"What TWO things are always needed to cast a shadow?","emoji":"🔦","options":["A light source + an object blocking the light","Rain + mud only","Ice cream + spoon"],"correctAnswer":"A light source + an object blocking the light","hint":"Think of torch + hand!","explanation":"Shadows form whenever a solid object blocks light rays."},{"id":"st-3-q3","prompt":"Which sense helps you tell sweet ripe mango from sour lemon?","emoji":"🍋","options":["Taste (Tongue 👅)","Ears 👂","Hair"],"correctAnswer":"Taste (Tongue 👅)","hint":"Sweet vs sour happens on your...","explanation":"Taste buds on our tongue recognize sweet, sour, salty, and bitter."}],"realLifeChallenge":{"title":"Torch Hand-Bunny Shadow","instruction":"With a parent holding a phone torch against a wall in a dim room, hold up two fingers like bunny ears to make a giant shadow jump!","familyTip":"Move your hand closer and farther from the light to watch the shadow grow and shrink!"},"badge":{"id":"badge-st-3","title":"Five Senses Scout","emoji":"👀"}},"4":{"zoneId":"stem_innovation","classAge":4,"className":"LKG","pedagogyTier":"play","moduleTitle":"Sink or Float? Water Lab Fun!","hindiSubtitle":"डूबेगा या तैरेगा? पानी के प्रयोग","ncertGoalNote":"Hands-on inquiry prediction: why objects sink vs float in a bucket","lessons":[{"id":"st-4-1","title":"Predict First, Test in Water!","hindiTitle":"पहले अंदाज़ा लगाओ, फिर पानी में देखो","emojiVisual":"🍃 Leaf & Wooden Stick = FLOAT ⬆️   |   🪙 Coin & Pebble = SINK ⬇️","explanation":"Good little scientists GUESS (predict) BEFORE testing! Light wooden blocks, plastic balls, and dry leaves float happily on top of bucket water, while dense metal keys and marbles sink straight to the bottom!","indianExample":"Even a giant steel ship floats because its hollow curved hull holds lots of light air inside—like a steel kitchen katori floating upright!","funFact":"Try placing an empty steel katori gently flat on water vs pushing it sideways!","askNyraPrompt":"NYRA, ask me 3 Sink-or-Float prediction puzzles for LKG!"},{"id":"st-4-2","title":"Dissolving Magic: Sugar vs Sand","hindiTitle":"पानी में घुलने का जादू (चीनी बनाम रेत)","emojiVisual":"🧂 Salt/Sugar + 💧 Stir = Vanishes!  |  🪨 Sand + 💧 = Stays Visible!","explanation":"When Mama stirs sugar or salt in clean water, it disappears inside the water—we say it DISSOLVES! If you stir sand or tiny pebbles, they sink and never disappear.","indianExample":"Making sweet *shikanji* (lemonade) mixes sugar & salt invisibly right into cold water!","funFact":"Even though dissolved sugar looks invisible, your tongue can still taste it sweet!","askNyraPrompt":"NYRA, name 2 kitchen items that dissolve in water and 2 that don’t!"}],"activity":{"kind":"classify","title":"Predict: Does It Float or Sink?","instruction":"Sort objects into Top-Floater vs Bottom-Sinker before checking a tub!","leftBucketLabel":"🫧 Floats on Top","rightBucketLabel":"⚓ Sinks to Bottom","classifyItems":[{"id":"fl1","label":"Dry Tree Leaf","emoji":"🍃","bucket":"left"},{"id":"fl2","label":"Metal Key","emoji":"🔑","bucket":"right"},{"id":"fl3","label":"Paper Boat","emoji":"⛵","bucket":"left"},{"id":"fl4","label":"Glass Marble","emoji":"🟣","bucket":"right"}],"successMessage":"Splash-tastic! Accurate floating & sinking predictions!"},"quiz":[{"id":"st-4-q1","prompt":"You gently place a dry wooden ice-cream stick in a water mug. What will it do?","emoji":"🪵","options":["Float on top","Melt into steam","Fly up to the fan"],"correctAnswer":"Float on top","hint":"Wood floats lightly on water!","explanation":"Wood is less dense than water, so boats and sticks float easily."},{"id":"st-4-q2","prompt":"Which ingredient COMPLETELY dissolves when stirred in warm water?","emoji":"🥛","options":["Sugar 🍚","Pebbles 🪨","Plastic button 🔘"],"correctAnswer":"Sugar 🍚","hint":"Think of sweet lemonade!","explanation":"Sugar crystals break tiny and dissolve evenly in water."},{"id":"st-4-q3","prompt":"What happens if you poke holes in a floating steel kitchen katori?","emoji":"🥣","options":["Water rushes in and pushes air out, so it sinks!","It flies higher","It turns into ice"],"correctAnswer":"Water rushes in and pushes air out, so it sinks!","hint":"Trapped air kept the hollow boat afloat!","explanation":"Boats float by trapping light air inside watertight curved hulls."}],"realLifeChallenge":{"title":"Bath-Bucket Float Lab (With Parent!)","instruction":"Test 4 safe household items in a small bowl of water (bottle cap, spoon, twig, orange peel)—GUESS each one aloud BEFORE dropping it in!","familyTip":"Ask \"Why do you think the steel spoon sank while the plastic lid floated?\""},"badge":{"id":"badge-st-4","title":"Water Lab Explorer","emoji":"🫧"}},"5":{"zoneId":"stem_innovation","classAge":5,"className":"UKG","pedagogyTier":"play","moduleTitle":"Solid Ice → Liquid Water → Steam & Magnet Magic","hindiSubtitle":"बर्फ, पानी, भाप और चुंबक का जादू","ncertGoalNote":"Observing 3 states of water & playful magnetic attraction discovery","lessons":[{"id":"st-5-1","title":"One Water, Three Cool Costumes!","hindiTitle":"पानी के तीन रूप: बर्फ, तरल और भाप","emojiVisual":"🧊 Solid Ice + Warmth  ➡️  💧 Liquid Water + Heat  ➡️  ♨️ Water Vapor!","explanation":"Water loves wearing three forms! Freeze water cold and it becomes hard SOLID ice cubes; warm ice and it melts into flowing LIQUID water; heat water (adults at stove!) and invisible steam (GAS) rises up!","indianExample":"Cooling mango juice with milk in the freezer turns liquid into yummy solid mango kulfi!","funFact":"Dew drops on cold morning grass come from invisible air vapor cooling overnight!","askNyraPrompt":"NYRA, explain Ice, Water, and Steam for UKG using a kulfi example!"},{"id":"st-5-2","title":"Friendly Magnet Pulls Iron (Never Electronics!)","hindiTitle":"चुंबक का आकर्षण: लोहा खींचना","emojiVisual":"🧲 Pulls Iron Nail & Paperclip   |   Ignores Wood, Eraser, Plastic!","explanation":"A magnet has invisible superpower pull for **iron and steel**! Touch it near a paperclip and it snaps right on—yet push it near a rubber eraser, wooden pencil, or gold bangle and nothing sticks! (Keep strong magnets away from TVs and phones!)","indianExample":"Fridge doors stay closed gently because a hidden flexible magnet strip lines the inside rubber seal!","funFact":"Every magnet has TWO poles—North and South!","askNyraPrompt":"NYRA, play a Magnet Yes-or-No quiz with me!"}],"activity":{"kind":"classify","title":"Magnet Check: Sticks or Ignores?","instruction":"Which everyday things stick to a fridge magnet vs stay unmoved?","leftBucketLabel":"🧲 Sticks to Magnet","rightBucketLabel":"🪵 Not Magnetic","classifyItems":[{"id":"mg1","label":"Iron Nail / Clip","emoji":"📎","bucket":"left"},{"id":"mg2","label":"Rubber Eraser","emoji":"🧽","bucket":"right"},{"id":"mg3","label":"Steel Fridge Door","emoji":"🚪","bucket":"left"},{"id":"mg4","label":"Wooden Pencil","emoji":"✏️","bucket":"right"}],"successMessage":"Magnet detective certified!"},"quiz":[{"id":"st-5-q1","prompt":"You forget a bowl of ice cubes on a sunny verandah for 30 minutes. What happens?","emoji":"🧊","options":["It melts from solid ice into liquid water","It turns into rocks","It glows purple"],"correctAnswer":"It melts from solid ice into liquid water","hint":"Warmth melts solid ice!","explanation":"Heat changes solid ice cleanly back into liquid water."},{"id":"st-5-q2","prompt":"Which object will JUMP onto a toy magnet?","emoji":"🧲","options":["Metal paperclip 📎","Glass marble 🔮","Leaf 🍃"],"correctAnswer":"Metal paperclip 📎","hint":"Look for iron/steel!","explanation":"Magnets attract iron and steel items, never glass or leaves."},{"id":"st-5-q3","prompt":"Why should tiny magnets NEVER be placed near mouth or near phones/cards?","emoji":"⚠️","options":["Swallowing magnets is dangerous AND magnets scramble card strips","Magnets melt ears","Phones become frogs"],"correctAnswer":"Swallowing magnets is dangerous AND magnets scramble card strips","hint":"Think of safety for tummies and electronics!","explanation":"Safe science means keeping magnets only with adult supervision away from mouths & screens."}],"realLifeChallenge":{"title":"Melt Race Observation","instruction":"Put one ice cube in a shade bowl and one in gentle sunshine—time which melts faster!","familyTip":"Ask \"Where did the warmth come from to melt the sunny cube first?\""},"badge":{"id":"badge-st-5","title":"Magnet & Ice Wizard","emoji":"🧲"}},"6":{"zoneId":"stem_innovation","classAge":6,"className":"1st Class","pedagogyTier":"foundational","moduleTitle":"Air Has Weight & Push + Balanced Thali Science","hindiSubtitle":"हवा का दबाव और संतुलित थाली का विज्ञान","ncertGoalNote":"Invisible air properties (occupies space/pushes) & food groups for growing bodies","lessons":[{"id":"st-6-1","title":"Air Is Invisible, Yet Takes Up Real Space!","hindiTitle":"अदृश्य हवा भी जगह घेरती है और धक्का देती है","emojiVisual":"🎈 Empty Balloon (Flat) + Blow Air Inside ➡️ Expands Tight!","explanation":"Even though you cannot see air, it fills every inch around us! Inflating a balloon, spinning a paper pinwheel (*phirki*), or seeing bicycle tyres stay firm proves trapped air pushes outward strongly!","indianExample":"Notice how wind lifts colorful kites high above terraces during Makar Sankranti!","funFact":"Moving air is called WIND—and warm air rises upward like sky lanterns!","askNyraPrompt":"NYRA, show me a 1-minute cup-and-tissue air trick I can try over a sink!"},{"id":"st-6-2","title":"Three Food Superpowers in Your Thali","hindiTitle":"हमारी थाली के 3 शक्ति समूह","emojiVisual":"🌾 Energy (Roti/Rice) + 🫘 Body-Builders (Dal/Milk) + 🥬 Protectors (Fruits/Sabzi)","explanation":"Our bodies need three food teams every day: **Energy foods** (roti, idli, rice, millet) to run; **Body-Building foods** (dal, rajma, paneer, curd, nuts/eggs) to grow tall muscles; and **Protective foods** (spinach, papaya, amla, carrots) to fight colds!","indianExample":"A classic home thali—dal, sabzi, roti, curd, salad—balances ALL three groups in one plate!","funFact":"Drinking clean water carries nutrients into every tiny cell of your body!","askNyraPrompt":"NYRA, check my lunch: Rice + Rajma + Cucumber salad—which food groups did I eat?"}],"activity":{"kind":"classify","title":"Sort the Balanced Thali Superpowers!","instruction":"Sort foods into Energy/Body-Builders vs Protective Vitamins.","leftBucketLabel":"💪 Grains & Protein Builders","rightBucketLabel":"🛡️ Vitamin Protectors","classifyItems":[{"id":"th1","label":"Whole Wheat Roti","emoji":"🫓","bucket":"left"},{"id":"th2","label":"Amla & Orange","emoji":"🍊","bucket":"right"},{"id":"th3","label":"Moong Dal Bowl","emoji":"🍲","bucket":"left"},{"id":"th4","label":"Fresh Palak & Carrot","emoji":"🥕","bucket":"right"}],"successMessage":"Nutrition scientist! A balanced colorful thali powers everything!"},"quiz":[{"id":"st-6-q1","prompt":"What pushes a bicycle tyre tight and spins a paper pinwheel (phirki)?","emoji":"🎡","options":["Air occupying space and pushing in motion","Invisible glue","Moonlight"],"correctAnswer":"Air occupying space and pushing in motion","hint":"Air has mass and force even when invisible!","explanation":"Compressed and moving air applies real physical push."},{"id":"st-6-q2","prompt":"Which food group mainly helps build strong growing muscles and bones (Body-Builders)?","emoji":"🍲","options":["Dals, beans, milk, curd & nuts","Fizzy colas","Cotton candy"],"correctAnswer":"Dals, beans, milk, curd & nuts","hint":"Rich in protein and calcium!","explanation":"Pulses, dairy, nuts, and wholesome proteins repair and build growing tissues."},{"id":"st-6-q3","prompt":"If you trap air inside an upside-down empty cup and press straight down into water, why stays dry inside?","emoji":"🥛","options":["Air already fills the cup and blocks water from entering!","The cup is scared of water","Paper hates blue cups"],"correctAnswer":"Air already fills the cup and blocks water from entering!","hint":"Two things cannot occupy the exact same space at once!","explanation":"Trapped air takes up space so water cannot enter until air bubbles escape."}],"realLifeChallenge":{"title":"Build a Folded Paper Pinwheel (Phirki)","instruction":"Craft a paper fan or pinwheel, blow gently vs blow hard on it, and observe how faster wind spins it faster!","familyTip":"Ask what happens to a stuffed tissue inside an inverted glass dipped in a bowl of water!"},"badge":{"id":"badge-st-6","title":"Air & Nutrition Pro","emoji":"🎡"}},"7":{"zoneId":"stem_innovation","classAge":7,"className":"2nd Class","pedagogyTier":"foundational","moduleTitle":"Water Cycle Adventure & Sound Vibrations","hindiSubtitle":"जल चक्र का सफर और ध्वनि के कंपन","ncertGoalNote":"Evaporation-condensation-precipitation cycle & how vibrations create sound","lessons":[{"id":"st-7-1","title":"How Puddles Climb Into Clouds (Water Cycle)","hindiTitle":"तालाब से बादल और बारिश का अद्भुत सफर","emojiVisual":"☀️ Warm Sun Evaporates 💧 ➡️ ☁️ Cools Into Clouds ➡️ 🌧️ Rain Falls Back!","explanation":"Earth recycles water endlessly! Sun warmth evaporates puddle and ocean water into invisible vapor rising skyward. High cool air turns vapor back into tiny droplets (condensation = clouds!), which grow heavy and fall as rain!","indianExample":"Notice tiny water drops forming OUTSIDE a cold steel glass of ice water—that is air vapor condensing just like clouds!","funFact":"Every sip of water you drink today has traveled through the water cycle for millions of years!","askNyraPrompt":"NYRA, explain Evaporation vs Condensation simply for Class 2!"},{"id":"st-7-2","title":"Sound = Fast Tiny Vibrations!","hindiTitle":"कंपन (Vibration) से बनती है आवाज़","emojiVisual":"🔔 Plucked Rubber Band Wiggles Fast  ➡️  Air Waves  ➡️  👂 Ears Hear!","explanation":"Touch your throat gently while humming \"Hmmmm\"—feel that tickle? Your vocal cords vibrate rapidly! Whether it is a guitar string, drum skin, or buzzing bee wing, vibrations push air ripples straight to our ears.","indianExample":"Stretching a rubber band across an empty tiffin box makes a mini musical harp!","funFact":"Tighter, shorter rubber bands vibrate faster and sound higher-pitched!","askNyraPrompt":"NYRA, tell me why a bee’s fast wings make a \"Bzzzz\" sound!"}],"activity":{"kind":"sequence","title":"Track a Raindrop Through the Water Cycle!","instruction":"Put the 4 Water Cycle steps in order starting from the Sunny Pond.","sequenceSteps":[{"id":"wc1","label":"Sun Warms Pond (Evaporation)","emoji":"☀️","order":1},{"id":"wc2","label":"Warm Vapor Rises High","emoji":"⬆️","order":2},{"id":"wc3","label":"Cool Air Forms Clouds (Condensation)","emoji":"☁️","order":3},{"id":"wc4","label":"Rain Falls Back to Earth!","emoji":"🌧️","order":4}],"successMessage":"Nature’s water cycle mastered!"},"quiz":[{"id":"st-7-q1","prompt":"Warm sunlight turning wet washed clothes dry on a clothesline is an example of:","emoji":"👕","options":["Evaporation","Freezing","Magnetism"],"correctAnswer":"Evaporation","hint":"Liquid water changing into rising water vapor!","explanation":"Heat causes water to evaporate into dry moving air."},{"id":"st-7-q2","prompt":"Why do tiny water droplets appear on the OUTSIDE of an ice-cold steel bottle?","emoji":"🧊","options":["Warm air vapor touches the cold steel and condenses into liquid drops","Steel leaks water through solid metal","Rain fell inside the fridge"],"correctAnswer":"Warm air vapor touches the cold steel and condenses into liquid drops","hint":"Just like cloud formation—gas cooling back to liquid!","explanation":"Condensation happens when invisible water vapor cools on a chilly surface."},{"id":"st-7-q3","prompt":"Pluck a stretched rubber band and then press it gently with your finger to stop its wiggle. What happens to the sound?","emoji":"🎸","options":["The sound stops immediately when vibration stops!","The sound gets twice as loud","It glows red"],"correctAnswer":"The sound stops immediately when vibration stops!","hint":"No vibration = no sound!","explanation":"All sounds depend on vibrating matter."}],"realLifeChallenge":{"title":"Feel Your Humming Throat & Tin-Can Telephone","instruction":"Put two fingers gently on your throat and hum low vs high! Feel how the vibrations speed up on higher notes!","familyTip":"Ask what happens to droplets on a chilled water tumbler left on the dining table."},"badge":{"id":"badge-st-7","title":"Cloud & Sound Explorer","emoji":"☁️"}},"8":{"zoneId":"stem_innovation","classAge":8,"className":"3rd Class","pedagogyTier":"conceptual","moduleTitle":"Simple Machines & Moon Phases","hindiSubtitle":"सरल मशीनें (लीवर, पहिया, घिरनी) और चंद्रमा की कलाएँ","ncertGoalNote":"Everyday simple machines reducing effort & lunar illumination phases","lessons":[{"id":"st-8-1","title":"Simple Machines Make Heavy Jobs Easy!","hindiTitle":"छोटी सरल मशीनों से बड़े काम आसान","emojiVisual":"⚖️ Lever (Seesaw/Spoon) • 🛞 Wheel & Axle • ⛰️ Ramp • 🪢 Pulley (Well!)","explanation":"Simple machines have zero motors yet multiply your strength! A ramp lets a wheelchair roll smoothly up steps; a **Pulley** lets you pull down on a rope to lift a heavy water bucket up a well; a **Lever** lets one spoon pry open a tight tin lid!","indianExample":"Village stone wells use a grooved pulley wheel (*ghirni*) so pulling downward feels much easier than hauling straight up!","funFact":"Even a pair of scissors combines TWO levers + TWO sharp wedges!","askNyraPrompt":"NYRA, help me find 4 hidden simple machines inside my kitchen or school!"},{"id":"st-8-2","title":"Why the Moon Changes Shape Every Night","hindiTitle":"चाँद का आकार हर रात क्यों बदलता दिखता है?","emojiVisual":"🌑 New Moon  ➡️  🌒 Crescent  ➡️  🌓 Half  ➡️  🌕 Full Moon (Purnima)!","explanation":"The Moon makes ZERO light of its own—it glows like a giant mirror reflecting bright Sunlight! As the Moon orbits Earth every ~29.5 days, we see different fractions of its sunlit half: from dark Amavasya to glowing Purnima!","indianExample":"Indian calendar festivals like *Purnima*, *Karwa Chauth*, and *Eid Crescent* follow Moon phases closely!","funFact":"Half the Moon is ALWAYS lit by the Sun—only our viewing angle from Earth changes!","askNyraPrompt":"NYRA, explain with an orange and torch why the Moon looks Crescent vs Full!"}],"activity":{"kind":"classify","title":"Identify the Simple Machine in Everyday Life!","instruction":"Sort real-life helpers into Ramp/Wheel vs Lever/Pulley.","leftBucketLabel":"🛞 Wheel & Ramp","rightBucketLabel":"⚖️ Lever & Pulley","classifyItems":[{"id":"sm1","label":"Hospital Wheelchair Ramp","emoji":"♿","bucket":"left"},{"id":"sm2","label":"Well Bucket Rope Wheel","emoji":"🪣","bucket":"right"},{"id":"sm3","label":"Rolling Toy Cart","emoji":"🛒","bucket":"left"},{"id":"sm4","label":"Park Seesaw","emoji":"⚖️","bucket":"right"}],"successMessage":"Mechanical engineer level unlocked!"},"quiz":[{"id":"st-8-q1","prompt":"A heavy metal paint-tin lid is stuck. Using a spoon handle near the rim works as which simple machine?","emoji":"🥄","options":["A Lever","A Magnet","A Battery"],"correctAnswer":"A Lever","hint":"Resting on the tin rim as a turning fulcrum!","explanation":"The spoon handle pivots on the rim (fulcrum) to multiply upward prying force!"},{"id":"st-8-q2","prompt":"Why does the Moon shine brightly in the night sky?","emoji":"🌕","options":["It reflects light coming from the Sun","It burns coal inside","Millions of bulbs live there"],"correctAnswer":"It reflects light coming from the Sun","hint":"Does the Moon make its own heat/light?","explanation":"Moonlight is reflected sunlight bouncing off lunar dust and rock."},{"id":"st-8-q3","prompt":"Why are sloping ramps built next to stairs for wheelchairs and luggage trolleys?","emoji":"📐","options":["An inclined plane spreads lifting force gently over a longer slope","Ramps teleport boxes","Wheels dislike flat floors"],"correctAnswer":"An inclined plane spreads lifting force gently over a longer slope","hint":"Easier slope = less push needed!","explanation":"Inclined planes reduce the force required to raise loads upward."}],"realLifeChallenge":{"title":"1-Week Moon Sketch Diary","instruction":"Peek outside right after dinner twice this week (3 days apart) and sketch how much of the Moon’s face looks lit!","familyTip":"Ask whether the sunlit side is growing bigger (waxing) or shrinking (waning)!"},"badge":{"id":"badge-st-8","title":"Simple Machine Ace","emoji":"⚙️"}},"9":{"zoneId":"stem_innovation","classAge":9,"className":"4th Class","pedagogyTier":"conceptual","moduleTitle":"Circuits, Conductors & Soil/Bridge Strength","hindiSubtitle":"विद्युत परिपथ, सुचालक-कुचालक और मजबूत संरचनाएँ","ncertGoalNote":"Closed circuits (battery-led conceptual only), conductors vs insulators & triangle truss strength","lessons":[{"id":"st-9-1","title":"Closed Loops & Conductors vs Insulators (Battery Safe!)","hindiTitle":"बंद परिपथ और बिजली के सुचालक-कुचालक","emojiVisual":"🔋➡️ Wire ➡️ 💡 ➡️ Back to 🔋 (Closed Loop = Lights Up!) • Rubber Stops Flow","explanation":"Electricity only flows around an unbroken **Closed Loop** from one battery terminal, through a bulb, and back! Metals (copper, steel) are **Conductors** letting electrons travel; plastic, dry wood, and rubber are **Insulators**—that is why wires wear plastic jackets so hands stay safe! (Never experiment with wall AC plugs!)","indianExample":"Notice electricians always wear thick rubber gloves and wooden ladders for safety!","funFact":"Even small gaps—like opening a light switch—break the loop so the bulb turns off immediately!","askNyraPrompt":"NYRA, explain why switches are actually smart \"loop breakers\"!"},{"id":"st-9-2","title":"Why Triangles Make Strong Bridges (Engineering!)","hindiTitle":"पुलों और टावरों में त्रिकोण की अद्भुत शक्ति","emojiVisual":"🟥 Square Squishes Sideways   vs   🔺 Triangle Locks Firmly in Place!","explanation":"Push on the corner of a straw square and it flops flat easily! Push on a straw TRIANGLE and its three sides brace against each other without collapsing! That is why railway bridges (like Howrah Bridge & Bogibeel Bridge), cranes, and electricity towers use triangular trusses!","indianExample":"Look up at the criss-crossing steel triangles next time your train crosses a river bridge!","funFact":"The Eiffel Tower and modern space frames rely on connected triangles to stay light yet super strong!","askNyraPrompt":"NYRA, how can I test triangle vs square paper bridges safely using coins?"}],"activity":{"kind":"classify","title":"Safe Science: Conductor vs Insulator!","instruction":"Sort materials that conduct battery current vs safe protective insulators.","leftBucketLabel":"⚡ Metal Conductor","rightBucketLabel":"🛡️ Safe Insulator","classifyItems":[{"id":"cd1","label":"Copper Wire Core","emoji":"🔌","bucket":"left"},{"id":"cd2","label":"Rubber Wire Jacket","emoji":"🧤","bucket":"right"},{"id":"cd3","label":"Steel Paperclip","emoji":"📎","bucket":"left"},{"id":"cd4","label":"Dry Wooden Ruler","emoji":"📏","bucket":"right"}],"successMessage":"Circuit safety & material science mastered!"},"quiz":[{"id":"st-9-q1","prompt":"Why are copper electrical wires covered outside with rubber or plastic?","emoji":"🧤","options":["Plastic & rubber are insulators that stop shocks from reaching hands","Rubber makes wires heavier","Copper hates air"],"correctAnswer":"Plastic & rubber are insulators that stop shocks from reaching hands","hint":"Conductor inside, protector outside!","explanation":"Insulating coats safely block electric flow from escaping wires."},{"id":"st-9-q2","prompt":"Which shape NEVER squishes flat when pushed at its corners, making it engineers’ favorite for bridges?","emoji":"🌉","options":["Triangle 🔺","Wobbly Square 🟥","Loose Oval"],"correctAnswer":"Triangle 🔺","hint":"Look at railway truss bridges!","explanation":"Triangles distribute weight evenly across all three struts without bending."},{"id":"st-9-q3","prompt":"You touch two AA-battery wires to an LED bulb, yet ONE wire is cut in half. Will it glow?","emoji":"💡","options":["No—it is an open broken circuit so current cannot complete the loop","Yes, brighter than ever","It turns blue"],"correctAnswer":"No—it is an open broken circuit so current cannot complete the loop","hint":"Must form a full unbroken circle!","explanation":"Current needs a continuous closed path from positive to negative terminal."}],"realLifeChallenge":{"title":"Accordion-Fold Paper Bridge Strength Test!","instruction":"Lay 1 flat sheet of paper between two books and test how many coins it holds (it bends!). Now fold that SAME paper accordion-style (zig-zag triangles!) and count how many MORE coins it holds!","familyTip":"Ask why zigzag pleats suddenly give weak paper bridge strength!"},"badge":{"id":"badge-st-9","title":"Bridge & Circuit Builder","emoji":"🌉"}},"10":{"zoneId":"stem_innovation","classAge":10,"className":"5th Class","pedagogyTier":"conceptual","moduleTitle":"Solar System, Scientific Method & Design Thinking","hindiSubtitle":"सौरमंडल, वैज्ञानिक विधि और नवाचार डिज़ाइन सोच","ncertGoalNote":"Solar system scale, fair-test scientific method (variables) & human-centered engineering","lessons":[{"id":"st-10-1","title":"Fair Tests: Change Only ONE Variable at a Time!","hindiTitle":"सही विज्ञान प्रयोग: एक बार में केवल एक बदलाव","emojiVisual":"🪴 Plant A: Water+Sun  |  🪴 Plant B: Water Only  (Keep Soil & Pot SAME!)","explanation":"If you put Plant A in sunshine with lots of fertilizer AND put Plant B in the dark with zero water, you won’t know WHICH factor helped Plant A! In a **Fair Test**, keep everything identical EXCEPT the ONE variable you are testing!","indianExample":"Testing which paper airplane wing flies farthest? Throw both with the SAME gentle wrist speed indoors!","funFact":"Ask Question → Form Hypothesis → Run Fair Test → Measure Data → Share Conclusion!","askNyraPrompt":"NYRA, help me check variables for a fair seed-sprouting experiment at home!"},{"id":"st-10-2","title":"Design Thinking: Invent a Helper for Real People!","hindiTitle":"डिज़ाइन थिंकिंग: असल समस्या का रचनात्मक समाधान","emojiVisual":"1️⃣ Empathize (Listen) ➡️ 2️⃣ Define ➡️ 3️⃣ Sketch Ideas ➡️ 4️⃣ Prototype & Test!","explanation":"Real inventors don’t start with fancy lasers—they start by noticing someone’s daily hassle (e.g., Dada struggling to carry heavy grocery bags up stairs, or stray birds lacking water on hot roofs) and sketching/prototyping cardboard solutions!","indianExample":"India’s Mitticool clay fridge (electricity-free cooling!) was invented by Mansukhbhai Prajapati to help villages keep veggies fresh naturally!","funFact":"If your first cardboard prototype breaks, congratulations—you found what to improve in version 2!","askNyraPrompt":"NYRA, walk me through 4 Design Thinking steps for a classroom waste-sorting bin!"}],"activity":{"kind":"sequence","title":"Order the Design Thinking Innovation Cycle!","instruction":"Put these 4 steps of inventing a useful product in order.","sequenceSteps":[{"id":"dt1","label":"Empathize: Notice Real User Problem","emoji":"👂","order":1},{"id":"dt2","label":"Ideate: Sketch Wild & Practical Ideas","emoji":"💡","order":2},{"id":"dt3","label":"Prototype: Build Rough Paper/Cardboard Model","emoji":"🛠️","order":3},{"id":"dt4","label":"Test & Improve With Feedback!","emoji":"🚀","order":4}],"successMessage":"Young innovator certified! Ready for real-world problem solving!"},"quiz":[{"id":"st-10-q1","prompt":"You want to test if sugar dissolves faster in warm water vs cold water. Which MUST stay the SAME in both cups?","emoji":"🧪","options":["Same cup water volume, same 1-spoon sugar amount & same stirring speed","Use 10 spoons in cold and 1 in warm","Stir one cup and don’t stir the other"],"correctAnswer":"Same cup water volume, same 1-spoon sugar amount & same stirring speed","hint":"Only temperature should change in a Fair Test!","explanation":"Controlling extra variables proves temperature caused the speed difference."},{"id":"st-10-q2","prompt":"Which set orders the 4 inner rocky planets of our Solar System closest to farthest from the Sun?","emoji":"🪐","options":["Mercury, Venus, Earth, Mars","Earth, Mars, Venus, Mercury","Jupiter, Saturn, Earth, Mars"],"correctAnswer":"Mercury, Venus, Earth, Mars","hint":"My Very Educated Mother...","explanation":"Mercury → Venus → Earth → Mars are the 4 inner rocky planets."},{"id":"st-10-q3","prompt":"What is the VERY FIRST step of Design Thinking before drawing an invention?","emoji":"🤝","options":["Listen and empathize with the person facing the problem","Buy expensive metal tools","Write a victory speech"],"correctAnswer":"Listen and empathize with the person facing the problem","hint":"Understand WHO needs help and WHY!","explanation":"Understanding real human needs guarantees inventions actually help people."}],"realLifeChallenge":{"title":"Sketch a Mini Home-Helper Invention","instruction":"Spot 1 tiny hassle at home (tangled charger wires, sparrow water bowl, dark shoe rack) and sketch a labeled invention diagram using cardboard/recycled parts!","familyTip":"Ask your child: \"What failed on try #1 and how would you improve v2?\""},"badge":{"id":"badge-st-10","title":"Young Innovator","emoji":"🚀"}}}};
